loring\";s:5:\"light\";s:15:\"editor_coloring\";s:5:\"light\";s:11:\"fontsize_pc\";s:4:\"14px\";s:11:\"fontsize_sp\";s:4:\"13px\";s:11:\"font_family\";s:82:\"Menlo, Consolas, \"Hiragino Kaku Gothic ProN\", \"Hiragino Sans\", Meiryo, sans-serif;\";s:14:\"prism_css_path\";s:0:\"\";s:13:\"prism_js_path\";s:0:\"\";}','auto'),(199,'_transient_jetpack_autoloader_plugin_paths','a:2:{i:0;s:26:\"{{WP_PLUGIN_DIR}}/knit-pay\";i:1;s:26:\"{{WP_PLUGIN_DIR}}/mailpoet\";}','on'),(200,'nsl-version','3.1.26','on'),(202,'pmpro_restricted_files_random_string','0391741630','auto'),(203,'pmpro_undeprecated_gateways','a:0:{}','auto'),(204,'widget_pmpro-member-login','a:1:{s:12:\"_multiwidget\";i:1;}','auto'),(209,'pmpro_account_page_id','17','auto'),(210,'pmpro_billing_page_id','18','auto'),(211,'pmpro_cancel_page_id','19','auto'),(212,'pmpro_checkout_page_id','20','auto'),(213,'pmpro_confirmation_page_id','21','auto'),(214,'pmpro_invoice_page_id','22','auto'),(215,'pmpro_levels_page_id','23','auto'),(216,'pmpro_login_page_id','24','auto'),(217,'pmpro_member_profile_edit_page_id','25','auto'),(218,'codesblock_membership_levels','a:4:{s:7:\"starter\";i:1;s:3:\"pro\";i:2;s:8:\"lifetime\";i:3;s:10:\"pro_annual\";i:4;}','off'),(219,'cbcommerce_social_flow_page_id','27','off'),(220,'codesblock_ai_agents_course_id','28','off'),(221,'cbcommerce_setup_version','1.6.1','off'),(222,'action_scheduler_lock_async-request-runner','6a885e4153d4d7.10311024|1787321981','no'),(223,'pmpro_library_conflicts','a:1:{s:16:\"action-scheduler\";a:1:{s:115:\"C:/Users/pulki/Local Sites/codesblock/app/public/wp-content/plugins/knit-pay/packages/woocommerce/action-scheduler/\";a:2:{s:7:\"version\";s:5:\"3.9.3\";s:9:\"timestamp\";s:19:\"2026-09-02 13:41:02\";}}}','off'),(226,'widget_mailpoet_form','a:1:{s:12:\"_multiwidget\";i:1;}','auto'),(227,'widget_nextend_social_login','a:1:{s:12:\"_multiwidget\";i:1;}','auto'),(233,'pmpro_license_check','a:2:{s:7:\"license\";b:0;s:7:\"enddate\";i:0;}','off'),(234,'wisdom_notification_times','a:1:{s:20:\"paid-memberships-pro\";i:1784304889;}','auto'),(235,'pmpro_addons_timestamp','1788356040','off'),(236,'pmpro_addons','a:124:{i:0;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Abandoned Cart Recovery\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Abandoned Cart Recovery\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/abandoned-cart-recovery/\";s:4:\"Slug\";s:29:\"pmpro-abandoned-cart-recovery\";s:6:\"plugin\";s:63:\"pmpro-abandoned-cart-recovery/pmpro-abandoned-cart-recovery.php\";s:7:\"Version\";s:5:\"1.0.3\";s:11:\"Description\";s:109:\"Recover lost revenue by capturing abandoned carts and following up with customers to complete their purchase.\";s:12:\"Installation\";s:237:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-abandoned-cart-recovery</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:335:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-abandoned-cart-recovery/issues\">https://github.com/strangerstudios/pmpro-abandoned-cart-recovery/issues</a></p>\";s:9:\"Changelog\";s:530:\"<h4>Changelog</h4><p>1.0.3 - 2026-05-01</p><ul>\n<li>ENHANCEMENT: Recovery reminder emails are now scheduled via Action Scheduler when running PMPro 3.5 or newer. Sites on older versions continue to use WP-Cron. #17 (@andrewlimaza)</li>\n<li>ENHANCEMENT: Updated the default subject and body for the three recovery reminder email templates to use Liquid (<code>{{ variable }}</code>) syntax on PMPro 3.7 and newer. Older PMPro versions continue to receive the legacy <code>!!variable!!</code> defaults. #18 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:90:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-abandoned-cart-recovery.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:23:\"Abandoned Cart Recovery\";}i:1;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Add Member From Admin\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Add Member From Admin\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/add-member-admin-add-on/\";s:4:\"Slug\";s:22:\"pmpro-add-member-admin\";s:6:\"plugin\";s:49:\"pmpro-add-member-admin/pmpro-add-member-admin.php\";s:7:\"Version\";s:5:\"0.7.4\";s:11:\"Description\";s:48:\"Allow admins to add members in the WP dashboard.\";s:12:\"Installation\";s:502:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-add-member-admin</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Memberships -&gt; Add Member to add a new member.</li>\n<li>When viewing the member\'s list or user\'s list in the dashboard a \"+ order\" link will show up under the username that can be used to add a new order for an existing user through the same form.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1045:\"<h4>Changelog</h4><p>0.7.4 - 2026-08-19</p><ul>\n<li>SECURITY: Now validating the submitted role against <code>get_editable_roles()</code> when adding a member so that users cannot create accounts with roles they are not allowed to assign. #65 (@flintfromthebasement)</li>\n</ul><p>0.7.3 - 2026-05-20</p><ul>\n<li>SECURITY: Added nonce verification to the Add Member admin form to prevent CSRF. #64 (@dparker1005)</li>\n<li>BUG FIX: Prevented the +order workflow from changing an existing user\'s membership level. #54 (@andrewlimaza)</li>\n</ul><p>0.7.2 - 2024-01-25</p><ul>\n<li>SECURITY: Improved sanitization and escaping throughout the plugin. #56 (@JarrydLong)</li>\n<li>ENHANCEMENT: Added a link to the Edit Member page if using PMPro v3.0+. #60 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Added some missing email template variables to the \"add member added admin\" email. #55 (@andrewlimaza)</li>\n<li>BUG FIX/ENHANCEMENT: Marking plugin as incompatible with Multiple Memberships Per User for the PMPro v3.0 update. #59 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-add-member-admin.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:21:\"Add Member From Admin\";}i:2;a:16:{s:4:\"Name\";s:43:\"Paid Memberships Pro - Add Name to Checkout\";s:5:\"Title\";s:43:\"Paid Memberships Pro - Add Name to Checkout\";s:9:\"PluginURI\";s:75:\"https://www.paidmembershipspro.com/add-ons/add-first-last-name-to-checkout/\";s:4:\"Slug\";s:26:\"pmpro-add-name-to-checkout\";s:6:\"plugin\";s:57:\"pmpro-add-name-to-checkout/pmpro-add-name-to-checkout.php\";s:7:\"Version\";s:5:\"0.7.3\";s:11:\"Description\";s:97:\"Adds first and last name fields to the user account section at checkout for Paid Memberships Pro.\";s:12:\"Installation\";s:272:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-add-name-to-checkout</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:575:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-add-name-to-checkout/issues\">https://github.com/strangerstudios/pmpro-add-name-to-checkout/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:196:\"<h4>Changelog</h4><p>0.7.3 - 2026-06-12</p><ul>\n<li>BUG FIX: Fixed an issue where the first and last name weren\'t being truly required at checkout for certain cases. #46 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:87:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-add-name-to-checkout.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Add Name to Checkout\";}i:3;a:16:{s:4:\"Name\";s:48:\"Paid Memberships Pro - Add PayPal Express Add On\";s:5:\"Title\";s:48:\"Paid Memberships Pro - Add PayPal Express Add On\";s:9:\"PluginURI\";s:84:\"https://www.paidmembershipspro.com/add-ons/pmpro-add-paypal-express-option-checkout/\";s:4:\"Slug\";s:24:\"pmpro-add-paypal-express\";s:6:\"plugin\";s:53:\"pmpro-add-paypal-express/pmpro-add-paypal-express.php\";s:7:\"Version\";s:5:\"0.7.1\";s:11:\"Description\";s:49:\"Add PayPal Express as a Second Option at Checkout\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:85:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-add-paypal-express.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:18:\"Add PayPal Express\";}i:4;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - Addon Packages\";s:5:\"Title\";s:37:\"Paid Memberships Pro - Addon Packages\";s:9:\"PluginURI\";s:82:\"https://www.paidmembershipspro.com/add-ons/pmpro-purchase-access-to-a-single-page/\";s:4:\"Slug\";s:20:\"pmpro-addon-packages\";s:6:\"plugin\";s:45:\"pmpro-addon-packages/pmpro-addon-packages.php\";s:7:\"Version\";s:5:\"0.9.2\";s:11:\"Description\";s:95:\"Sell members-only access to individual pages or posts, or sell a la carte items for a flat fee.\";s:12:\"Installation\";s:280:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-addon-packages</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit a post or page to set a price for it.</li>\n</ol>\";s:3:\"FAQ\";s:810:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-addon-packages/issues\">https://github.com/strangerstudios/pmpro-addon-packages/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\n<p>Please Note: This plugin is meant as a temporary solution. Most updates and fixes will be reserved for when this functionality is built into Paid Memberships Pro. We may not fix the pmpro-addon-packages plugin itself unless it is critical.</p>\";s:9:\"Changelog\";s:534:\"<h4>Changelog</h4><p>0.9.2 - 2026-05-04</p><ul>\n<li>BUG FIX: Levels that no longer allow signups are now skipped when generating the addon package checkout link. #72 (@dwanjuki)</li>\n<li>BUG FIX: Resolved a fatal error that could occur on the addon package checkout page when an existing member\'s only matching level had signups disabled. #72 (@dwanjuki)</li>\n<li>BUG FIX: Fixed an \"Undefined array key\" PHP warning on the orders admin page when order notes did not match the expected Addon Package pattern. #73 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:81:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-addon-packages.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"Addon Packages\";}i:5;a:16:{s:4:\"Name\";s:53:\"Paid Memberships Pro - Address For Free Levels Add On\";s:5:\"Title\";s:53:\"Paid Memberships Pro - Address For Free Levels Add On\";s:9:\"PluginURI\";s:92:\"https://www.paidmembershipspro.com/add-ons/capture-name-address-free-levels-offsite-gateway/\";s:4:\"Slug\";s:29:\"pmpro-address-for-free-levels\";s:6:\"plugin\";s:63:\"pmpro-address-for-free-levels/pmpro-address-for-free-levels.php\";s:7:\"Version\";s:5:\"0.6.2\";s:11:\"Description\";s:66:\"Show address fields for free levels also with Paid Memberships Pro\";s:12:\"Installation\";s:237:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-address-for-free-levels</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:830:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-address-for-free-levels/issues\">https://github.com/strangerstudios/pmpro-address-for-free-levels/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\n<p>Please Note: This plugin is meant as a temporary solution. Most updates and fixes will be reserved for when this functionality is built into Paid Memberships Pro. We may not fix the pmpro-addon-packages plugin itself unless it is critical.</p>\";s:9:\"Changelog\";s:199:\"<h4>Changelog</h4><p>0.6.2 - 2026-01-20</p><ul>\n<li>BUG FIX: Fixes an issue where the default test gateway would not interfere with free checkouts, and possibly other gateways. (@WTEK-PW3)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:90:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-address-for-free-levels.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:23:\"Address For Free Levels\";}i:6;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Advanced Levels Page Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Advanced Levels Page Add On\";s:9:\"PluginURI\";s:75:\"https://www.paidmembershipspro.com/add-ons/pmpro-advanced-levels-shortcode/\";s:4:\"Slug\";s:31:\"pmpro-advanced-levels-shortcode\";s:6:\"plugin\";s:67:\"pmpro-advanced-levels-shortcode/pmpro-advanced-levels-shortcode.php\";s:7:\"Version\";s:5:\"1.2.1\";s:11:\"Description\";s:106:\"Build a beautiful membership levels page for Paid Memberships Pro using a customizable block or shortcode.\";s:12:\"Installation\";s:615:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-advanced-levels</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Replace the [pmpro_levels] shortcode on your site with the Advanced Levels Page block or [pmpro_advanced_levels] shortcode.</li>\n</ol>\n<p>For more information about block settings and shortcode attributes, see the documentation here:\n<a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-advanced-levels-shortcode/\">https://www.paidmembershipspro.com/add-ons/pmpro-advanced-levels-shortcode/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:890:\"<h4>Changelog</h4><p>1.2.1 - 2026-05-01</p><ul>\n<li>ENHANCEMENT: Improved accessibility of the level buttons with state-aware <code>aria-label</code> text for select, renew, and account actions. #74 (@kimcoleman)</li>\n<li>ENHANCEMENT: Improved accessibility of the empty header cell in the table layout by replacing <code>&amp;nbsp;</code> with screen-reader-only \"Action\" text. #74 (@kimcoleman)</li>\n<li>BUG FIX: Resolved \"Undefined array key\" warnings and orphan columns in the compare table layout, and stopped the small-screen view from overriding values from the <code>pmpro_advanced_levels_compare_items</code> filter. #80 (@dwanjuki)</li>\n<li>BUG FIX: Resolved deprecation warnings in the browser console for the Advanced Levels Page block by adding <code>__next40pxDefaultSize</code> and <code>__nextHasNoMarginBottom</code> props to the editor controls. #79 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:92:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-advanced-levels-shortcode.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Advanced Levels Page\";}i:7;a:16:{s:4:\"Name\";s:40:\"Paid Memberships Pro - Affiliates Add On\";s:5:\"Title\";s:40:\"Paid Memberships Pro - Affiliates Add On\";s:9:\"PluginURI\";s:80:\"https://www.paidmembershipspro.com/add-ons/pmpro-lightweight-affiliate-tracking/\";s:4:\"Slug\";s:16:\"pmpro-affiliates\";s:6:\"plugin\";s:37:\"pmpro-affiliates/pmpro-affiliates.php\";s:7:\"Version\";s:3:\"0.8\";s:11:\"Description\";s:82:\"Create affiliate accounts with unique referrer URLs to track membership checkouts.\";s:12:\"Installation\";s:741:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-affiliates</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Manage affiliates through the \"affiliates\" admin page added under Memberships.</li>\n<li>Affiliate URLs will look like <a href=\"http://site.com/?pa=AFFILIATECODE\">http://site.com/?pa=AFFILIATECODE</a></li>\n<li>You can add a \"subid\" to the URL on the fly for more granular tracking <a href=\"http://site.com/?pa=AFFILIATECODE&amp;subid=TEST1\">http://site.com/?pa=AFFILIATECODE&amp;subid=TEST1</a></li>\n<li>Create a page with the [pmpro_affiliates_report] shortcode and direct your affiliate users to that page.</li>\n</ol>\";s:3:\"FAQ\";s:555:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-affiliates/issues\">https://github.com/strangerstudios/pmpro-affiliates/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:481:\"<h4>Changelog</h4><p>0.8 - 2026-03-19</p><ul>\n<li>ENHANCEMENT: Retroactively create affiliates for any member that belongs to a level with the \"Automatically create affiliate code?\" option enabled. (@andrewlimaza)</li>\n<li>ENHANCEMENT: Added an Affiliate Edit Member Panel screen for all affiliate users with pagination. (@andrewlimaza, @jahidhasan018)</li>\n<li>ENHANCEMENT: General improvements to the admin UI as well as helpful links added in the admin. (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:77:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-affiliates.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:10:\"Affiliates\";}i:8;a:16:{s:4:\"Name\";s:42:\"Paid Memberships Pro - Akismet Integration\";s:5:\"Title\";s:42:\"Paid Memberships Pro - Akismet Integration\";s:9:\"PluginURI\";s:57:\"https://www.paidmembershipspro.com/add-ons/pmpro-akismet/\";s:4:\"Slug\";s:13:\"pmpro-akismet\";s:6:\"plugin\";s:31:\"pmpro-akismet/pmpro-akismet.php\";s:7:\"Version\";s:3:\"1.1\";s:11:\"Description\";s:86:\"Protect your membership site from checkout spam with Akismet and Paid Memberships Pro.\";s:12:\"Installation\";s:1545:\"<p>Installation</p><p>Note: You must have <a href=\"https://wordpress.org/plugins/paid-memberships-pro/\">Paid Memberships Pro</a> and <a href=\"https://wordpress.org/plugins/akismet/\">Akismet</a> installed and activated on your site.</p>\n<h3>Install PMPro Akismet from within WordPress</h3>\n<ol>\n<li>Make sure Paid Memberships Pro is active.</li>\n<li>Visit Memberships &gt; Add Ons</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - Akismet Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro Akismet Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-akismet</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - Akismet Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: How to Use</h3>\n<p>This plugin relies on the settings you have configured within the main Akismet plugin.</p>\n<p>Navigate to Settings &gt; Akismet Anti-Spam to configure your general Akismet settings.</p>\n<p>PMPro Akismet will automatically detect spam at checkout and prevent submissions if they are considered spam. If you have enabled the setting to \"Display a privacy notice under your comment forms,\" this message will also display on your membership checkout page.</p>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-akismet/\">https://www.paidmembershipspro.com/add-ons/pmpro-akismet/</a>.</p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:732:\"<h4>Changelog</h4><p>1.1 - 2024-08-12</p><ul>\n<li>FEATURE: Now only blocking \"definite\" spam. For \"likely spam\", users are prompted to checkout again.</li>\n<li>ENHANCEMENT: Now always tracking likely spam responses from Akismet as \"spam activity\" for the PMPro spam blocker. Folks testing cards on checkout pages are blocked twice as fast now.</li>\n<li>ENHANCEMENT: You can use the <code>pmpro_akismet_threshold</code> filter and have it return 1 instead of 2 to use the stricter rules where all likely spam is treated as spam and blocked.</li>\n<li>ENHANCEMENT/BUG FIX: Fixed formatting of the Akismet link if shown via the <code>pmpro_akismet_checkout_privacy_notice</code> filter. Have that return \'display\' to display.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:71:\"https://license.paidmembershipspro.com/downloads/free/pmpro-akismet.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:19:\"Akismet Integration\";}i:9;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Approvals Add On\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Approvals Add On\";s:9:\"PluginURI\";s:71:\"https://www.paidmembershipspro.com/add-ons/approval-process-membership/\";s:4:\"Slug\";s:15:\"pmpro-approvals\";s:6:\"plugin\";s:35:\"pmpro-approvals/pmpro-approvals.php\";s:7:\"Version\";s:3:\"1.8\";s:11:\"Description\";s:75:\"Grants administrators the ability to approve/deny memberships after signup.\";s:12:\"Installation\";s:1053:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-approvals/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>How to Use</p><ol>\n<li>To set a level\'s approval requirements, edit your membership level and adjust the settings under \"Approval Settings\".</li>\n<li>To process membership approvals, navigate to the Approvals Dashboard under Memberships &gt; Approvals.</li>\n<li>To customize the emails related to this plugin, navigate to Memberships &gt; Settings &gt; Email Templates in the WordPress admin.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/approval-process-membership/\">https://www.paidmembershipspro.com/add-ons/approval-process-membership/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:949:\"<h4>Changelog</h4><p>1.8 - 2026-06-10</p><ul>\n<li>ENHANCEMENT: Modernized the Approvals admin list with level and status filters, responsive table, colored status badges, item count, and standard pagination. Approval status is no longer combined with Email Confirmation status. #221 (@kimcoleman)</li>\n<li>ENHANCEMENT: Rebuilt the application view into the standard PMPro two-column layout with breadcrumb navigation, inline Approve / Deny / Reset actions, read-only user fields, and a Member Information sidebar. #221 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added an Approvals panel to the Edit Member screen listing the member\'s applications and full approval history. #221 (@kimcoleman)</li>\n<li>ENHANCEMENT: Account page now displays approval status for Pending and Denied members using newer hooks. Requires PMPro 3.4+. #221 (@kimcoleman)</li>\n<li>ENHANCEMENT: getApprovalCount() now supports all as a status argument. #221 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:76:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-approvals.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Approvals\";}i:10;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Auto-Renewal Checkbox\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Auto-Renewal Checkbox\";s:9:\"PluginURI\";s:85:\"https://www.paidmembershipspro.com/add-ons/auto-renewal-checkbox-membership-checkout/\";s:4:\"Slug\";s:27:\"pmpro-auto-renewal-checkbox\";s:6:\"plugin\";s:59:\"pmpro-auto-renewal-checkbox/pmpro-auto-renewal-checkbox.php\";s:7:\"Version\";s:5:\"0.4.2\";s:11:\"Description\";s:55:\"Make auto-renewal optional at checkout with a checkbox.\";s:12:\"Installation\";s:307:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-auto-renewal-checkbox</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit your membership levels and set the \"Auto Renewal\" options for each level.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:197:\"<h4>Changelog</h4><p>0.4.2 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Added a \"Learn more\" link to the Auto-Renewal Settings section on the Edit Membership Level admin page. #41 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:88:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-auto-renewal-checkbox.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:21:\"Auto-Renewal Checkbox\";}i:11;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - AvaTax Add On\";s:5:\"Title\";s:36:\"Paid Memberships Pro - AvaTax Add On\";s:9:\"PluginURI\";s:69:\"https://www.paidmembershipspro.com/add-ons/avalara-avatax-integration\";s:4:\"Slug\";s:12:\"pmpro-avatax\";s:6:\"plugin\";s:29:\"pmpro-avatax/pmpro-avatax.php\";s:7:\"Version\";s:3:\"0.1\";s:11:\"Description\";s:74:\"Integrate with Avalara AvaTax for automated sales and use tax calculation.\";s:12:\"Installation\";s:889:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n<li>You must have a <a href=\"https://www.avalara.com\">subscription with Avalara</a> to use this service.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-avatax/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>Settings</p><ol>\n<li>Navigate to Memberships &gt; AvaTax in the WordPress admin.</li>\n<li>Complete the fields in the \"Credentials\" section to connect your membership site to your Avalara account.</li>\n<li>Complete the fields with your \"Company\" information and configure additional options.</li>\n<li>Save settings.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:61:\"<h4>Changelog</h4><p>0.1</p><ul>\n<li>First commit.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:70:\"https://license.paidmembershipspro.com/downloads/free/pmpro-avatax.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:6:\"AvaTax\";}i:12;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - AWeber Add On\";s:5:\"Title\";s:36:\"Paid Memberships Pro - AWeber Add On\";s:9:\"PluginURI\";s:68:\"https://www.paidmembershipspro.com/add-ons/pmpro-aweber-integration/\";s:4:\"Slug\";s:12:\"pmpro-aweber\";s:6:\"plugin\";s:29:\"pmpro-aweber/pmpro-aweber.php\";s:7:\"Version\";s:3:\"1.4\";s:11:\"Description\";s:70:\"Add users and members to AWeber lists based on their membership level.\";s:12:\"Installation\";s:1319:\"<p>Installation</p><p>This plugin works with and without Paid Memberships Pro installed.</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-aweber</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Settings &gt; PMPro Aweber to proceed with setup.</li>\n</ol><p>Configuration and Settings</p><p><strong>Authorize your app with AWeber:</strong> Your Authorization Code will be provided once the app is authorized with your AWeber account. Navigate to Settings &gt; PMPro AWeber in the WordPress dashboard to authorize your app with AWeber.</p>\n<p>After entering your Authorization Code, continue with the setup by assigning All User Lists, Membership Level Lists, and review the additional settings.</p>\n<p>For full documentation on all settings, please visit the <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-aweber-integration/\">AWeber Integration Add On documentation page at Paid Memberships Pro</a>. </p>\n<p>Filter hooks are available for developers that need to customize specific aspects of the integration. <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-aweber-integration/#hooks\">Please explore the plugin\'s action and filter hooks here</a>.</p>\";s:3:\"FAQ\";s:547:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-aweber/issues\">https://github.com/strangerstudios/pmpro-aweber/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:195:\"<h4>Changelog</h4><p>1.4 - 2024-10-17</p><ul>\n<li>FEATURE: Now updating the plugin from paidmembershipspro.com.</li>\n<li>ENHANCEMENT: Updated translation files bundled with the plugin.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:70:\"https://license.paidmembershipspro.com/downloads/free/pmpro-aweber.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:6:\"AWeber\";}i:13;a:16:{s:4:\"Name\";s:18:\"Basic User Avatars\";s:5:\"Title\";s:18:\"Basic User Avatars\";s:9:\"PluginURI\";s:49:\"https://wordpress.org/plugins/basic-user-avatars/\";s:4:\"Slug\";s:18:\"basic-user-avatars\";s:6:\"plugin\";s:41:\"basic-user-avatars/basic-user-avatars.php\";s:7:\"Version\";s:5:\"1.0.8\";s:11:\"Description\";s:111:\"Add an avatar upload field on frontend pages and Edit Profile screen so users can add a custom profile picture.\";s:12:\"Installation\";s:1109:\"<p>Installation</p><ol>\n<li>Upload <code>basic-user-avatars</code> to your <code>/wp-content/plugins/</code> directory or download through the Plugins page.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>If you only want users with file upload capabilities to upload avatars, check the applicable option under Settings &gt; Discussion.</li>\n<li>Navigate to Users &gt; Edit User to upload a custom avatar for your users.</li>\n<li>Add the <code>[basic-user-avatars]</code> shortcode to a page in your WordPress site to allow front-end avatar upload for your users.</li>\n</ol>\n<p>bbPress support is added automatically if bbPress is activated.</p>\n<p><strong><a href=\"https://github.com/strangerstudios/basic-user-avatars/\">This plugin is on GitHub</a></strong> and pull requests are welcome. If possible please report issues through Github.</p>\n<p>Note: This plugin is a fork of Simple Local Avatars v1.3.1 by Jake Goldman and 10up. Check out <a href=\"http://wordpress.org/plugins/simple-local-avatars\">Simple Local Avatars</a> to compare their latest release to this plugin.</p>\";s:3:\"FAQ\";s:578:\"<p>Frequently Asked Questions</p><p>I\'m still having problems</p><p>While this plugin has been tested with common server setups, some enviroments could cause an issue.</p>\n<p>If you are having a problem deactivate all plugins other than this one and then switch your theme to TwentyTweleve (or similar). If things work, then the issue is with a 3rd party theme or plugin.</p>\n<p>If things are still not functioning properly then proceed to reporting an issue. The ideal method is via <a href=\"https://github.com/strangerstudios/basic-user-avatars/issues/\">GitHub issues</a>.</p>\";s:9:\"Changelog\";s:506:\"<h4>Changelog</h4><p>1.0.8 - 2024-01-23</p><ul>\n<li>ENHANCEMENT: Added filter \'basic_user_avatars_default_size\' to allow changing the default size of the avatar. (Thanks @jarrydlong)</li>\n<li>ENHANCEMENT: Improved functionality on how we load the text domain of the plugin for translations. (@ipokkel)</li>\n<li>BUG FIX: Fixed a fatal issue when the option \"Only allow users with file upload capabilities to upload local avatars (Authors and above)\" wasn\'t set on new installations. (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:32:\"https://www.strangerstudios.com/\";s:8:\"Download\";s:61:\"https://downloads.wordpress.org/plugin/basic-user-avatars.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:18:\"Basic User Avatars\";}i:14;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - bbPress Add On\";s:5:\"Title\";s:37:\"Paid Memberships Pro - bbPress Add On\";s:9:\"PluginURI\";s:57:\"https://www.paidmembershipspro.com/add-ons/pmpro-bbpress/\";s:4:\"Slug\";s:13:\"pmpro-bbpress\";s:6:\"plugin\";s:31:\"pmpro-bbpress/pmpro-bbpress.php\";s:7:\"Version\";s:5:\"1.9.1\";s:11:\"Description\";s:104:\"Restrict access to bbPress for free or premium members by integrating bbPress with Paid Memberships Pro.\";s:12:\"Installation\";s:2391:\"<p>Installation</p><p>Note: You must have <a href=\"https://www.paidmembershipspro.com\">Paid Memberships Pro</a> and <a href=\"https://wordpress.org/plugins/bbpress/\">bbPress</a> installed and activated on your site.</p>\n<h3>Install PMPro bbPress from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro bbPress\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - bbPress Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro bbPress Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-bbpress</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - bbPress Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Create a Private Forum</h3>\n<ol>\n<li>Navigate to Forums &gt; Edit Forum to restrict access to the forum and make it private.</li>\n<li>Or, create a new Forum under Forums &gt; Add New.</li>\n<li>In the right column \"Settings\" panel, locate the \"Require Membership\" section.</li>\n<li>Check the box for one or more membership level that can access this forum.</li>\n<li>Save your changes by clicking the \"Update\" button (or \"Publish\" if you are creating a new forum).</li>\n<li>Further settings can be found on the Settings &gt; Forums page of your admin dashboard.</li>\n</ol>\n<h3>Shortcode for Member Activity</h3>\n<p>The bbPress Integration for Paid Memberships Pro includes one shortcode to display a member\'s activity (topics or replies created).</p><p>Sample shortcode usage:</p><p><code>[bbp-user-activity activity_type=\"topic\" show_date=\"true\" title=\"My Recent Topics\"]</code></p><p>Shortcode attributes include:</p><ul>\n<li>activity_type: Accepts \'topic\' or \'reply\'. Default is \'topic\'</li>\n<li>bbp_user_id: Accepts any user ID. Omit this attribute to load the current user\'s entries. Default is the <code>current_user-&gt;ID</code>.</li>\n<li>count: The number of entries to show. Default is \'5\'.</li>\n<li>show_date: Optionally show the entry date. Default is \'false\'.</li>\n<li>show_excerpt: Optionally show a 50-character excerpt of the entry. Default is \'false\'.</li>\n<li>title: An optional title for the shortcode output, wrapped in the h2 class=\"widgettitle\" format.</li>\n</ul>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1353:\"<h4>Changelog</h4><p>1.9.1 - 2026-07-20</p><ul>\n<li>BUG FIX: Membership level changes no longer overwrite forum roles assigned manually. Levels set to \"Preserve Current Forum Role\" no longer force members back to the default role, and members with multiple levels now receive the forum role with the most enabled capabilities. #52 (@kimcoleman)</li>\n</ul><p>1.9 - 2026-06-18</p><ul>\n<li>FEATURE: Added a \"Memberships\" &gt; \"Forums\" settings page that consolidates all Add On settings: per-forum membership restrictions, the general forum settings previously found on the bbPress &gt; Settings screen, and links to level-specific settings. Compatible with bbPress and BuddyBoss Platform. The bbPress &gt; Settings screen now shows a Paid Memberships Pro section linking to the new page.</li>\n<li>ENHANCEMENT: Visitors without access to a single forum are now redirected to the \"Access Restricted\" page registered by the PMPro BuddyPress Add On if one is set. Applies on BuddyPress and BuddyBoss sites.</li>\n<li>ENHANCEMENT: When BuddyBoss Platform is active, the no access message is no longer shown for individual restricted forums on the forum archive page.</li>\n</ul><p>1.8 -2024-10-21</p><ul>\n<li>FEATURE: Now updating the plugin from paidmembershipspro.com</li>\n<li>ENHANCEMENT: Added Swedish, Dutch and Portguese (Brazil) language files.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:70:\"http://license.paidmembershipspro.com/downloads/free/pmpro-bbpress.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:7:\"bbPress\";}i:15;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Better Logins Report Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Better Logins Report Add On\";s:9:\"PluginURI\";s:64:\"http://www.paidmembershipspro.com/wp/pmpro-better-logins-report/\";s:4:\"Slug\";s:26:\"pmpro-better-logins-report\";s:6:\"plugin\";s:57:\"pmpro-better-logins-report/pmpro-better-logins-report.php\";s:7:\"Version\";s:6:\".2.3.2\";s:11:\"Description\";s:66:\"Adds login, view, and visit stats for \"This Week\" and \"This Year\".\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:88:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-better-logins-report.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:20:\"Better Logins Report\";}i:16;a:16:{s:4:\"Name\";s:52:\"Paid Memberships Pro - BuddyPress & BuddyBoss Add On\";s:5:\"Title\";s:52:\"Paid Memberships Pro - BuddyPress & BuddyBoss Add On\";s:9:\"PluginURI\";s:65:\"https://www.paidmembershipspro.com/add-ons/buddypress-integration\";s:4:\"Slug\";s:16:\"pmpro-buddypress\";s:6:\"plugin\";s:37:\"pmpro-buddypress/pmpro-buddypress.php\";s:7:\"Version\";s:3:\"1.6\";s:11:\"Description\";s:84:\"Restrict access to your BuddyPress or BuddyBoss Community using Paid Memberships Pro\";s:12:\"Installation\";s:4616:\"<p>Installation</p><p>Note: You must have <a href=\"https://www.paidmembershipspro.com\">Paid Memberships Pro</a> and <a href=\"https://wordpress.org/plugins/buddypress/\">BuddyPress</a> or <a href=\"https://www.paidmembershipspro.com/buddyboss-membership-plugin/?utm_source=pmpro-buddypress-readme&amp;utm_medium=readme&amp;utm_campaign=pmpro-buddypress\">BuddyBoss</a> installed and activated on your site.</p>\n<h3>Install PMPro BuddyPress from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro BuddyPress\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - BuddyPress Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro BuddyPress Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-buddypress</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - BuddyPress Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Configure Plugin Settings</h3>\n<p>There are four primary settings areas in this plugin.</p><ol>\n<li>Select Your Preferred Registration Process</li>\n</ol><p>This plugin allows you to use the BuddyPress or BuddyBoss user registration process (in place of the standard Paid Memberships Pro membership checkout process).</p>\n<ol>\n<li>Navigate to Memberships &gt; PMPro BuddyPress in the WordPress admin.</li>\n<li>Change the \"Registration Page\" setting to \"Use BuddyPress Registration Page\".</li>\n<li>Save Settings.</li>\n</ol>\n<p>Note: If your membership is not free, you must use the Paid Memberships Pro membership checkout process. If you have a free community and want to allow users to register through BuddyPress or BuddyBoss, you must adjust this setting.</p>\n<p>If you\'d like members that register through the BuddyPress or BuddyBoss system to also be given a membership level, check out this guide on <a href=\"https://www.paidmembershipspro.com/apply-a-buddypress-member-type-on-membership-checkout-or-level-change/?utm_source=pmpro-buddypress-readme&amp;utm_medium=readme&amp;utm_campaign=pmpro-buddypress\">setting a default level for all user registrations in WordPress</a>.</p><ol start=\"2\">\n<li>Assign the \"Access Restricted\" Page</li>\n</ol><p>Navigate to Memberships &gt; Settings &gt; Pages to create or edit the \"Access Restricted\" page.</p>\n<p>This is the page that visitors and users are redirected to if they cannot access restricted BuddyPress or BuddyBoss features.</p><ol start=\"3\">\n<li>Configure Membership Level Settings</li>\n</ol><p>Navigate to Memberships &gt; Settings &gt; Membership Levels and locate the \"BuddyPress Restrictions\" section.</p>\n<p>From this section you can adjust settings for how you \"unlock BuddyPress\" for members of this level, including:</p>\n<ul>\n<li>Group Creation</li>\n<li>Single Group Viewing</li>\n<li>Groups Page Viewing</li>\n<li>Joining Groups</li>\n<li>Public Messaging</li>\n<li>Private Messaging</li>\n<li>Send Friend Requests</li>\n<li>Include in Member Directory</li>\n</ul>\n<p>Next, adjust the \"BuddyPress Group Membership\" settings to add or invite members of this level to your existing BuddyPress Groups.</p>\n<p>If you want to adjust BuddyPress Member Types, you must first create the types through custom code. <a href=\"https://www.paidmembershipspro.com/apply-a-buddypress-member-type-on-membership-checkout-or-level-change/?utm_source=pmpro-buddypress-readme&amp;utm_medium=readme&amp;utm_campaign=pmpro-buddypress\">This post explains how to add Member Types to BuddyPress</a>.</p>\n<p><a href=\"https://www.paidmembershipspro.com/add-ons/buddypress-integration/#members?utm_source=pmpro-buddypress-readme&amp;utm_medium=readme&amp;utm_campaign=pmpro-buddypress\">Read our full documentation on Membership Level Settings for your BuddyPress or BuddyBoss community here</a>.</p><ol start=\"4\">\n<li>Configure Settings for Logged in Non Members</li>\n</ol><p>Some of your WordPress users may not have a membership level in Paid Memberships Pro. This plugin allows you to set how BuddyPress should be locked down for these users without a membership level.</p>\n<p>Navigate to Memberships &gt; Settings &gt; PMPro BuddyPress and locate the \"Non-member User Settings\" section.</p>\n<p><a href=\"https://www.paidmembershipspro.com/add-ons/buddypress-integration/#non_member_user?utm_source=pmpro-buddypress-readme&amp;utm_medium=readme&amp;utm_campaign=pmpro-buddypress\">Read our full documentation on Non-Member Users in BuddyPress or BuddyBoss here</a>.</p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1573:\"<h4>Changelog</h4><p>1.6 - 2026-06-19</p><ul>\n<li>ENHANCEMENT: Improved overall UI/UX for PMPro BuddyPress settings page. Includes new sections for XProfile Field Mapping to sync User Fields and XProfile fields and Membership Level Settings to give a quick overview of level related BuddyPress settings and restrictions.</li>\n<li>ENHANCEMENT: Added support for granular access to view and upload Documents in BuddyBoss and BuddyPress Docs plugin.</li>\n</ul><p>1.5.2 - 2026-05-07</p><ul>\n<li>ENHANCEMENT: Added a link to the Paid Memberships Pro documentation for the BuddyPress Integration Add On in the Edit Level settings. #126 (@kimcoleman)</li>\n<li>BUG FIX: Fixed a conflict with the BP Profile Search plugin where searches that returned no matches would show all members of the level, and ensured the directory remains correctly locked to PMPro members when the include filter is otherwise empty. #118 (@kasperaitis)</li>\n</ul><p>1.5.1 - 2025-03-12</p><ul>\n<li>BUG FIX/ENHANCEMENT: No longer calling <code>pmpro_bp_get_members_in_directory()</code> on pages that do not need that data. #121 (@dparker1005)</li>\n<li>BUG FIX: Fixed an issue that could cause xProfile fields to be created with the incorrect visibility set. #122 (@MaximilianoRicoTabo)</li>\n<li>BUG FIX: Fixed a PHP warning that would show when group buttons did not have a <code>link_class</code> set. #120 (@anas-ha)</li>\n<li>BUG FIX: Fixed a PHP warning that would show when invalid data was passed into the <code>pmpro_bp_disable_group_buttons()</code> function. #123 (@MaximilianoRicoTabo)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:73:\"http://license.paidmembershipspro.com/downloads/free/pmpro-buddypress.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:22:\"BuddyPress & BuddyBoss\";}i:17;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Cancel on Next Payment Date\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Cancel on Next Payment Date\";s:9:\"PluginURI\";s:70:\"https://www.paidmembershipspro.com/add-ons/cancel-on-next-payment-date\";s:4:\"Slug\";s:33:\"pmpro-cancel-on-next-payment-date\";s:6:\"plugin\";s:71:\"pmpro-cancel-on-next-payment-date/pmpro-cancel-on-next-payment-date.php\";s:7:\"Version\";s:5:\"0.5.1\";s:11:\"Description\";s:105:\"Change membership cancellation to set expiration date for next payment instead of cancelling immediately.\";s:12:\"Installation\";s:301:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-cancel-on-next-payment-date</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>That\'s it. This plugin has no additional settings.</li>\n</ol>\";s:3:\"FAQ\";s:343:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-cancel-on-next-payment-date/issues\">https://github.com/strangerstudios/pmpro-cancel-on-next-payment-date/issues</a></p>\";s:9:\"Changelog\";s:195:\"<h4>Changelog</h4><p>0.5.1 - 2022-08-22</p><ul>\n<li>ENHANCEMENT: Internationalization for the date in the cancellation text string. (This was accidentally left out of the last update.)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:91:\"https://license.paidmembershipspro.com/downloads/free/pmpro-cancel-on-next-payment-date.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:27:\"Cancel on Next Payment Date\";}i:18;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - CCBill Gateway\";s:5:\"Title\";s:37:\"Paid Memberships Pro - CCBill Gateway\";s:9:\"PluginURI\";s:49:\"https://www.paidmembershipspro.com/add-ons/ccbill\";s:4:\"Slug\";s:12:\"pmpro-ccbill\";s:6:\"plugin\";s:29:\"pmpro-ccbill/pmpro-ccbill.php\";s:7:\"Version\";s:5:\"1.0.2\";s:11:\"Description\";s:36:\"PMPro Gateway integration for CCBill\";s:12:\"Installation\";s:533:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-ccbill</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>Navigate to Memberships &gt; Settings &gt; Payment Gateways &amp; SSL and select the CCBill payment gateway. You will then need to fill out the required account credentials to connect your website to the payment gateway.</p>\";s:3:\"FAQ\";s:493:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-ccbill/issues\">https://github.com/strangerstudios/pmpro-ccbill/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:166:\"<h4>Changelog</h4><p>1.0.2 - 2025-07-10</p><ul>\n<li>ENHANCEMENT: Improved support for Paid Memberships Pro 3.5+ and payment gateway settings. (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:69:\"http://license.paidmembershipspro.com/downloads/free/pmpro-ccbill.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"CCBill Gateway\";}i:19;a:16:{s:4:\"Name\";s:42:\"Paid Memberships Pro - Check Levels Add On\";s:5:\"Title\";s:42:\"Paid Memberships Pro - Check Levels Add On\";s:9:\"PluginURI\";s:56:\"http://www.paidmembershipspro.com/wp/pmpro-check-levels/\";s:4:\"Slug\";s:18:\"pmpro-check-levels\";s:6:\"plugin\";s:41:\"pmpro-check-levels/pmpro-check-levels.php\";s:7:\"Version\";s:2:\".3\";s:11:\"Description\";s:106:\"A collection of customizations useful when allowing users to pay by check for Paid Memberships Pro levels.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:80:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-check-levels.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:12:\"Check Levels\";}i:20;a:16:{s:4:\"Name\";s:39:\"Connect Paid Memberships Pro to Discord\";s:5:\"Title\";s:39:\"Connect Paid Memberships Pro to Discord\";s:9:\"PluginURI\";s:132:\"https://www.expresstechsoftwares.com/step-by-step-documentation-guide-on-how-to-connect-pmpro-and-discord-server-using-discord-addon\";s:4:\"Slug\";s:20:\"pmpro-discord-add-on\";s:6:\"plugin\";s:45:\"pmpro-discord-add-on/pmpro-discord-add-on.php\";s:7:\"Version\";s:5:\"1.2.8\";s:11:\"Description\";s:108:\"Connect your PaidMebershipPro site to your discord server, enable your members to be part of your community.\";s:12:\"Installation\";s:862:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Go to Plugins &gt; Add New to find and install PMPRO discord Addon.</li>\n<li>Or, download the latest version of the plugin, then go to Plugins &gt; Add New and click the \"Upload Plugin\" button to upload your .zip file.</li>\n<li>Activate the plugin.</li>\n</ol><p>Complete the Initial Plugin Setup</p><p>Go to Memberships &gt; Discord Settings in the WordPress admin to begin setup. Our <a href=\"https://youtu.be/v7lxB_Bvlv4\">Initial Setup Tutorial Video </a> will show you how to configure</p><p>More Installation and Setup Documentation</p><ul>\n<li><a href=\"https://youtu.be/v7lxB_Bvlv4\">Installation Video</a></li>\n<li><a href=\"https://www.expresstechsoftwares.com/step-by-step-documentation-guide-on-how-to-connect-pmpro-and-discord-server-using-discord-addon/\">Installation Docs</a></li>\n</ul>\";s:3:\"FAQ\";s:471:\"<p>Frequently Asked Questions</p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit <a href=\"https://www.expresstechsoftwares.com/step-by-step-documentation-guide-on-how-to-connect-pmpro-and-discord-server-using-discord-addon/\">our support site at https://www.expresstechsoftwares.com/step-by-step-documentation-guide-on-how-to-connect-pmpro-and-discord-server-using-discord-addon/</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:59:\"ExpressTech Software Solutions Pvt. Ltd., Strangers Studios\";s:9:\"AuthorURI\";s:36:\"https://www.expresstechsoftwares.com\";s:8:\"Download\";s:63:\"https://downloads.wordpress.org/plugin/pmpro-discord-add-on.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:39:\"Connect Paid Memberships Pro to Discord\";}i:21;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Constant Contact Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Constant Contact Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/pmpro-constant-contact/\";s:4:\"Slug\";s:22:\"pmpro-constant-contact\";s:6:\"plugin\";s:49:\"pmpro-constant-contact/pmpro-constant-contact.php\";s:7:\"Version\";s:3:\"2.0\";s:11:\"Description\";s:86:\"Sync PMPro members to a Constant Contact list with tags assigned per membership level.\";s:12:\"Installation\";s:653:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-constant-contact</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Memberships &gt; Constant Contact in your WordPress admin.</li>\n<li>Enter your Constant Contact API Key (Client ID) and API Secret from the <a href=\"https://app.constantcontact.com/pages/dma/portal/\">Constant Contact Developer Portal</a>.</li>\n<li>Save settings, then click \"Connect to Constant Contact\" to authorize.</li>\n<li>Choose the list that members should be added to and assign tags for each membership level.</li>\n</ol>\";s:3:\"FAQ\";s:1763:\"<p>Frequently Asked Questions</p><p>Where do I get my API Key and Secret?</p><ol>\n<li>Go to the <a href=\"https://app.constantcontact.com/pages/dma/portal/\">Constant Contact Developer Portal</a>.</li>\n<li>Create a new application.</li>\n<li>Set the Redirect URI to your WordPress admin URL (shown on the settings page).</li>\n<li>Copy the API Key (Client ID) and the generated Client Secret into the plugin settings. Note: Constant Contact only displays the secret once when it is generated, so copy it right away.</li>\n</ol><p>Does this sync existing members?</p><p>The plugin syncs members when their membership level changes or when they update their profile. To sync existing members, you can trigger a membership level or profile update for those users.</p><p>Will this remove tags I applied manually in Constant Contact?</p><p>No. The plugin only manages tags that are mapped to PMPro membership levels. Any tags you apply manually in Constant Contact are left untouched.</p><p>What happens when a member cancels?</p><p>Level-specific tags are removed (if tag removal is enabled). The contact remains on your member list so you can continue to reach them with win-back campaigns; remove or unsubscribe contacts directly in Constant Contact if desired. Note that Constant Contact bills by active contact count.</p><p>Why one list with tags instead of a list per level?</p><p>Constant Contact tags are account-wide and can be used to filter recipients when sending an email, so a single list plus per-level tags keeps members segmented without maintaining multiple lists. Note: accounts with more than 10,000 contacts cannot filter by tag at send time and must use a custom segment instead (active custom segments are limited on the Lite and Standard plans).</p>\";s:9:\"Changelog\";s:822:\"<h4>Changelog</h4><p>2.0 - 2026-07-10</p><ul>\n<li>FEATURE: Complete rewrite of the Add On using the Constant Contact v3 API. #17 (@flintfromthebasement, @dparker1005)</li>\n<li>FEATURE: Automatically tag members in Constant Contact based on their membership levels.</li>\n<li>FEATURE: Connect securely to Constant Contact with OAuth 2.0, including PKCE support for applications without a client secret.</li>\n<li>FEATURE: Sync members in the background using the PMPro Action Scheduler for faster checkouts.</li>\n<li>FEATURE: Enable debug logging to troubleshoot syncs and API activity.</li>\n<li>ENHANCEMENT: Contacts in Constant Contact are automatically kept in sync when a member changes their email address in WordPress.</li>\n</ul><p>1.0.3</p><ul>\n<li>Legacy version using Constant Contact v2 API (deprecated).</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/free/pmpro-constant-contact.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Constant Contact\";}i:22;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - ConvertKit Integration\";s:5:\"Title\";s:45:\"Paid Memberships Pro - ConvertKit Integration\";s:9:\"PluginURI\";s:53:\"https://www.paidmembershipspro.com/add-ons/convertkit\";s:4:\"Slug\";s:35:\"convertkit-for-paid-memberships-pro\";s:6:\"plugin\";s:75:\"convertkit-for-paid-memberships-pro/convertkit-for-paid-memberships-pro.php\";s:7:\"Version\";s:5:\"1.1.0\";s:11:\"Description\";s:66:\"Subscribe and tag your Paid Memberships Pro members in ConvertKit.\";s:12:\"Installation\";s:865:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Go to Plugins &gt; Add New to find and install ConvertKit Paid Memberships Pro Integration.</li>\n<li>Or, download the latest version of the plugin, then go to Plugins &gt; Add New and click the \"Upload Plugin\" button to upload your .zip file.</li>\n<li>Activate the plugin.</li>\n</ol><p>Complete the ConvertKit Integration Setup</p><p>Go to Settings &gt; PMPro ConvertKit in the WordPress admin to begin setup.</p>\n<ol>\n<li>Enter your ConvertKit API key, which you can find <a href=\"https://app.convertkit.com/account/edit\">here</a>.</li>\n<li>To add purchase data for subscribers, enter your ConvertKit Secret API key.</li>\n<li>Save your settings.</li>\n<li>Then, adjust the dropdown fields to select a tag for subscribers who sign up for each Membership Level.</li>\n<li>Save your settings.</li>\n</ol>\";s:3:\"FAQ\";s:155:\"<p>Frequently Asked Questions</p><p>Does this plugin require a paid service?</p><p>Yes, for it to work you must first have an account on ConvertKit.com</p>\";s:9:\"Changelog\";s:857:\"<h4>Changelog</h4><p>1.1 - 2021-06-21</p><ul>\n<li>FEATURE: Updated opt-in settings. You can edit the label shown on the opt-in message at checkout.</li>\n<li>FEATURE: Added purchase tracking for each level in ConvertKit.</li>\n<li>ENHANCEMENT: Added assets for GitHub and WordPress.org.</li>\n<li>ENHANCEMENT: Added field to capture API Secret Key.</li>\n<li>ENHANCEMENT: Added Purchases tracking for new membership checkouts.</li>\n<li>ENHANCEMENT: Added filter <code>pmpro_convertkit_change_membership_level_remove_tags</code> to allow optionally removing tags on level change when the previous level is passed to the pmpro_after_change_membership_level function.</li>\n<li>BUG FIX: Email addresses and names are now properly URL encoded when passed to ConvertKit.</li>\n<li>REFACTOR: Refactored API method for retrieving tags and tagging subscribers.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:78:\"https://downloads.wordpress.org/plugin/convertkit-for-paid-memberships-pro.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:22:\"ConvertKit Integration\";}i:23;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - ConvertKit Integration\";s:5:\"Title\";s:45:\"Paid Memberships Pro - ConvertKit Integration\";s:9:\"PluginURI\";s:53:\"https://www.paidmembershipspro.com/add-ons/convertkit\";s:4:\"Slug\";s:31:\"convertkit-paid-memberships-pro\";s:6:\"plugin\";s:67:\"convertkit-paid-memberships-pro/convertkit-paid-memberships-pro.php\";s:7:\"Version\";s:5:\"1.2.1\";s:11:\"Description\";s:66:\"Subscribe and tag your Paid Memberships Pro members in ConvertKit.\";s:12:\"Installation\";s:865:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Go to Plugins &gt; Add New to find and install ConvertKit Paid Memberships Pro Integration.</li>\n<li>Or, download the latest version of the plugin, then go to Plugins &gt; Add New and click the \"Upload Plugin\" button to upload your .zip file.</li>\n<li>Activate the plugin.</li>\n</ol><p>Complete the ConvertKit Integration Setup</p><p>Go to Settings &gt; PMPro ConvertKit in the WordPress admin to begin setup.</p>\n<ol>\n<li>Enter your ConvertKit API key, which you can find <a href=\"https://app.convertkit.com/account/edit\">here</a>.</li>\n<li>To add purchase data for subscribers, enter your ConvertKit Secret API key.</li>\n<li>Save your settings.</li>\n<li>Then, adjust the dropdown fields to select a tag for subscribers who sign up for each Membership Level.</li>\n<li>Save your settings.</li>\n</ol>\";s:3:\"FAQ\";s:155:\"<p>Frequently Asked Questions</p><p>Does this plugin require a paid service?</p><p>Yes, for it to work you must first have an account on ConvertKit.com</p>\";s:9:\"Changelog\";s:1032:\"<h4>Changelog</h4><p>1.2.1 - 2024-12-20</p><ul>\n<li>ENHANCEMENT: Updated the settings page link to be under \"Memberships\" and the settings page UI. #25 (@kimcoleman)</li>\n<li>ENHANCEMENT: Updated the checkout page styling for compatibility with PMPro v3.1+. #31 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added a new filter <code>pmpro_convertkit_disable_create_purchase</code> to disable tracking purchases. #26 (@kimcoleman)</li>\n<li>ENHANCEMENT: Improved the logic around updating ConvertKit subscriber after a user profile is updated. #30 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added a new filter <code>pmpro_kit_update_profile</code> to allow updating ConvertKit subscribers after every profile save. #30 (@kimcoleman)</li>\n<li>BUG FIX/ENHANCEMENT: Now sending a user\'s display name to ConvertKit if the first name is not set. #27 (@kimcoleman)</li>\n<li>BUG FIX: Fixed outdated link to retrieve ConvertKit API key. #20 (@JarrydLong)</li>\n<li>BUG FIX: Fixed a PHP error when no tags are present in ConvertKit. #21 (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:89:\"https://license.paidmembershipspro.com/downloads/free/convertkit-paid-memberships-pro.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:22:\"ConvertKit Integration\";}i:24;a:16:{s:4:\"Name\";s:52:\"Paid Memberships Pro - Courses for Membership Add On\";s:5:\"Title\";s:52:\"Paid Memberships Pro - Courses for Membership Add On\";s:9:\"PluginURI\";s:73:\"https://www.paidmembershipspro.com/add-ons/pmpro-courses-lms-integration/\";s:4:\"Slug\";s:13:\"pmpro-courses\";s:6:\"plugin\";s:31:\"pmpro-courses/pmpro-courses.php\";s:7:\"Version\";s:5:\"2.1.3\";s:11:\"Description\";s:89:\"Create courses and lessons for members. Integrates LMS plugins with Paid Memberships Pro.\";s:12:\"Installation\";s:2199:\"<p>Installation</p><p>Note: You must have <a href=\"https://www.paidmembershipspro.com\">Paid Memberships Pro</a> installed and activated on your site.</p>\n<h3>Install PMPro Courses from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro Courses\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - Courses for Membership\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro Courses Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-courses</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - Courses for Membership\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Configure Course Modules</h3>\n<p>Navigate to Memberships &gt; Courses in the WordPress admin to configure modules.</p>\n<p>The Courses settings page controls which modules are active in your membership site. In most cases, you will only need to have one module active at a time. Navigate to Memberships &gt; Courses to choose from the following settings:</p>\n<ol>\n<li>Default Module: Use the built-in course and lesson custom post types to build a basic e-learning component in your WordPress membership site.</li>\n<li>LearnDash: Enable the LearnDash module to enable course protection by membership level for your courses in the LearnDash LMS.</li>\n<li>LifterLMS: Enable the LifterLMS module to enable course protection by membership level for your courses in LifterLMS.</li>\n</ol>\n<p>Note: This Add On does not include any update scripts to manage enrollment for existing members. For the LearnDash and LifterLMS modules, all members who have an existing membership level will not be automatically enrolled in courses. Course protection and enrollment is hooked in the level change event: only new members or members that cancel or change their level will be updated. You must manually add and remove current members from protected courses.</p>\n<p>The default (built-in) module does not rely on enrollment and will not require any update script.</p>\";s:3:\"FAQ\";s:543:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-courses/issues\">https://github.com/strangerstudios/pmpro-courses/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit <a href=\"http://www.paidmembershipspro.com/\">our support site at https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:654:\"<h4>Changelog</h4><p>2.1.3 - 2026-07-30</p><ul>\n<li>BUG FIX: Fixed members not being enrolled in Tutor LMS courses when their membership level changed. The arguments passed to Tutor\'s <code>do_enroll()</code> were transposed, so enrollment silently failed. #135 (@dparker1005)</li>\n</ul><p>2.1.2 - 2026-06-30</p><ul>\n<li>BUG FIX: Fixed a PHP 8.1+ deprecation notice that occurred when rendering a course outline for a course with no lessons. #127 (@kimcoleman)</li>\n</ul><p>2.1.1 - 2026-06-04</p><ul>\n<li>BUG FIX: Fixed an issue where LearnDash enrollment wasn\'t working correctly on membership assignment or cancellation. #122 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:70:\"http://license.paidmembershipspro.com/downloads/free/pmpro-courses.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:22:\"Courses for Membership\";}i:25;a:16:{s:4:\"Name\";s:52:\"Paid Memberships Pro - Custom Level Cost Text Add On\";s:5:\"Title\";s:52:\"Paid Memberships Pro - Custom Level Cost Text Add On\";s:9:\"PluginURI\";s:72:\"https://www.paidmembershipspro.com/add-ons/pmpro-custom-level-cost-text/\";s:4:\"Slug\";s:21:\"pmpro-level-cost-text\";s:6:\"plugin\";s:47:\"pmpro-level-cost-text/pmpro-level-cost-text.php\";s:7:\"Version\";s:5:\"0.4.4\";s:11:\"Description\";s:99:\"Modify the default level cost text per level, per discount code, or globally via advanced settings.\";s:12:\"Installation\";s:361:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-level-cost-text</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit a Membership Level, Discount Code or the Memberships &gt; Advanced Settings page to modify generated level cost text.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1151:\"<h4>Changelog</h4><p>0.4.4 - 2026-06-30</p><ul>\n<li>ENHANCEMENT: Applied the Level Cost Text format settings (hide decimals, abbreviate periods, etc.) to the individual price and period fields output by the <code>[pmpro_membership_level]</code> shortcode, so they now match the <code>level_cost</code> field. #50 (@kimcoleman)</li>\n</ul><p>0.4.3 - 2026-05-01</p><ul>\n<li>ENHANCEMENT: Updated the Custom Level Cost Text settings on the Edit Level page with the modern admin styling and a link to the Custom Level Cost Text Add On documentation. #47 (@kimcoleman)</li>\n<li>BUG FIX: Fixed an issue where Custom Level Cost Text set on a discount code was missing from checkout emails when using Stripe Checkout, the checkout block, or other contexts that use the <code>pmpro_discount_code</code> request key. #48 (@flintfromthebasement)</li>\n</ul><p>0.4.2 - 2024-02-13</p><ul>\n<li>BUG FIX: Fixed an issue where one-time payments would not hide decimals.</li>\n<li>BUG FIX: Fixed an issue when getting the custom cost text for a level when the $level_id wasn\'t an integer.</li>\n<li>REFACTOR: Moved from pmpro_getOption to get_option for settings.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:82:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-level-cost-text.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:22:\"Custom Level Cost Text\";}i:26;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Custom Post Type Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Custom Post Type Add On\";s:9:\"PluginURI\";s:78:\"https://www.paidmembershipspro.com/add-ons/custom-post-type-membership-access/\";s:4:\"Slug\";s:9:\"pmpro-cpt\";s:6:\"plugin\";s:23:\"pmpro-cpt/pmpro-cpt.php\";s:7:\"Version\";s:5:\"1.0.2\";s:11:\"Description\";s:76:\"Add the PMPro meta box to CPTs and redirects non-members to a selected page.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:70:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-cpt.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Custom Post Type\";}i:27;a:16:{s:4:\"Name\";s:49:\"Paid Memberships Pro - Developer\'s Toolkit Add On\";s:5:\"Title\";s:49:\"Paid Memberships Pro - Developer\'s Toolkit Add On\";s:9:\"PluginURI\";s:57:\"https://www.paidmembershipspro.com/add-ons/pmpro-toolkit/\";s:4:\"Slug\";s:13:\"pmpro-toolkit\";s:6:\"plugin\";s:31:\"pmpro-toolkit/pmpro-toolkit.php\";s:7:\"Version\";s:5:\"1.1.3\";s:11:\"Description\";s:70:\"Various tools to test and debug Paid Memberships Pro enabled websites.\";s:12:\"Installation\";s:221:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-toolkit</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:303:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-toolkit/issues\">https://github.com/strangerstudios/pmpro-toolkit/issues</a></p>\";s:9:\"Changelog\";s:1291:\"<h4>Changelog</h4><p>1.1.3 - 2026-08-19</p><ul>\n<li>SECURITY: Performance testing REST API endpoints now require an authenticated administrator by default. Unauthenticated access can be re-enabled with the new <code>pmpro_toolkit_allow_unauthenticated_requests</code> filter. #74 (@flintfromthebasement)</li>\n<li>SECURITY: Basic Auth is now only allowed for Toolkit REST API routes. #74 (@flintfromthebasement)</li>\n</ul><p>1.1.2 - 2026-05-07</p><ul>\n<li>BUG FIX: Replaced the top-of-file <code>is_plugin_active()</code> early return with narrow <code>function_exists()</code> checks at each PMPro-dependent entry point. The plugin now initializes correctly when PMPro is installed under a non-standard folder name (e.g. <code>paid-memberships-pro-rc1</code>) and avoids potential fatals on frontend requests. #71 (@dparker1005)</li>\n</ul><p>1.1.1 - 2026-03-23</p><ul>\n<li>ENHANCEMENT: Added an option to set an expiration date when moving members between levels. #66 (@andrewlimaza)</li>\n<li>BUG FIX/ENHANCEMENT: Fixed issue with Generate User buttons as well as improved styling and added support for date field completion. #67 (@andrewlimaza)</li>\n<li>BUG FIX: Removed deprecated call to <code>pmpro_doing_webhook()</code> for compatibility with PMPro v3.7+. #70 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:74:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-toolkit.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:19:\"Developer\'s Toolkit\";}i:28;a:16:{s:4:\"Name\";s:32:\"Paid Memberships Pro - Donations\";s:5:\"Title\";s:32:\"Paid Memberships Pro - Donations\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/donations-add-on/\";s:4:\"Slug\";s:15:\"pmpro-donations\";s:6:\"plugin\";s:35:\"pmpro-donations/pmpro-donations.php\";s:7:\"Version\";s:3:\"2.4\";s:11:\"Description\";s:65:\"Allow customers to set an additional donation amount at checkout.\";s:12:\"Installation\";s:310:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-donations</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit the levels you want to add donations to and set the \"Donation\" settings.</li>\n</ol>\";s:3:\"FAQ\";s:307:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-donations/issues\">https://github.com/strangerstudios/pmpro-donations/issues</a></p>\";s:9:\"Changelog\";s:673:\"<h4>Changelog</h4><p>2.4 - 2026-05-15</p><ul>\n<li>ENHANCEMENT: Added support for the new pmpro-paypal Add On (1.1+) as a no-billing gateway at checkout. #100 (@dparker1005)</li>\n<li>ENHANCEMENT: The membership cost and donation amount now appear on the admin View Order page and the printable order template, in addition to the existing public invoice and confirmation pages. Now requires Paid Memberships Pro v3.1 or later. #98 (@andrewlimaza)</li>\n<li>DEPRECATED: The <code>pmpro_donations_invoice_bullets</code> filter has been removed. Use the core <code>pmpro_order_single_meta</code> filter to customize donation entries on order views. #98 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:76:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-donations.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Donations\";}i:29;a:16:{s:4:\"Name\";s:58:\"Paid Memberships Pro - Download Monitor Integration Add On\";s:5:\"Title\";s:58:\"Paid Memberships Pro - Download Monitor Integration Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/pmpro-download-monitor/\";s:4:\"Slug\";s:22:\"pmpro-download-monitor\";s:6:\"plugin\";s:49:\"pmpro-download-monitor/pmpro-download-monitor.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:72:\"Require membership for downloads when using the Download Monitor plugin.\";s:12:\"Installation\";s:853:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro and Download Monitor installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-download-monitor/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>How to Use</p><ol>\n<li>After activation, navigate to \"Downloads\" to Edit or Add a New Download.</li>\n<li>Check the box for each level that can access this download in the \"Require Membership\" meta box (below the Publish box in the right sidebar). </li>\n<li>Save your changes by clicking the \"Update\" button (or \"Publish\" if you are creating a new download).</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:2545:\"<h4>Changelog</h4><p>1.0 - 2026-02-25</p><ul>\n<li>BUG FIX/ENHANCEMENT: Download Monitor blocks now correctly filter output for restricted downloads, showing restricted templates instead of download links for non-members. #12 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Overhauled the template system for membership-restricted downloads. Templates now only render the restricted state and match Download Monitor v4.9.6 patterns including <code>DLM_Utils</code> attributes, Gutenberg <code>className</code> support, and <code>before/after</code> link hooks. #12 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Now using <code>pmpro_get_no_access_message()</code> for PMPro 3.1+ no-access messages on the Download Monitor no-access page. #10 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Now using the <code>pmpro_restrictable_post_types</code> filter for meta box registration instead of a custom init hook. #10 (@dparker1005)</li>\n<li>BUG FIX: Fixed <code>dlm_can_download</code> filter callback to match modern Download Monitor\'s filter signature (<code>$can_download</code>, <code>$download</code>) instead of the previous (<code>$download</code>, <code>$version</code>). #10 (@dparker1005)</li>\n<li>BUG FIX: Fixed handling when all required membership levels have signups disabled, now correctly linking to the levels page instead of building a broken checkout URL. #10 (@dparker1005)</li>\n<li>BUG FIX: Added null guard for deleted membership levels in <code>pmprodlm_getDownloadLevels</code> to prevent fatal errors. #10 (@dparker1005)</li>\n<li>BUG FIX: Updated plugin for localization. #11 (@dparker1005)</li>\n<li>BUG FIX: Added proper output escaping (<code>esc_html()</code>, <code>esc_url()</code>, <code>esc_html__()</code>, <code>esc_html_e()</code>, <code>esc_attr__()</code>) to all outputted strings. #11 (@dparker1005)</li>\n<li>BUG FIX: Updated deprecated <code>getOption</code> to <code>get_option</code>. #6 (@JarrydLong)</li>\n<li>DEPRECATED: This Add On now requires running PMPro v3.0+.</li>\n<li>DEPRECATED: The <code>pmprodlm_shortcode_download_content_filter</code> filter has been removed. The <code>dlm_get_template_part</code> filter now handles all download template filtering. #12 (@dparker1005)</li>\n<li>DEPRECATED: The <code>pmpro_*</code> template names (e.g., <code>template=\"pmpro_box\"</code>) should no longer be used directly. Use standard Download Monitor template names (e.g., <code>template=\"box\"</code>) instead. Using legacy names will trigger a <code>_doing_it_wrong</code> notice. #12 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/free/pmpro-download-monitor.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:28:\"Download Monitor Integration\";}i:30;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Downloads Add On\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Downloads Add On\";s:9:\"PluginURI\";s:59:\"https://www.paidmembershipspro.com/add-ons/pmpro-downloads/\";s:4:\"Slug\";s:15:\"pmpro-downloads\";s:6:\"plugin\";s:35:\"pmpro-downloads/pmpro-downloads.php\";s:7:\"Version\";s:3:\"1.2\";s:11:\"Description\";s:45:\"Create restricted file downloads for members.\";s:12:\"Installation\";s:773:\"<p>Installation</p><ol>\n<li>Navigate to Memberships &gt; Add Ons in the WordPress admin.</li>\n<li>Locate the Downloads Add On and click Install Now.</li>\n<li>Activate the plugin through the Plugins screen in the WordPress admin.</li>\n<li>Navigate to Downloads in the WordPress admin sidebar and click Add New Download.</li>\n<li>Enter a Download Name, upload a file, and set membership restrictions.</li>\n<li>Use the <code>[pmpro_download]</code> shortcode or the PMPro Download block to display a single download on any page.</li>\n<li>Use the <code>[pmpro_download_library]</code> shortcode or the PMPro Download Library block to display multiple downloads.</li>\n</ol>\n<p><a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-downloads/\">View full documentation</a></p>\";s:3:\"FAQ\";s:1902:\"<p>Frequently Asked Questions</p><p>Where are my uploaded files stored?</p><p>Files are stored in PMPro\'s restricted uploads directory, which is located outside of the standard WordPress <code>wp-content/uploads</code> folder and is protected from direct browser access. Files can only be served through PMPro\'s authenticated download handler.</p><p>What file types can I upload?</p><p>Any file type that WordPress permits for upload on your site. The allowed file types are controlled by WordPress\'s standard <code>upload_mimes</code> filter.</p><p>Can a member download a file multiple times?</p><p>Yes. There is no download limit per user. Once a member has the correct membership level, they can download the file as many times as they like.</p><p>What happens when I delete a Download post?</p><p>The physical file is permanently deleted from the server when the post is permanently deleted (not just moved to the Trash).</p><p>What happens when I replace a file?</p><p>The old file is deleted from the server only after the new file uploads successfully. If the new upload fails, the original file is preserved.</p><p>Can I display multiple downloads on one page?</p><p>Yes, use the <code>[pmpro_download_library]</code> shortcode or block to show all downloads, or place multiple <code>[pmpro_download id=\"...\"]</code> shortcodes on the same page.</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-downloads/issues/new/choose\">https://github.com/strangerstudios/pmpro-downloads/issues/new/choose</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:1227:\"<h4>Changelog</h4><p>1.2 - 2026-07-20</p><ul>\n<li>FEATURE: Added Download Categories, allowing downloads to be organized and categories to be protected by membership level. #7 (@kimcoleman)</li>\n<li>ENHANCEMENT: Forced Downloads to use the block editor when the Classic Editor plugin is active, ensuring the download editing interface remains available. #8 (@kimcoleman)</li>\n<li>BUG FIX: Fixed locked download templates to hide membership levels that do not allow signups and show generic messaging when no public levels are available. #6 (@kimcoleman)</li>\n</ul><p>1.1 - 2026-05-04</p><ul>\n<li>ENHANCEMENT: Added a new \"Embed Image\" toggle to the PMPro Download block (and <code>embed_image=\"true\"</code> shortcode attribute) that displays image-type downloads inline for members with access. #4 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: The <code>[pmpro_download]</code> shortcode placed in a level confirmation message now renders as a clickable download link when the confirmation message is included in checkout emails, instead of appearing as raw shortcode text. Invalid shortcodes are left unchanged so admins can spot the typo. #3 (@dparker1005)</li>\n</ul><p>1.0 - 2026-03-30</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:76:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-downloads.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Downloads\";}i:31;a:16:{s:4:\"Name\";s:48:\"Paid Memberships Pro - Email Confirmation Add On\";s:5:\"Title\";s:48:\"Paid Memberships Pro - Email Confirmation Add On\";s:9:\"PluginURI\";s:69:\"https://www.paidmembershipspro.com/add-ons/email-confirmation-add-on/\";s:4:\"Slug\";s:24:\"pmpro-email-confirmation\";s:6:\"plugin\";s:53:\"pmpro-email-confirmation/pmpro-email-confirmation.php\";s:7:\"Version\";s:3:\"0.9\";s:11:\"Description\";s:73:\"Require email confirmation before certain levels are enabled for members.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:85:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-email-confirmation.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:18:\"Email Confirmation\";}i:32;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Email Templates Add On\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Email Templates Add On\";s:9:\"PluginURI\";s:72:\"https://www.paidmembershipspro.com/add-ons/email-templates-admin-editor/\";s:4:\"Slug\";s:21:\"pmpro-email-templates\";s:6:\"plugin\";s:47:\"pmpro-email-templates/pmpro-email-templates.php\";s:7:\"Version\";s:5:\"0.8.1\";s:11:\"Description\";s:114:\"Customize member emails for Paid Memberships Pro using an interactive admin editor within the WordPress dashboard.\";s:12:\"Installation\";s:333:\"<h4>Installation</h4><p>Installation</p><ol>\n<li>Upload the <code>pmpro-email-templates</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Memberships &gt; Email Templates to begin customizing emails.</li>\n</ol>\";s:3:\"FAQ\";s:354:\"<h4>Frequently Asked Questions</h4><p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-email-templates/issues\">https://github.com/strangerstudios/pmpro-email-templates/issues</a></p>\";s:9:\"Changelog\";s:153:\"<h4>Changelog</h4><p>0.8.1 - 2020-06-04</p><ul>\n<li>BUG Fix: Fixed issue where !!membership_change!! may not show user\'s new membership level.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-email-templates.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:15:\"Email Templates\";}i:33;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - Events Add On\";s:5:\"Title\";s:36:\"Paid Memberships Pro - Events Add On\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/events-for-members-only/\";s:4:\"Slug\";s:12:\"pmpro-events\";s:6:\"plugin\";s:29:\"pmpro-events/pmpro-events.php\";s:7:\"Version\";s:5:\"1.6.1\";s:11:\"Description\";s:65:\"Offer Members-only events using PMPro and popular events plugins.\";s:12:\"Installation\";s:1915:\"<p>Installation</p><p>Note: You must have <a href=\"https://paidmembershipspro.com\">Paid Memberships Pro</a> installed and activated on your site.</p>\n<h3>Install PMPro Events from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro Events\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - Events\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro Events Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-events</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - Events\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Create Members-Only Events</h3>\n<p>Once the plugin is activated, it automatically detects which events module to load for your site. The included modules are:</p>\n<ul>\n<li><a href=\"https://wordpress.org/plugins/events-manager/\">Events Manager</a></li>\n<li><a href=\"https://wordpress.org/plugins/the-events-calendar/\">The Events Calendar</a></li>\n<li><a href=\"https://wordpress.org/plugins/sugar-calendar-lite/\">Sugar Calendar</a></li>\n<li><a href=\"https://wordpress.org/plugins/all-in-one-event-calendar/\">Timely All-in-One Events Calendar (&lt; 3.0.0)</a></li>\n</ul>\n<p>If you are not already using an events plugin, you must select one from this list to use the features of this integration plugin.</p>\n<ol>\n<li>Edit any event in your site to restrict access via the \"Require Membership\" meta box.</li>\n<li>Events are displayed or hidden from calendar (archive) view according to your settings under Memberships &gt; Settings &gt; Advanced Settings.</li>\n<li>Event excerpts are shown or hidden from non-members according to your settings under Memberships &gt; Settings &gt; Advanced Settings.</li>\n</ol>\";s:3:\"FAQ\";s:693:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-events/issues\">https://github.com/strangerstudios/pmpro-events/issues</a></p>\n<p>For immediate help, also post to our premium support site at <a href=\"https://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:182:\"<h4>Changelog</h4><p>1.6.1 - 2025-11-25</p><ul>\n<li>BUG FIX: Resolve a PHP warning for Events Manager that occurs when event content is retrieved via AJAX. #56 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:69:\"http://license.paidmembershipspro.com/downloads/free/pmpro-events.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:6:\"Events\";}i:34;a:16:{s:4:\"Name\";s:61:\"Paid Memberships Pro - Extra Expiration Warning Emails Add On\";s:5:\"Title\";s:61:\"Paid Memberships Pro - Extra Expiration Warning Emails Add On\";s:9:\"PluginURI\";s:82:\"https://www.paidmembershipspro.com/add-ons/extra-expiration-warning-emails-add-on/\";s:4:\"Slug\";s:37:\"pmpro-extra-expiration-warning-emails\";s:6:\"plugin\";s:79:\"pmpro-extra-expiration-warning-emails/pmpro-extra-expiration-warning-emails.php\";s:7:\"Version\";s:5:\"1.0.3\";s:11:\"Description\";s:81:\"Send out more than one \"membership expiration warning\" email to users with PMPro.\";s:12:\"Installation\";s:386:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-extra-expiration-warning-emails</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the <code>Plugins</code> menu in WordPress.</li>\n<li>Update the $emails array to change when the additional emails are sent and to define a custom template file, if desired.</li>\n</ol>\";s:3:\"FAQ\";s:597:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-extra-expiration-warning-emails/issues\">https://github.com/strangerstudios/pmpro-extra-expiration-warning-emails/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:834:\"<h4>Changelog</h4><p>1.0.3 - 2026-05-15</p><ul>\n<li>BUG FIX/ENHANCEMENT: The admin Bcc email now falls back to the bare <code>admin_email</code> value when no WordPress user is associated with it, instead of being silently dropped. #41 (@gazer22)</li>\n<li>BUG FIX: Fixed a PHP warning and malformed <code>Bcc:</code> header that occurred when the site\'s <code>admin_email</code> was not associated with a WordPress user. #41 (@gazer22)</li>\n<li>BUG FIX: Fixed an issue in multisite environments where the same <code>membership_id</code> on different subsites could share a single notice-sent timestamp, causing some subsites to skip expiration notices that should have been sent. Notice tracking is now scoped per-site via <code>update_user_option()</code>, with legacy timestamps migrated automatically. #42 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:98:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-extra-expiration-warning-emails.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:31:\"Extra Expiration Warning Emails\";}i:35;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Failed Payment Limit Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Failed Payment Limit Add On\";s:9:\"PluginURI\";s:64:\"http://www.paidmembershipspro.com/wp/pmpro-failed-payment-limit/\";s:4:\"Slug\";s:26:\"pmpro-failed-payment-limit\";s:6:\"plugin\";s:57:\"pmpro-failed-payment-limit/pmpro-failed-payment-limit.php\";s:7:\"Version\";s:2:\".3\";s:11:\"Description\";s:55:\"Cancel members subscriptions after 1-3 failed payments.\";s:12:\"Installation\";s:433:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-failed-payment-limit</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Visit Memberships -&gt; Advanced Settings to change the \"Failed Payment Limit\" setting.</li>\n<li>Alternatively, you can set a PMPRO_FAILED_PAYMENT_LIMIT constant in your wp-config.php file.</li>\n</ol>\";s:3:\"FAQ\";s:329:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-failed-payment-limit/issues\">https://github.com/strangerstudios/pmpro-failed-payment-limit/issues</a></p>\";s:9:\"Changelog\";s:431:\"<h4>Changelog</h4><p>0.3 - 2023-10-12</p><ul>\n<li>BUG FIX/ENHANCEMENT: Marking plugin as incompatible with Multiple Memberships Per User for the PMPro v3.0 update. #14 (@dparker1005)</li>\n<li>BUG FIX: Now passing user object to <code>sendCancelEmail()</code> instead of just the user ID. #10 (@mircobabini)</li>\n<li>REFACTOR: Now using <code>get_option()</code> instead of <code>pmpro_getOption()</code>. #15 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:88:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-failed-payment-limit.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:20:\"Failed Payment Limit\";}i:36;a:16:{s:4:\"Name\";s:47:\"Paid Memberships Pro - Force Profile Completion\";s:5:\"Title\";s:47:\"Paid Memberships Pro - Force Profile Completion\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/force-profile-completion\";s:4:\"Slug\";s:30:\"pmpro-force-profile-completion\";s:6:\"plugin\";s:65:\"pmpro-force-profile-completion/pmpro-force-profile-completion.php\";s:7:\"Version\";s:3:\"1.1\";s:11:\"Description\";s:92:\"Require all members to complete required profile fields before accessing restricted content.\";s:12:\"Installation\";s:637:\"<p>Installation</p><ol>\n<li>Upload the plugin folder to <code>/wp-content/plugins/</code> or install via <strong>Plugins &gt; Add New</strong>.</li>\n<li>Activate the plugin through the <strong>Plugins</strong> menu in WordPress.</li>\n<li>In Paid Memberships Pro, go to <strong>Memberships &gt; Settings &gt; User Fields</strong> and mark one or more fields as <strong>Required</strong>.</li>\n<li>Members with an active membership who have not filled in those fields will be redirected to the Edit Profile page on their next login or when they attempt to view restricted content.</li>\n</ol>\n<p>No additional configuration is required.</p>\";s:3:\"FAQ\";s:1860:\"<p>Frequently Asked Questions</p><p>Does this affect non-members or logged-out visitors?</p><p>No. The redirect only applies to logged-in users who have an active membership level. Logged-out visitors and users without a membership level are handled by PMPro core as normal.</p><p>Which pages can members always access?</p><p>All PMPro-assigned pages (account, billing, cancel, checkout, confirmation, etc.) are always accessible. This prevents members from being fully locked out while they complete their profile. The directory and profile pages are excluded from this bypass so they can remain gated if needed.</p><p>What counts as a \"required\" field?</p><p>Any field defined through <strong>PMPro &gt; Settings &gt; User Fields</strong> that has the <strong>Required</strong> checkbox enabled. Fields with conditional visibility (<code>depends</code>) are only required when their parent field\'s condition is satisfied.</p><p>Does this work with conditional/dependent fields?</p><p>Yes. If a field is set to only display when another field has a specific value, this plugin checks whether that condition is met before treating the field as required. Fields whose conditions are not satisfied are skipped.</p><p>Will members lose access to their account or billing pages?</p><p>No. PMPro core pages (account, checkout, billing, cancel, etc.) are always reachable so members can still manage their subscription while they complete their profile.</p><p>When is the incomplete-fields cache cleared?</p><p>The cache is cleared automatically when:</p>\n<ul>\n<li>The member saves their profile (<code>pmpro_personal_options_update</code> or <code>profile_update</code>).</li>\n<li>An admin saves, updates, or deletes the User Fields settings (<code>pmpro_user_fields_settings</code> option changes).</li>\n</ul>\n<p>The cache has a maximum lifetime of 10 minutes.</p>\";s:9:\"Changelog\";s:246:\"<h4>Changelog</h4><p>1.1 - 2026-07-02</p><ul>\n<li>BUG FIX: Fixes an issue where it would cause the Member Profile page for the Member Directory and Profile Add On would be 404.</li>\n</ul><p>1.0 - 2026-04-02</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:91:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-force-profile-completion.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:24:\"Force Profile Completion\";}i:37;a:16:{s:4:\"Name\";s:41:\"Paid Memberships Pro - GetResponse Add On\";s:5:\"Title\";s:41:\"Paid Memberships Pro - GetResponse Add On\";s:9:\"PluginURI\";s:52:\"http://www.paidmembershipspro.com/pmpro-getresponse/\";s:4:\"Slug\";s:17:\"pmpro-getresponse\";s:6:\"plugin\";s:39:\"pmpro-getresponse/pmpro-getresponse.php\";s:7:\"Version\";s:2:\".5\";s:11:\"Description\";s:65:\"Sync your WordPress users and members with GetResponse campaigns.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:79:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-getresponse.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:11:\"GetResponse\";}i:38;a:16:{s:4:\"Name\";s:38:\"Paid Memberships Pro - Gift Aid Add On\";s:5:\"Title\";s:38:\"Paid Memberships Pro - Gift Aid Add On\";s:9:\"PluginURI\";s:52:\"https://www.paidmembershipspro.com/add-ons/gift-aid/\";s:4:\"Slug\";s:14:\"pmpro-gift-aid\";s:6:\"plugin\";s:33:\"pmpro-gift-aid/pmpro-gift-aid.php\";s:7:\"Version\";s:3:\"0.2\";s:11:\"Description\";s:70:\"Add a checkbox to opt in to the UK Gift Aid tax incentive at checkout.\";s:12:\"Installation\";s:309:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-gift-aid</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit the levels you want to add donations to and set the \"Donation\" settings.</li>\n</ol>\";s:3:\"FAQ\";s:305:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-gift-aid/issues\">https://github.com/strangerstudios/pmpro-gift-aid/issues</a></p>\";s:9:\"Changelog\";s:652:\"<h4>Changelog</h4><p>0.2 - 2024-10-19</p><ul>\n<li>ENHANCEMENT: Updated the frontend UI for compatibility with PMPro v3.1. #18 (@MaximilianoRicoTabo, @kimcoleman)</li>\n<li>ENHANCEMENT: Added compatibility for the Donations Add On for Paid Memberships Pro. #18 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added filter <code>pmproga_show_gift_aid_at_checkout</code> to show or hide the gift aid checkbox. #18 (@kimcoleman)</li>\n<li>BUG FIX: Fixed compatibility with admin checkout email templates updated in PMPro v3.0. #19 (@MaximilianoRicoTabo)</li>\n<li>BUG FIX: Fixed bug where Gift Aid user meta was not set if unchecked. #17 (@MaximilianoRicoTabo)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:76:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-gift-aid.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:8:\"Gift Aid\";}i:39;a:16:{s:4:\"Name\";s:41:\"Paid Memberships Pro - Gift Levels Add On\";s:5:\"Title\";s:41:\"Paid Memberships Pro - Gift Levels Add On\";s:9:\"PluginURI\";s:61:\"https://www.paidmembershipspro.com/add-ons/pmpro-gift-levels/\";s:4:\"Slug\";s:17:\"pmpro-gift-levels\";s:6:\"plugin\";s:39:\"pmpro-gift-levels/pmpro-gift-levels.php\";s:7:\"Version\";s:5:\"1.1.2\";s:11:\"Description\";s:86:\"Sell a gift certificate that generates a unique gift code for membership to your site.\";s:12:\"Installation\";s:640:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-gift-levels</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Memberships &gt; Settings &gt; Levels to create and manage gift membership levels.</li>\n<li>Navigate to Memberships &gt; Settings &gt; Email Templates to modify default messages sent through this plugin.</li>\n</ol>\n<p>Refer to the <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-gift-levels/\">Gift Levels Add On documentation page</a> for more information on how to set up your gift levels.</p>\";s:3:\"FAQ\";s:33:\"<p>Frequently Asked Questions</p>\";s:9:\"Changelog\";s:305:\"<h4>Changelog</h4><p>1.1.2 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Updated email templates to use liquid <code>{{ }}</code> variable syntax when running Paid Memberships Pro v3.7+, with backwards-compatible fallback to legacy <code>!!</code> syntax for older versions of PMPro. #76 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:78:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-gift-levels.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:11:\"Gift Levels\";}i:40;a:16:{s:4:\"Name\";s:47:\"Paid Memberships Pro - Goal Progress Bar Add On\";s:5:\"Title\";s:47:\"Paid Memberships Pro - Goal Progress Bar Add On\";s:9:\"PluginURI\";s:55:\"https://www.paidmembershipspro.com/add-ons/pmpro-goals/\";s:4:\"Slug\";s:11:\"pmpro-goals\";s:6:\"plugin\";s:27:\"pmpro-goals/pmpro-goals.php\";s:7:\"Version\";s:3:\"1.2\";s:11:\"Description\";s:68:\"Display a progress bar for membership site signup and revenue goals.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:72:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-goals.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:17:\"Goal Progress Bar\";}i:41;a:16:{s:4:\"Name\";s:51:\"Paid Memberships Pro - Google Analytics Integration\";s:5:\"Title\";s:51:\"Paid Memberships Pro - Google Analytics Integration\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/google-analytics/\";s:4:\"Slug\";s:22:\"pmpro-google-analytics\";s:6:\"plugin\";s:49:\"pmpro-google-analytics/pmpro-google-analytics.php\";s:7:\"Version\";s:5:\"1.0.3\";s:11:\"Description\";s:111:\"Connect Paid Memberships Pro to Google Analytics 4 to measure traffic, interactions, and ecommerce conversions.\";s:12:\"Installation\";s:1008:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-google-analytics/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>How to Use</p><ol>\n<li>Navigate to Settings &gt; PMPro Google Analytics.</li>\n<li>Enter your Google Analytics Property\'s Measurement ID </li>\n<li>Define settings for membership levels to track (including free checkouts) or leave blank to track all ecommerce conversions.</li>\n<li>Optionally exclude administrator role users from tracking.</li>\n<li>Save Settings.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/google-analytics/\">https://www.paidmembershipspro.com/add-ons/google-analytics/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:345:\"<h4>Changelog</h4><p>1.0.3 - 2026-05-05</p><ul>\n<li>BUG FIX: Added a null check for the global <code>$pmpro_level</code> in <code>pmproga4_checkout_events()</code> to prevent fatal errors when the membership level is not set on the checkout page (e.g. direct page access or third-party plugin interference). #9 (@flintfromthebasement)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-google-analytics.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:28:\"Google Analytics Integration\";}i:42;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Group Accounts Add On\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Group Accounts Add On\";s:9:\"PluginURI\";s:58:\"https://www.paidmembershipspro.com/add-ons/group-accounts/\";s:4:\"Slug\";s:20:\"pmpro-group-accounts\";s:6:\"plugin\";s:45:\"pmpro-group-accounts/pmpro-group-accounts.php\";s:7:\"Version\";s:3:\"1.6\";s:11:\"Description\";s:108:\"Sell group memberships where one member pays for a collection of people to access your content individually.\";s:12:\"Installation\";s:626:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-group-accounts/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/group-accounts/\">https://www.paidmembershipspro.com/add-ons/group-accounts/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1061:\"<h4>Changelog</h4><p>1.6 - 2026-05-21</p><ul>\n<li>FEATURE: Added a new \"Group Accounts\" admin page (Memberships â†’ Group Accounts) for administrators to view all groups on the site and manually create new groups. The new admin list table supports custom columns via the <code>pmprogroupacct_manage_groupslist_columns</code> filter and the <code>pmprogroupacct_manage_grouplist_custom_column</code> action. #92 (@dparker1005)</li>\n<li>ENHANCEMENT: Added a \"Managed by [parent name]\" message to the membership account page level cards for child group members, supporting the PMPro 3.4+ card-based account layout. #87 (@dparker1005)</li>\n<li>ENHANCEMENT: Added Group Accounts fields to the new mapping screen in the Import Users From CSV Add On so administrators can map CSV headers to group seat counts and group IDs. #91 (@andrewlimaza)</li>\n<li>DEPRECATED: Removed automatic creation of empty 0-seat groups on level gain and parent login. Groups are now created only at checkout or by an administrator via the new admin page. #92 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:81:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-group-accounts.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"Group Accounts\";}i:43;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Group Discount Codes Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Group Discount Codes Add On\";s:9:\"PluginURI\";s:64:\"https://www.paidmembershipspro.com/add-ons/group-discount-codes/\";s:4:\"Slug\";s:26:\"pmpro-group-discount-codes\";s:6:\"plugin\";s:57:\"pmpro-group-discount-codes/pmpro-group-discount-codes.php\";s:7:\"Version\";s:5:\"0.5.1\";s:11:\"Description\";s:98:\"Adds features to PMPro to better manage grouped discount codes or large numbers of discount codes.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:87:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-group-discount-codes.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Group Discount Codes\";}i:44;a:16:{s:4:\"Name\";s:30:\"Hide Admin Bar From Non-admins\";s:5:\"Title\";s:30:\"Hide Admin Bar From Non-admins\";s:9:\"PluginURI\";s:74:\"https://www.paidmembershipspro.com/add-ons/hide-admin-bar-from-non-admins/\";s:4:\"Slug\";s:30:\"hide-admin-bar-from-non-admins\";s:6:\"plugin\";s:65:\"hide-admin-bar-from-non-admins/hide-admin-bar-from-non-admins.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:71:\"A tweak of the code by Yoast to hide the admin bar for non-admins only.\";s:12:\"Installation\";s:346:\"<p>Installation</p><ol>\n<li>Upload the <code>hide-admin-bar-from-non-admins</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Tweak the plugin code as needed. There are no settings, and this plugin will not be updated often.</li>\n</ol>\";s:3:\"FAQ\";s:585:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/hide-admin-bar-from-non-admins/issues\">https://github.com/strangerstudios/hide-admin-bar-from-non-admins/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:78:\"<h4>Changelog</h4><p>1.0</p><ul>\n<li>Initial version of the plugin.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:31:\"https://www.strangerstudios.com\";s:8:\"Download\";s:73:\"https://downloads.wordpress.org/plugin/hide-admin-bar-from-non-admins.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:30:\"Hide Admin Bar From Non-admins\";}i:45;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Holler Box Integration\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Holler Box Integration\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/holler-box-integration/\";s:4:\"Slug\";s:15:\"pmpro-hollerbox\";s:6:\"plugin\";s:35:\"pmpro-hollerbox/pmpro-hollerbox.php\";s:7:\"Version\";s:4:\".1.1\";s:11:\"Description\";s:105:\"Integrates Paid Memberships Pro with the Holler Box plugin to display popups/banners by membership level.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:73:\"https://license.paidmembershipspro.com/downloads/plus/pmpro-hollerbox.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:22:\"Holler Box Integration\";}i:46;a:16:{s:4:\"Name\";s:53:\"Paid Memberships Pro - Import Members From CSV Add On\";s:5:\"Title\";s:53:\"Paid Memberships Pro - Import Members From CSV Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/pmpro-import-users-csv/\";s:4:\"Slug\";s:27:\"pmpro-import-users-from-csv\";s:6:\"plugin\";s:59:\"pmpro-import-users-from-csv/pmpro-import-users-from-csv.php\";s:7:\"Version\";s:5:\"1.4.1\";s:11:\"Description\";s:99:\"Import your users or members list to WordPress and automatically assign membership levels in PMPro.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:523:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-import-users-from-csv/issues\">https://github.com/strangerstudios/pmpro-import-users-from-csv/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:1091:\"<h4>Changelog</h4><p>1.4.1 - 2026--08-25</p><ul>\n<li>ENHANCEMENT: Normalize date-type User Fields to Y-m-d format when importing. #82 (@flintfromthebasement)</li>\n</ul><p>1.4 - 2026-08-20</p><ul>\n<li>SECURITY: Improved security to harden against potential vulnerabilities. Defensive coding practices have been applied to prevent XSS while importing users. #82 (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed an issue where order timestamps would always default to current date of import. #81 (@LSNicholls)</li>\n<li>BUG FIX: Fixed an issue where \'id\' would not automatically map to \'ID\' in the field mapper. #80 (@andrewlimaza)</li>\n<li>BUG FIX: Fixed an issue where the \"Skip Existing Members\" option was not being honored when looping through batches. #83 (@dwanjuki)</li>\n</ul><p>1.3 - 2026-07-31</p><ul>\n<li>ENHANCEMENT: Added compatibility for multi-value User Fields importing. If a User Field is set to allow multiple values (multiselect,checkbox_grouped etc), the import will now accept a comma-separated list of values for that field. (@flintfromthebasement,@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:88:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-import-users-from-csv.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:23:\"Import Members From CSV\";}i:47;a:16:{s:4:\"Name\";s:21:\"Import Users from CSV\";s:5:\"Title\";s:21:\"Import Users from CSV\";s:9:\"PluginURI\";s:58:\"http://wordpress.org/extend/plugins/import-users-from-csv/\";s:4:\"Slug\";s:21:\"import-users-from-csv\";s:6:\"plugin\";s:47:\"import-users-from-csv/import-users-from-csv.php\";s:7:\"Version\";s:5:\"1.0.0\";s:11:\"Description\";s:47:\"Import Users data and metadata from a csv file.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:13:\"Ulrich Sossou\";s:9:\"AuthorURI\";s:24:\"http://ulrichsossou.com/\";s:8:\"Download\";s:64:\"https://downloads.wordpress.org/plugin/import-users-from-csv.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:21:\"Import Users from CSV\";}i:48;a:16:{s:4:\"Name\";s:42:\"Paid Memberships Pro - Infusionsoft Add On\";s:5:\"Title\";s:42:\"Paid Memberships Pro - Infusionsoft Add On\";s:9:\"PluginURI\";s:74:\"https://www.paidmembershipspro.com/add-ons/pmpro-infusionsoft-integration/\";s:4:\"Slug\";s:18:\"pmpro-infusionsoft\";s:6:\"plugin\";s:41:\"pmpro-infusionsoft/pmpro-infusionsoft.php\";s:7:\"Version\";s:3:\"1.4\";s:11:\"Description\";s:65:\"Sync your WordPress users and members with Infusionsoft contacts.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:61:\"https://downloads.wordpress.org/plugin/pmpro-infusionsoft.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:12:\"Infusionsoft\";}i:49;a:16:{s:4:\"Name\";s:52:\"Paid Memberships Pro - Invite Only Membership Add On\";s:5:\"Title\";s:52:\"Paid Memberships Pro - Invite Only Membership Add On\";s:9:\"PluginURI\";s:72:\"https://www.paidmembershipspro.com/add-ons/pmpro-invite-only-membership/\";s:4:\"Slug\";s:17:\"pmpro-invite-only\";s:6:\"plugin\";s:39:\"pmpro-invite-only/pmpro-invite-only.php\";s:7:\"Version\";s:3:\"0.4\";s:11:\"Description\";s:102:\"Require an invite code to sign up for the specified Membership Levels (works for free or paid levels).\";s:12:\"Installation\";s:647:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-invite-only</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Set the $pmproio_invite_required_levels array to specify the levels which should require invite codes and generate them and (optionally) set the $pmproio_invite_given_levels if only specific levels should be given invite codes to share.</li>\n<li>Other optional settings: PMPROIO_CODES and PMPROIO_CODES_USES constants can be set to define the number of codes to generate and number of uses code allowed per code.</li>\n</ol>\";s:3:\"FAQ\";s:311:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-invite-only/issues\">https://github.com/strangerstudios/pmpro-invite-only/issues</a></p>\";s:9:\"Changelog\";s:172:\"<h4>Changelog</h4><p>0.4 - 2024-09-27</p><ul>\n<li>ENHANCEMENT: Updated the frontend UI for compatibility with PMPro v3.1. #29 (@MaximilianoRicoTabo, @kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:78:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-invite-only.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:22:\"Invite Only Membership\";}i:50;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Keap Integration\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Keap Integration\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/keap-integration/\";s:4:\"Slug\";s:10:\"pmpro-keap\";s:6:\"plugin\";s:25:\"pmpro-keap/pmpro-keap.php\";s:7:\"Version\";s:5:\"1.0.4\";s:11:\"Description\";s:69:\"Create and tag leads and customers in Keap based on membership level.\";s:12:\"Installation\";s:1023:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-keap/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>How to Use</p><ol>\n<li>Navigate to Memberships &gt; Keap in the WordPress dashboard.</li>\n<li>You will need to enter your Keap API Key and Secret Key. You can find these in your Keap account by navigating to <a href=\"https://keys.developer.keap.com/\">https://keys.developer.keap.com/</a>.</li>\n<li>Once authorized, you may select the tags to apply to users based on their membership level.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/keap-integration/\">https://www.paidmembershipspro.com/add-ons/keap-integration/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:482:\"<h4>Changelog</h4><p>1.0.2 - 2024-09-13</p><ul>\n<li>ENHANCEMENT: Adjusting the format of settings page and fields; updating descriptions; using PMPro-native styles for scroll boxes; labels with correct for name (@kimcoleman)</li>\n<li>ENHANCEMENT: Adding repo files; fixing links to Add On page, Add On name, removing admin.css (@kimcoleman)</li>\n<li>ENHANCEMENT: Update README.MD, Update .gitattributes (@kimcoleman)</li>\n<li>ENHANCEMENT: Adding banner file (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:67:\"http://license.paidmembershipspro.com/downloads/free/pmpro-keap.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Keap Integration\";}i:51;a:16:{s:4:\"Name\";s:41:\"Paid Memberships Pro - Kissmetrics Add On\";s:5:\"Title\";s:41:\"Paid Memberships Pro - Kissmetrics Add On\";s:9:\"PluginURI\";s:0:\"\";s:4:\"Slug\";s:17:\"pmpro-kissmetrics\";s:6:\"plugin\";s:39:\"pmpro-kissmetrics/pmpro-kissmetrics.php\";s:7:\"Version\";s:4:\".3.1\";s:11:\"Description\";s:116:\"Integrates your WordPress site with Kissmetrics to track meaningful user data, with or without Paid Memberships Pro.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:26:\"http://strangerstudios.com\";s:8:\"Download\";s:60:\"https://downloads.wordpress.org/plugin/pmpro-kissmetrics.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:11:\"Kissmetrics\";}i:52;a:16:{s:4:\"Name\";s:33:\"Paid Memberships Pro - Kit Add On\";s:5:\"Title\";s:33:\"Paid Memberships Pro - Kit Add On\";s:9:\"PluginURI\";s:65:\"https://www.paidmembershipspro.com/add-ons/pmpro-kit-integration/\";s:4:\"Slug\";s:9:\"pmpro-kit\";s:6:\"plugin\";s:23:\"pmpro-kit/pmpro-kit.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:96:\"Connect Paid Memberships Pro to Kit to add members as subscribers and manage tags automatically.\";s:12:\"Installation\";s:201:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-kit</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:75:\"<h4>Changelog</h4><p>1.0 - 2026-01-27</p><ul>\n<li>First version.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:66:\"http://license.paidmembershipspro.com/downloads/free/pmpro-kit.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:3:\"Kit\";}i:53;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Levels as DIV Layout Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Levels as DIV Layout Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/levels-page-div-layout/\";s:4:\"Slug\";s:16:\"pmpro-div-levels\";s:6:\"plugin\";s:37:\"pmpro-div-levels/pmpro-div-levels.php\";s:7:\"Version\";s:2:\".3\";s:11:\"Description\";s:76:\"Display your Membership Levels Page in a DIV Layout for Paid Memberships Pro\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:78:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-div-levels.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:20:\"Levels as DIV Layout\";}i:54;a:16:{s:4:\"Name\";s:9:\"LifterLMS\";s:5:\"Title\";s:9:\"LifterLMS\";s:9:\"PluginURI\";s:22:\"https://lifterlms.com/\";s:4:\"Slug\";s:9:\"lifterlms\";s:6:\"plugin\";s:23:\"lifterlms/lifterlms.php\";s:7:\"Version\";s:5:\"7.3.0\";s:11:\"Description\";s:107:\"Complete e-learning platform to sell online courses, protect lessons, offer memberships, and quiz students.\";s:12:\"Installation\";s:2037:\"<p>Installation</p><h4>Minimum System Requirements</h4>\n<p>LifterLMS Requires</p>\n<ul>\n<li>PHP 7.4 or later</li>\n<li>WordPress 5.6 or later</li>\n<li>MySQL 5.6 or later</li>\n</ul>\n<p>Visit our <a href=\"https://lifterlms.com/docs/minimum-system-requirements-lifterlms/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">full system requirements</a> for additional information.</p>\n<h4>Automatic Installation</h4>\n<p>The simplest way to install LifterLMS is through your existing WordPress siteâ€™s admin. Let WordPress handle file transfers for you - youâ€™ll never need to leave the web browser or admin panel.</p>\n<ol>\n<li>Log in to your WordPress dashboard</li>\n<li>Navigate to Plugins -&gt; Add New</li>\n<li>In the search field, type \"LifterLMS\" and click \"Search Plugins\"</li>\n<li>Once you\'ve located LifterLMS, click \"Install Now\"</li>\n<li>Once installation is complete, click \"Activate\"</li>\n</ol>\n<h4>Manual Installation</h4>\n<p>To manually install LifterLMS, you\'ll need to download the zip file using the \"Download\" link on this screen. Then, use FTP to manually upload the unzipped plugin folder to the proper plugins directory on your webserver.</p>\n<p>Please see this <a href=\"https://wordpress.org/documentation/article/manage-plugins/#manual-plugin-installation-1\">WordPress Codex document</a> for full instructions on Manual Plugin Installation.</p>\n<h4>Setup Wizard</h4>\n<p>After installation, LifterLMS launches a friendly (and super quick) Setup Wizard.</p>\n<p>This wizard helps you configure LifterLMS so you can get to the fun stuff - like creating your courses - as quickly as possible.</p>\n<p>The wizard includes a few sample courses you can import if you want to see some examples before you start creating your own content.</p>\n<p>You can return to the setup wizard at any time by following <a href=\"https://lifterlms.com/docs/rerun-lifterlms-setup-wizard/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">these steps</a>.</p>\";s:3:\"FAQ\";s:6297:\"<p>Frequently Asked Questions</p><h4>Where do I buy add-ons or bundles for my LifterLMS eLearning Website?</h4>\n<p>You can explore the individual learning management system add-ons <a href=\"https://lifterlms.com/store/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">here</a> or save BIG with a <a href=\"https://lifterlms.com/product-category/bundles/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">bundle</a></p>\n<h4>How do I troubleshoot issues with my LMS website?</h4>\n<p>First, make sure that you\'re running the latest version of LifterLMS. And if you\'ve got any other LifterLMS plugins active on your site, make sure those are running the most current version as well.</p>\n<p>The most common issues we see are either plugin conflicts, theme conflicts, or outdated servers. You can test if a plugin or theme is conflicting by manually deactivating other plugins until just LifterLMS is running on your site. If the issue persists from there, revert to the default Twenty Fifteen theme. If the issue is resolved after deactivating a specific plugin or your theme, you\'ll know that is the source of the conflict. If it is a hosting issue, contact your web host and make sure theyâ€™re running the most current version of PHP.</p>\n<p>Also be sure to check out the official LifterLMS <a href=\"https://lifterlms.com/docs/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">Knowledge Base</a>.</p>\n<h4>How do I ask a question about my online course website?</h4>\n<p>Users of the free LifterLMS should post their questions here in our WordPress.org support area. If you find you\'re not getting support in as timely a fashion as you wish, you might want to consider <a href=\"https://lifterlms.com/pricing/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">purchasing a product from LifterLMS</a> so you can access the LifterLMS support team.</p>\n<p>If you\'re already a LifterLMS customer, you can simply log into your account and contact the support team directly on the <a href=\"https://lifterlms.com/my-account/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">LifterLMS website</a>. We can provide a deeper level of support in there and address your needs on a daily basis during the work week. Generally, except in times of increased support loads, we reply to all comments within 12 business hours.</p>\n<h4>LifterLMS is awesome! Can you set up my online course site for me?</h4>\n<p>LifterLMS offers technical support, but we do not offer custom website development services. However, we do recommend third party LifterLMS Experts who can help with web design, web development, instructional design or marketing for a fee.  Click here to visit the <a href=\"https://lifterlms.com/experts/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">LifterLMS Experts page</a>.</p>\n<h4>I\'m interested in purchasing add-ons for my WordPress LMS website, but I have a few questions first.</h4>\n<p>If you\'re not finding your questions answered here or on our website, you can ask your presales questions through this <a href=\"https://lifterlms.com/contact/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">contact form</a>. You can also connect live with a member of our team <a href=\"https://lifterlms.com/contact/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">here</a>.</p>\n<h4>What add-ons are available for LifterLMS, and where can I read more about them?</h4>\n<p>You can find a full list of official LifterLMS Add-ons <a href=\"https://lifterlms.com/store/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">here</a></p>\n<h4>I have a feature idea. What\'s the best way to tell you about it?</h4>\n<p>We care about your feature ideas and what you have to say. You can <a href=\"https://lifterlms.com/contact/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">request a feature</a>, <a href=\"?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">vote on existing feature requests</a>, and checkout the <a href=\"https://lifterlms.com/roadmap/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">product roadmap</a>.</p>\n<h4>Do you have any training for building an online course website?</h4>\n<p>Be sure youâ€™ve taken the free tutorial training video course: <a href=\"https://academy.lifterlms.com/course/how-to-build-a-learning-management-system-with-lifterlms/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">How to Create an Online Course with LifterLMS</a>. We also encourage you to get to know us by signing up for a $1 temporary <em>30 Day</em> website on our servers which comes with the core LifterLMS plugin all our add-ons intalled. This demo allows you to test drive all the add-ons before you invest. Check it out here: <strong><a href=\"https://lifterlms.com/try/?utm_source=LifterLMS%20Plugin&amp;utm_medium=README&amp;utm_campaign=Readme%20to%20Sale\">Try LifterLMS for $1</a></strong>.</p>\n<h4>I\'m interested in contributing to LifterLMS, how can I start?</h4>\n<p>LifterLMS is an open source project. We manage our team, developers, issues, and code on <a href=\"https://github.com/gocodebox/lifterlms/\">GitHub</a>.</p>\n<p>We welcome contributions of all kinds, anyone can contribute even if you don\'t write code! Check out our <a href=\"https://github.com/gocodebox/lifterlms/blob/master/.github/CONTRIBUTING.md\">Contributor\'s Guidelines</a> to get started.</p>\n<h4>I found a security vulnerability or issue, how can I report it to the team?</h4>\n<p>The LifterLMS team takes security issues and vulnerabilities very seriously. We appreciate your efforts to responsibly disclose your findings, and will make every effort to acknowledge your contributions.</p>\n<p>Please contact team@lifterlms.com to report a security vulnerability.</p>\n<p>You can review our full security policy at <a href=\"https://lifterlms.com/security-policy\">https://lifterlms.com/security-policy</a>.</p>\";s:9:\"Changelog\";s:3759:\"<h4>Changelog</h4><p>v7.3.0 - 2023-08-08</p><h5>Updates and Enhancements</h5>\n<ul>\n<li>When a notice is shown for an access plan on the course edit screen (e.g. When using the WooCommerce integration and no product has been associated to the access plan.) Also display a warning icon next to the access plan title.</li>\n<li>Made sure only who can <code>view_others_lifterlms_reports</code> will be able to see the analytics widget content in the WordPress admin.</li>\n<li>Better rounding of float values on some reporting screens.</li>\n<li>Avoid creating a post revision when cloning a course/lesson.</li>\n<li>When creating pages via <code>llms_create_pages()</code>: strip all tags from the page title and slash the page data prior to inserting the page in the db via <code>wp_insert_post()</code> to prevent slashes from being stripped from the page title.</li>\n<li>Updated the WordPress tested version up to 6.3.</li>\n<li>Improved compatibility with the Divi theme by fixing an issue with the quiz attempt result clarifications not being visible when the Divi option <code>Defer jQuery And jQuery Migrate</code> was enabled. <a href=\"https://github.com/gocodebox/lifterlms/issues/2470\">#2470</a></li>\n</ul>\n<h5>Bug Fixes</h5>\n<ul>\n<li>Fix spacer block when creating new certificate templates in WP 6.3.</li>\n<li>Fixed PHP Warning when no course/membership catalog page was set or if the selected page doesn\'t exist anymore. <a href=\"https://github.com/gocodebox/lifterlms/issues/2496\">#2496</a></li>\n<li>Don\'t include WordPress default sidebar.php template when using a block theme. <a href=\"https://github.com/gocodebox/lifterlms/issues/2488\">#2488</a></li>\n<li>Updated Kazakhstani Tenge\'s currency symbol. <a href=\"https://github.com/gocodebox/lifterlms/issues/2475\">#2475</a></li>\n<li>Make the dashboard widget visible only if the current user has LMS Manager capabilities. <a href=\"https://github.com/gocodebox/lifterlms/issues/2500\">#2500</a></li>\n<li>Fixed issue with LifterLMS Navigation Link block and block visibility settings. <a href=\"https://github.com/gocodebox/lifterlms/issues/2474\">#2474</a></li>\n<li>Use student dashboard as default value for navigation link block. <a href=\"https://github.com/gocodebox/lifterlms/issues/2465\">#2465</a></li>\n<li>Fixed typo in a function name that could potentially produce a fatal. Thanks <a href=\"https://github.com/kamalahmed\">@kamalahmed</a>!</li>\n</ul>\n<h5>Developer Notes</h5>\n<ul>\n<li>Added the parameter <code>$tab</code> (ID/slug of the tab) to the <code>lifterlms_reporting_tab_cap</code> filter hook. Thanks <a href=\"https://github.com/sapayth\">@sapayth</a>! <a href=\"https://github.com/gocodebox/lifterlms/issues/2468\">#2468</a></li>\n<li>Added new filter hook <code>llms_can_analytics_widget_be_processed</code> that will allow to filter wheteher or not an analytics widgegt can be processed/disoplayed.</li>\n<li>Added new filter <code>llms_install_get_pages</code>.</li>\n<li>Added new public static method <code>LLMS_Admin_Dashboard_Widget::get_dashboard_widget_data()</code>.</li>\n<li>Added <code>llms_dashboard_checklist</code> and <code>llms_dashboard_widget_data</code> filters to adjust dashboard content. <a href=\"https://github.com/gocodebox/lifterlms/issues/2491\">#2491</a></li>\n</ul>\n<h5>Updated Templates</h5>\n<ul>\n<li><a href=\"https://github.com/gocodebox/lifterlms/blob/7.3.0/templates/admin/reporting/tabs/widgets.php\">templates/admin/reporting/tabs/widgets.php</a></li>\n<li><a href=\"https://github.com/gocodebox/lifterlms/blob/7.3.0/templates/global/sidebar.php\">templates/global/sidebar.php</a></li>\n<li><a href=\"https://github.com/gocodebox/lifterlms/blob/7.3.0/templates/quiz/results-attempt-questions-list.php\">templates/quiz/results-attempt-questions-list.php</a></li>\n</ul>\";s:6:\"Author\";s:9:\"LifterLMS\";s:9:\"AuthorURI\";s:22:\"https://lifterlms.com/\";s:8:\"Download\";s:52:\"https://downloads.wordpress.org/plugin/lifterlms.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"LifterLMS\";}i:55;a:16:{s:4:\"Name\";s:35:\"Paid Memberships Pro - Limit Logins\";s:5:\"Title\";s:35:\"Paid Memberships Pro - Limit Logins\";s:9:\"PluginURI\";s:56:\"https://www.paidmembershipspro.com/add-ons/limit-logins/\";s:4:\"Slug\";s:18:\"pmpro-limit-logins\";s:6:\"plugin\";s:41:\"pmpro-limit-logins/pmpro-limit-logins.php\";s:7:\"Version\";s:3:\"1.6\";s:11:\"Description\";s:93:\"Deter members from sharing login credentials: restrict simultaneous logins for the same user.\";s:12:\"Installation\";s:471:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-limit-logins</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate the plugin through the <code>Plugins</code> menu in WordPress.</li>\n</ol>\n<h3>Settings</h3>\n<p>There are no settings for this plugin. If you want to modify the default behavior to instead enable JavaScript checks, add the following code to your wp-config.php:</p>\n<p>define( \'PMPRO_LIMIT_LOGINS_HEARTBEAT_CHECK\', true );</p>\";s:3:\"FAQ\";s:322:\"<p>Frequently Asked Questions</p><p>I need something strong to keep people from sharing accounts.</p><p>We\'ve found that using a 2-Factor-Authentication scheme on your site is a good way to keep people from sharing accounts. When we tried to design an advanced version of WP-Bouncer, it was basically 2FA. So try that.</p>\";s:9:\"Changelog\";s:389:\"<h4>Changelog</h4><p>1.6 - 2025-01-20</p><ul>\n<li>REFACTOR: Renamed to Paid Memberships Pro - Limit Logins</li>\n<li>ENHANCEMENT: New filters added to match new name, previous filters maintained for backward compatibility. Please replace <code>wp_bouncer_</code> with <code>pmpro_limit_logins_</code> in code. </li>\n<li>ENHANCEMENT: Automatically deactivate WP Bouncer if active.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:31:\"https://www.strangerstudios.com\";s:8:\"Download\";s:80:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-limit-logins.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:12:\"Limit Logins\";}i:56;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Limit Post Views Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Limit Post Views Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/pmpro-limit-post-views/\";s:4:\"Slug\";s:22:\"pmpro-limit-post-views\";s:6:\"plugin\";s:49:\"pmpro-limit-post-views/pmpro-limit-post-views.php\";s:7:\"Version\";s:5:\"1.0.2\";s:11:\"Description\";s:115:\"Integrates with Paid Memberships Pro to limit the number of times members and visitors can view posts on your site.\";s:12:\"Installation\";s:501:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-limit-post-views</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Configure settings on the Limit Post Views settings page.</li>\n<li>Make sure your PMPro levels page mentions the post viewing limit so users know why they are being redirected.</li>\n</ol>\";s:3:\"FAQ\";s:513:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-limit-post-views/issues\">https://github.com/strangerstudios/pmpro-limit-post-views/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:201:\"<h4>Changelog</h4><p>1.0.2 - 2025-07-18</p><ul>\n<li>BUG FIX: Fixed an issue where users could view restricted content if their membership level did not have a view limit set. #69 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-limit-post-views.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Limit Post Views\";}i:57;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - Local Pricing\";s:5:\"Title\";s:36:\"Paid Memberships Pro - Local Pricing\";s:9:\"PluginURI\";s:57:\"https://www.paidmembershipspro.com/add-ons/local-pricing/\";s:4:\"Slug\";s:19:\"pmpro-local-pricing\";s:6:\"plugin\";s:43:\"pmpro-local-pricing/pmpro-local-pricing.php\";s:7:\"Version\";s:5:\"1.1.2\";s:11:\"Description\";s:151:\"Dynamically convert level pricing at checkout to the approximate rate in the visitor\'s local currency, as detected by their IP address and geolocation.\";s:12:\"Installation\";s:971:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-local-pricing</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Memberships &gt; Settings &gt; Payment Gateway.</li>\n<li>Enter your App ID and save settings.</li>\n</ol>\n<p>Note: currency conversions are processed using the <a href=\"https://openexchangerates.org/\">https://openexchangerates.org/</a> API. If your site\'s default currency is USD, you can use an API key linked to a free account at <a href=\"https://openexchangerates.org/\">https://openexchangerates.org/</a>. All other currencies will require a paid plan with the API provider.</p>\n<p>Refer to the <a href=\"https://www.paidmembershipspro.com/add-ons/local-pricing/\">Local Pricing Add On documentation page</a> for more information on how to set up this Add On or for a code recipe to offer unique discount codes based on location.</p>\";s:3:\"FAQ\";s:33:\"<p>Frequently Asked Questions</p>\";s:9:\"Changelog\";s:652:\"<h4>Changelog</h4><p>1.1.2 - 2026-05-15</p><ul>\n<li>ENHANCEMENT: Added a new filter <code>pmpro_local_pricing_custom_exchange_rate</code> that allows developers to short-circuit the exchange rate lookup with a custom rate source (alternative API, local data, hardcoded values, etc.). #17 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Added a defensive check to prevent a stale transient from being set when the exchange rate API response is missing the <code>rates</code> property. #17 (@dparker1005)</li>\n<li>BUG FIX: Resolved an issue where the settings version check could error if Paid Memberships Pro was deactivated. #16 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:80:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-local-pricing.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:13:\"Local Pricing\";}i:58;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Lock Membership Level\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Lock Membership Level\";s:9:\"PluginURI\";s:71:\"https://www.paidmembershipspro.com/add-ons/pmpro-lock-membership-level/\";s:4:\"Slug\";s:27:\"pmpro-lock-membership-level\";s:6:\"plugin\";s:59:\"pmpro-lock-membership-level/pmpro-lock-membership-level.php\";s:7:\"Version\";s:5:\"1.0.2\";s:11:\"Description\";s:61:\"Lock membership level changes for specific users or by level.\";s:12:\"Installation\";s:611:\"<p>Installation</p><ol>\n<li>Make sure you have Paid Memberships Pro installed and activated.</li>\n<li>Upload the <code>pmpro-lock-membership-level</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Add a new page for the \"Membership Locked\" message and assign it under Memberships &gt; Page settings. This is the page that members will be redirected to when attempting to cancel or change membership.</li>\n<li>Add the shortcode [pmpro_membership_locked] to that page. The shortcode\'s only attribute \"message\" can be used to customize the default message shown.</li>\n</ol>\";s:3:\"FAQ\";s:525:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-lock-membership-level/issues\">https://github.com/strangerstudios/pmpro-lock-membership-level/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:455:\"<h4>Changelog</h4><p>1.0.2 - 2026-05-01</p><ul>\n<li>ENHANCEMENT: Added a hint and proper <code>&lt;label&gt;</code> to the Membership Level field in the Locked Memberships panel of the Edit Member page to clarify how the setting works. #35 (@flintfromthebasement)</li>\n<li>ENHANCEMENT: Added a \"Learn more\" link to the Lock Membership Level Add On documentation in the level settings section on the Edit Membership Level page. #34 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:88:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-lock-membership-level.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:21:\"Lock Membership Level\";}i:59;a:16:{s:4:\"Name\";s:34:\"Paid Memberships Pro - Magic Login\";s:5:\"Title\";s:34:\"Paid Memberships Pro - Magic Login\";s:9:\"PluginURI\";s:55:\"https://www.paidmembershipspro.com/add-ons/magic-login/\";s:4:\"Slug\";s:17:\"pmpro-magic-login\";s:6:\"plugin\";s:39:\"pmpro-magic-login/pmpro-magic-login.php\";s:7:\"Version\";s:5:\"1.0.1\";s:11:\"Description\";s:71:\"Adds passwordless login via secure email links to Paid Memberships Pro.\";s:12:\"Installation\";s:335:\"<p>Installation</p><ol>\n<li>Upload the plugin files to the <code>/wp-content/plugins/pmpro-magic-login</code> directory, or install the plugin through the WordPress plugins screen directly.</li>\n<li>Activate the plugin through the \'Plugins\' screen in WordPress.</li>\n<li>Paid Memberships Pro must be installed and activated.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:262:\"<h4>Changelog</h4><p>1.0.1 - 2026-07-21</p><ul>\n<li>BUG FIX: Fixed the Magic Login button in the PMPro Login Widget by loading required assets when the widget is displayed. #2 (@andrewlimaza, @dparker1005)</li>\n</ul><p>1.0</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:78:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-magic-login.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:11:\"Magic Login\";}i:60;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Mailchimp Add On\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Mailchimp Add On\";s:9:\"PluginURI\";s:71:\"https://www.paidmembershipspro.com/add-ons/pmpro-mailchimp-integration/\";s:4:\"Slug\";s:15:\"pmpro-mailchimp\";s:6:\"plugin\";s:35:\"pmpro-mailchimp/pmpro-mailchimp.php\";s:7:\"Version\";s:5:\"2.4.1\";s:11:\"Description\";s:63:\"Sync your WordPress users and members with Mailchimp audiences.\";s:12:\"Installation\";s:1523:\"<p>Installation</p><p>This plugin works with and without Paid Memberships Pro installed.</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-mailchimp</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to Settings &gt; PMPro Mailchimp to proceed with setup.</li>\n</ol><p>Configuration and Settings</p><p><strong>Enter your Mailchimp API Key:</strong> Your Mailchimp API key can be found within your Mailchimp account under Account &gt; Extras &gt; API keys. If you don\'t have a Mailchimp account, <a href=\"http://eepurl.com/k4aAH\">you can create one here</a>. Read our documentation for a <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-mailchimp-integration/#api-key\">video demonstrating how to locate your Mailchimp API key</a>.</p>\n<p>After entering your API Key, continue with the setup by assigning User or Member Audiences and reviewing the additional settings.</p>\n<p>For full documentation on all settings, please visit the <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-mailchimp-integration/\">Mailchimp Integration Add On documentation page at Paid Memberships Pro</a>. </p>\n<p>Several action and filter hooks are available for developers that need to customize specific aspects of the integration. <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-mailchimp-integration/#hooks\">Please explore the plugin\'s action and filter hooks here</a>.</p>\";s:3:\"FAQ\";s:548:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-mailchimp/issues\">https://github.com/strangerstudios/pmpro-mailchimp/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit <a href=\"https://www.paidmembershipspro.com/\">our support site at https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:593:\"<h4>Changelog</h4><p>2.4.1 - 2026-05-14</p><ul>\n<li>ENHANCEMENT: Profile updates now only push changes to Mailchimp audiences associated with the user\'s current membership levels, opt-in lists, or non-member lists. This avoids unnecessary API calls and prevents merge fields from being overwritten on audiences configured for other sites that share the same Mailchimp account. #148 (@dwanjuki)</li>\n<li>ENHANCEMENT: Added a notice to the WordPress debug log when a Mailchimp API call returns an error, pointing administrators to the PMPro Mailchimp log for details. #150 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:72:\"http://license.paidmembershipspro.com/downloads/free/pmpro-mailchimp.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Mailchimp\";}i:61;a:16:{s:4:\"Name\";s:40:\"Paid Memberships Pro - MailerLite Add On\";s:5:\"Title\";s:40:\"Paid Memberships Pro - MailerLite Add On\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/mailerlite-integration/\";s:4:\"Slug\";s:16:\"pmpro-mailerlite\";s:6:\"plugin\";s:37:\"pmpro-mailerlite/pmpro-mailerlite.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:105:\"Connect Paid Memberships Pro to MailerLite to add members as subscribers and manage groups automatically.\";s:12:\"Installation\";s:224:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-mailerlite</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:309:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-mailerlite/issues\">https://github.com/strangerstudios/pmpro-mailerlite/issues</a></p>\";s:9:\"Changelog\";s:77:\"<h4>Changelog</h4><p>1.0 - 2026-06-25</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:73:\"http://license.paidmembershipspro.com/downloads/free/pmpro-mailerlite.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:10:\"MailerLite\";}i:62;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - Mailing Add On\";s:5:\"Title\";s:37:\"Paid Memberships Pro - Mailing Add On\";s:9:\"PluginURI\";s:80:\"https://www.paidmembershipspro.com/add-ons/shipping-address-membership-checkout/\";s:4:\"Slug\";s:14:\"pmpro-shipping\";s:6:\"plugin\";s:33:\"pmpro-shipping/pmpro-shipping.php\";s:7:\"Version\";s:5:\"2.0.1\";s:11:\"Description\";s:73:\"Add mailing or shipping address to the checkout page and other locations.\";s:12:\"Installation\";s:515:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-shipping</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>Fields will automatically be captured for all membership levels. You can remove the fields for a level on the Memberships &gt; Settings &gt; Edit Membership Level &gt; \"Hide Mailing Address\" ssetting.</p>\";s:3:\"FAQ\";s:497:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-shipping/issues\">https://github.com/strangerstudios/pmpro-shipping/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:228:\"<h4>Changelog</h4><p>2.0.1 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Updated the Edit Level settings UI to match modern PMPro 3.x conventions and added a link to the Mailing Address Add On documentation. #66 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:75:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-shipping.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:7:\"Mailing\";}i:63;a:16:{s:4:\"Name\";s:31:\"Paid Memberships Pro - MailPoet\";s:5:\"Title\";s:31:\"Paid Memberships Pro - MailPoet\";s:9:\"PluginURI\";s:64:\"https://www.paidmembershipspro.com/add-ons/mailpoet-integration/\";s:4:\"Slug\";s:36:\"mailpoet-paid-memberships-pro-add-on\";s:6:\"plugin\";s:77:\"mailpoet-paid-memberships-pro-add-on/mailpoet-paid-memberships-pro-add-on.php\";s:7:\"Version\";s:3:\"3.4\";s:11:\"Description\";s:107:\"Automatically subscribe members to MailPoet lists or allow them to opt-in to specific MailPoet newsletters.\";s:12:\"Installation\";s:2420:\"<p>Installation</p><p>Note: You must have <a href=\"https://www.paidmembershipspro.com\">Paid Memberships Pro</a> installed and activated on your site.</p>\n<h3>Install PMPro MailPoet from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro MailPoet\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - MailPoet Add On\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro MailPoet Manually</h3>\n<ol>\n<li>Upload the <code>MailPoet-Paid-Memberships-Pro-Add-on</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - MailPoet Integration\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Configure Membership Settings for MailPoet</h3>\n<p>Below is a description of the various settings available in the plugin. Navigate to Memberships &gt; MailPoet in the WordPress admin to configure the plugin for your site</p>\n<ul>\n<li>Non-Members List: Users are automatically subscribed to non-member lists when they register without a membership level or when their membership level is removed.</li>\n<li>Opt-In List: Give users the option to subscribe to additional lists at checkout and on their profile page.</li>\n<li>Membership Lists: Assign MailPoet subscriptions to each membership. Members are automatically subscribed to these lists during checkout or after membership level changes. You can add members to a single list or multiple lists depending on your needs.</li>\n<li>Unsubscribe On Level Change? Choose whether subscribers should be removed from their level lists when their membership changes. This setting unsubscribes members from their current levelâ€™s list when they cancel, expire, or otherwise change their membership level.</li>\n</ul>\n<h3>Import Current Members to MailPoet</h3>\n<p>This integration plugin does not perform a retroactive update of all membership levels &gt; subscriber list settings. If you want to start using MailPoet and you already have members, you must complete a one-time import to sync MailPoet subscribers and members.</p>\n<p><a href=\"https://www.paidmembershipspro.com/import-members-to-mailpoet-lists/\">View the Guide: How to Import Your PMPro Members List to MailPoet Subscriber Lists Â»</a></p>\";s:3:\"FAQ\";s:589:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/MailPoet-Paid-Memberships-Pro-Add-on/issues\">https://github.com/strangerstudios/MailPoet-Paid-Memberships-Pro-Add-on/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit <a href=\"http://www.paidmembershipspro.com/\">our support site at https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:645:\"<h4>Changelog</h4><p>3.4 - 2026-06-18</p><ul>\n<li>ENHANCEMENT: Added support for tagging in MailPoet. #22 (@andrewlimaza,@kimcoleman)</li>\n</ul><p>3.3.2 - 2025-12-09</p><ul>\n<li>BUG FIX: Fixed an issue where the plugin notice would show even if you are using the latest version of MailPoet. #19 (@dwanjuki)</li>\n</ul><p>3.3.1 - 2024-11-05 = </p>\n<ul>\n<li>ENHANCEMENT: Renamed plugin\'s file to match that of the plugin slug. Fixes automatic update issues.</li>\n</ul>\n<p>= 3.3 - 2024-10-17</p><ul>\n<li>FEATURE: Now updating the plugin from paidmembershipspro.com.</li>\n<li>ENHANCEMENT: Updated translation files bundled with the plugin.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:93:\"http://license.paidmembershipspro.com/downloads/free/mailpoet-paid-memberships-pro-add-on.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:8:\"MailPoet\";}i:64;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - Member Badges\";s:5:\"Title\";s:36:\"Paid Memberships Pro - Member Badges\";s:9:\"PluginURI\";s:57:\"https://www.paidmembershipspro.com/add-ons/member-badges/\";s:4:\"Slug\";s:19:\"pmpro-member-badges\";s:6:\"plugin\";s:43:\"pmpro-member-badges/pmpro-member-badges.php\";s:7:\"Version\";s:5:\"1.1.1\";s:11:\"Description\";s:115:\"Assign unique member badges (images) to each membership level and display via a shortcode or template PHP function.\";s:12:\"Installation\";s:417:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-member-badges</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit your membership levels to upload badges images.</li>\n<li>Use the [pmpro_member_badge] shortcode or the <code>pmpromb_show_badge()</code> function to show a badge on your site.</li>\n</ol>\";s:3:\"FAQ\";s:563:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-member-badges/issues\">https://github.com/strangerstudios/pmpro-member-badges/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:394:\"<h4>Changelog</h4><p>1.1.1 - 2026-05-01</p><ul>\n<li>ENHANCEMENT: Added a section heading and \"Learn more about Member Badges\" documentation link to the Edit Membership Level settings page. #20 (@kimcoleman)</li>\n<li>BUG FIX: Fixed a PHP 8.1+ deprecation notice in <code>pmpromb_show_badge()</code> caused by optional parameters declared before a required parameter. #19 (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:80:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-member-badges.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:13:\"Member Badges\";}i:65;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Member Directory Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Member Directory Add On\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/member-directory/\";s:4:\"Slug\";s:22:\"pmpro-member-directory\";s:6:\"plugin\";s:49:\"pmpro-member-directory/pmpro-member-directory.php\";s:7:\"Version\";s:5:\"2.3.1\";s:11:\"Description\";s:81:\"Adds a customizable Member Directory and Member Profiles to your membership site.\";s:12:\"Installation\";s:652:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-member-directory</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the <code>Plugins</code> menu in WordPress.</li>\n<li>Create a page for your directory and set the appropriate shortcode attributes and <code>Require Membership</code> settings per your needs.</li>\n<li>Create a page for your profile and set the appropriate shortcode attributes and <code>Require Membership</code> settings per your needs.</li>\n<li>Navigate to Memberships &gt; Page Settings to assign your pages to the Directory and Profile page settings.</li>\n</ol>\";s:3:\"FAQ\";s:567:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-member-directory/issues\">https://github.com/strangerstudios/pmpro-member-directory/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:2049:\"<h4>Changelog</h4><p>2.3.1 - 2026-08-19</p><ul>\n<li>SECURITY: Fixed an issue where profiles for members who are hidden from the directory, do not have an active membership, or are pending approval could still be viewed when the profile shortcode or block was placed on a page other than the assigned profile page. #233 (@flintfromthebasement)</li>\n<li>ENHANCEMENT: Members with an active membership can now view their own profile even if they are hidden from the directory or pending approval. #233 (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed the security check for testing the Google Maps API key so that the test only runs when saving the PMPro Advanced Settings page. #233 (@flintfromthebasement)</li>\n</ul><p>2.3 - 2026-06-22</p><ul>\n<li>ENHANCEMENT: Implemented caching logic for displaying the directory to help improve overall performance. (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed an issue where the Google Map would sometimes not load correctly on the directory page. (@andrewlimaza)</li>\n</ul><p>2.2 - 2026-05-06</p><ul>\n<li>ENHANCEMENT: Added marker clustering functionality for Google Maps. Markers are grouped into clusters at lower zoom levels and can be toggled via the new <code>pmpromd_map_cluster_markers</code> filter. #218 (@andrewlimaza)</li>\n<li>BUG FIX: Fixed member start/end date calculations when some membership levels do not have an expiration date. #224 (@kimcoleman)</li>\n<li>BUG FIX: The <code>show_map</code> attribute on the <code>[pmpro_member_profile]</code> shortcode now correctly accepts string values like <code>\"false\"</code>. #227 (@JarrydLong)</li>\n<li>BUG FIX: Resolved console warnings and errors in the Member Directory and Member Profile blocks, fixed a <code>webpack.config.js</code> build error, and updated block components to follow current WordPress component patterns. #222 (@dwanjuki)</li>\n<li>REFACTOR: Removed use of the deprecated <code>SQL_CALC_FOUND_ROWS</code> SELECT modifier. The total row count is now derived from the directory query without it. #225 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-member-directory.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Member Directory\";}i:66;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Member History Add On\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Member History Add On\";s:9:\"PluginURI\";s:64:\"https://www.paidmembershipspro.com/add-ons/pmpro-member-history/\";s:4:\"Slug\";s:20:\"pmpro-member-history\";s:6:\"plugin\";s:45:\"pmpro-member-history/pmpro-member-history.php\";s:7:\"Version\";s:4:\".3.1\";s:11:\"Description\";s:77:\"Display a history of a user\'s Membership on the User Profile for admins only.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:82:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-member-history.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:14:\"Member History\";}i:67;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Member Homepages Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Member Homepages Add On\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/member-homepages/\";s:4:\"Slug\";s:22:\"pmpro-member-homepages\";s:6:\"plugin\";s:49:\"pmpro-member-homepages/pmpro-member-homepages.php\";s:7:\"Version\";s:5:\"0.3.2\";s:11:\"Description\";s:75:\"Redirect members to a unique homepage or landing page based on their level.\";s:12:\"Installation\";s:358:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-member-homepages</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit your membership levels to assign a level\'s homepage and configure settings.</li>\n</ol>\";s:3:\"FAQ\";s:569:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-member-homepages/issues\">https://github.com/strangerstudios/pmpro-member-homepages/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:677:\"<h4>Changelog</h4><p>0.3.2 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Added a \"Learn more\" link to the Membership Homepage settings section on the Edit Membership Level page pointing to the Add On documentation. (@kimcoleman)</li>\n<li>ENHANCEMENT: Adjusted the markup of the Membership Homepage settings (heading level, label associations, and consistent escaping) for better accessibility and consistency with WordPress core admin conventions. (@kimcoleman)</li>\n<li>BUG FIX: Fixed an issue where the member homepage redirect could prevent the WordPress theme/plugin file editor from saving PHP changes by interfering with the loopback fatal-error check. #41 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-member-homepages.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Member Homepages\";}i:68;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Member Network Sites Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Member Network Sites Add On\";s:9:\"PluginURI\";s:78:\"https://www.paidmembershipspro.com/add-ons/pmpro-network-multisite-membership/\";s:4:\"Slug\";s:13:\"pmpro-network\";s:6:\"plugin\";s:31:\"pmpro-network/pmpro-network.php\";s:7:\"Version\";s:3:\"0.6\";s:11:\"Description\";s:76:\"Create a network site for the member as part of membership to the main site.\";s:12:\"Installation\";s:429:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Make sure you have properly configured Network Sites on your WordPress Multisite.</li>\n<li>Upload the \'pmpro-network\' directory to the \'/wp-content/plugins/\' directory of your site.</li>\n<li>Activate the plugin on the main site (the primary domaoin of the network) through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:497:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-network/issues\">https://github.com/strangerstudios/pmpro-network/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:1842:\"<h4>Changelog</h4><p>0.6 - 2026-04-30</p><ul>\n<li>ENHANCEMENT: Refreshed the Site Information section on the membership checkout page to use the v3.1 form classes and markup. #34 (@MaximilianoRicoTabo)</li>\n<li>ENHANCEMENT: Added a \"Site Credits\" panel on the v3.1 Edit Member dashboard page showing the member\'s site credits and a list of their network sites with links to visit each site or its dashboard. #33 #37 (@MaximilianoRicoTabo, @dparker1005)</li>\n<li>ENHANCEMENT: The \"Site Credits\" header on the Edit Membership Level page is now an <code>&lt;h3&gt;</code> to fit under the v3.1 heading hierarchy, and the plugin now bails at load on single-site installs. #32 (@MaximilianoRicoTabo)</li>\n<li>ENHANCEMENT: Site creation and reactivation failures are now appended to the order notes for easier debugging. <code>$_REQUEST</code> values used at checkout are now sanitized with <code>sanitize_text_field()</code> and <code>wp_unslash()</code>. #36 (@dwanjuki)</li>\n<li>ENHANCEMENT: Updated the link to the Memberlite theme in the readme. #35 (@kimwhite)</li>\n<li>BUG FIX/ENHANCEMENT: Network site provisioning now works correctly for offsite and delayed checkout flows (PayPal Express, PayFast, Stripe Checkout, Pay By Check). The plugin reads site details from <code>$_REQUEST</code> after PMPro core repopulates it from order meta, and <code>pmpron_addSite()</code> now accepts an optional <code>$user_id</code> argument so sites can be created for the right user during webhook-driven and admin-initiated completions. #36 (@dwanjuki)</li>\n<li>DEPRECATED: Removed the deprecated <code>pmpro_paypalexpress_session_vars</code> hook callback. PMPro core\'s <code>pmpro_save_checkout_data_to_order</code> / <code>pmpro_pull_checkout_data_from_order</code> mechanism handles offsite gateway data persistence now. #36 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:74:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-network.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Member Network Sites\";}i:69;a:16:{s:4:\"Name\";s:40:\"Paid Memberships Pro - Member RSS Add On\";s:5:\"Title\";s:40:\"Paid Memberships Pro - Member RSS Add On\";s:9:\"PluginURI\";s:54:\"http://www.paidmembershipspro.com/wp/pmpro-member-rss/\";s:4:\"Slug\";s:16:\"pmpro-member-rss\";s:6:\"plugin\";s:37:\"pmpro-member-rss/pmpro-member-rss.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:57:\"Create Member-Specific RSS Feeds for Paid Memberships Pro\";s:12:\"Installation\";s:224:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-member-rss</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:555:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-member-rss/issues\">https://github.com/strangerstudios/pmpro-member-rss/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:1164:\"<h4>Changelog</h4><p>1.0 - 2026-04-08</p><ul>\n<li>FEATURE: Added \"Allow Memberkey as Basic Auth Password\" setting. Members can use their memberkey as the password field in Basic Authentication, allowing RSS readers without application password support to authenticate securely.</li>\n<li>FEATURE: Added \"Disable Memberkey in URL\" setting. When enabled, feed authentication via the memberkey URL parameter is blocked and members must use Basic Authentication instead.</li>\n<li>FEATURE: Added <code>[pmpromrss_feeds]</code> shortcode and \"Member RSS Feeds\" PMPro page setting. Provides a dedicated member-facing page for feed management, key display, regeneration, and authentication guidance.</li>\n<li>ENHANCEMENT: When the feeds page is configured, the Membership Account page \"Member RSS Feed\" links to the dedicated page instead of inline feed URLs.</li>\n<li>ENHANCEMENT: Updated the regenerate key confirmation to mention that RSS readers will need to be updated.</li>\n<li>ENHANCEMENT: Improved messaging/hint around the Feed Authentication settings to clarify how to authenticate RSS feeds, including both Edit Member Panel and Frontend instructions.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:77:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-member-rss.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:10:\"Member RSS\";}i:70;a:16:{s:4:\"Name\";s:19:\"Memberlite Elements\";s:5:\"Title\";s:19:\"Memberlite Elements\";s:9:\"PluginURI\";s:52:\"https://www.memberlitetheme.com/memberlite-elements/\";s:4:\"Slug\";s:19:\"memberlite-elements\";s:6:\"plugin\";s:43:\"memberlite-elements/memberlite-elements.php\";s:7:\"Version\";s:3:\"1.1\";s:11:\"Description\";s:86:\"A set of elements designed enhance the appearance of sites using the Memberlite Theme.\";s:12:\"Installation\";s:679:\"<p>Installation</p><p>Download, Install and Activate</p><p>In your WordPress admin, go to Plugins &gt; Add New to install Memberlite Shortcodes, or:</p>\n<ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /memberlite-elements/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>Start Using the Elements!</p><p>Browse the Memberlite Elements documentation to see all features, their attributes, and to view sample demos.</p>\n<p><a href=\"https://memberlitetheme.com/memberlite-elements/\">View Documentation</a></p>\";s:3:\"FAQ\";s:650:\"<p>Frequently Asked Questions</p><p>Where can I find Memberlite Elements documentation and user guides?</p><p>For help setting up and configuring the Memberlite Elements plugin, please refer to <a href=\"https://memberlitetheme.com/memberlite-elements/\">documentation</a>.</p><p>Where can I get the Memberlite Theme?</p><p>Visit <a href=\"https://memberlitetheme.com\">https://memberlitetheme.com</a> to get your copy of the Memberlite Theme.</p><p>I\'m not using the Memberlite Theme - can I still use Memberlite Elements plugin?</p><p>As of this release, Memberlite Elements is only compatible with the Memberlite Theme or a Memberlite Child Theme.</p>\";s:9:\"Changelog\";s:202:\"<h4>Changelog</h4><p>1.1.0 - 2023-09-21</p><ul>\n<li>SECURITY: Improved sanitization and escaping of elements.</li>\n<li>REFACTOR: Improved accessibility for screen readers and plugin settings.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:31:\"https://www.memberlitetheme.com\";s:8:\"Download\";s:62:\"https://downloads.wordpress.org/plugin/memberlite-elements.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:19:\"Memberlite Elements\";}i:71;a:16:{s:4:\"Name\";s:21:\"Memberlite Shortcodes\";s:5:\"Title\";s:21:\"Memberlite Shortcodes\";s:9:\"PluginURI\";s:82:\"https://www.paidmembershipspro.com/documentation/memberlite/memberlite-shortcodes/\";s:4:\"Slug\";s:21:\"memberlite-shortcodes\";s:6:\"plugin\";s:47:\"memberlite-shortcodes/memberlite-shortcodes.php\";s:7:\"Version\";s:5:\"1.4.1\";s:11:\"Description\";s:82:\"Shortcodes designed to work with the Memberlite Theme and Memberlite Child Themes.\";s:12:\"Installation\";s:731:\"<p>Installation</p><p>Download, Install and Activate</p><p>In your WordPress admin, go to Plugins &gt; Add New to install Memberlite Shortcodes, or:</p>\n<ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /memberlite-shortcodes/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>Start Using the Shortcodes!</p><p>Browse the Memberlite Shortcodes documentation to see all shortcodes, their attributes, and to view sample shortcode demos.</p>\n<p><a href=\"https://www.paidmembershipspro.com/documentation/memberlite/memberlite-shortcodes/\">View Documentation</a></p>\";s:3:\"FAQ\";s:765:\"<p>Frequently Asked Questions</p><p>Where can I find Memberlite Shortcodes documentation and user guides?</p><p>For help setting up and configuring the Memberlite Shortcodes plugin, please refer to <a href=\"https://www.paidmembershipspro.com/documentation/memberlite/memberlite-shortcodes/\">documentation</a>.</p><p>Where can I get the Memberlite Theme?</p><p>Visit <a href=\"https://www.paidmembershipspro.com/themes/memberlite/\">https://www.paidmembershipspro.com/themes/memberlite/</a> to get your copy of the Memberlite Theme.</p><p>I\'m not using the Memberlite Theme - can I still use Memberlite Shortcodes plugin?</p><p>Some of the shortcodes in this plugin will work with any theme, but we cannot guarantee the appearance will match that of the demo site.</p>\";s:9:\"Changelog\";s:278:\"<h4>Changelog</h4><p>1.4.1 - 2025-09-10</p><ul>\n<li>SECURITY: Sanitized and escaped <code>class</code> shortcode attribute in the <code>row</code> shortcode.</li>\n<li>ENHANCEMENT: Updated links to theme details and docs now hosted on the Paid Memberships Pro website.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:64:\"https://downloads.wordpress.org/plugin/memberlite-shortcodes.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:21:\"Memberlite Shortcodes\";}i:72;a:16:{s:4:\"Name\";s:59:\"Paid Memberships Pro - MemberPress Migration Toolkit Add On\";s:5:\"Title\";s:59:\"Paid Memberships Pro - MemberPress Migration Toolkit Add On\";s:9:\"PluginURI\";s:86:\"https://www.paidmembershipspro.com/add-ons/pmpro-memberpress-migration-toolkit-add-on/\";s:4:\"Slug\";s:35:\"pmpro-memberpress-migration-toolkit\";s:6:\"plugin\";s:75:\"pmpro-memberpress-migration-toolkit/pmpro-memberpress-migration-toolkit.php\";s:7:\"Version\";s:5:\"0.1.1\";s:11:\"Description\";s:93:\"Tools to help you migrate your membership site data from MemberPress to Paid Memberships Pro.\";s:12:\"Installation\";s:227:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-memberpress-migration-toolkit</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1921:\"<h4>Changelog</h4><p>0.1.1 - 2026-06-17</p><ul>\n<li>ENHANCEMENT: User migrations are now queued in batches to avoid timeouts when migrating large sites. #9 (@dparker1005)</li>\n<li>ENHANCEMENT: Added dependency guards so the migration tools fail gracefully when Paid Memberships Pro is not active. #6 (@dparker1005)</li>\n<li>ENHANCEMENT: The Stripe Secret Key field on the Migrate Users step is now a password input. #13 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: No longer creating $0 orders when migrating MemberPress \'confirmed\' subscription-confirmation transactions. #10 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Cleaned up the Migrate Levels step, fixing the hidden \"no levels found\" message and correcting the level query ordering. #12 (@dparker1005)</li>\n<li>BUG FIX: Fixed a query that left core PMPro pages (checkout, account, etc.) restricted after migrating \"all pages\"/\"all content\" rules. #2 (@dparker1005)</li>\n<li>BUG FIX: Category and tag content restrictions now migrate correctly by looking up terms by slug. #1 (@dparker1005)</li>\n<li>BUG FIX: Content restriction inserts now use INSERT IGNORE to avoid duplicate-key database errors on re-runs and overlapping rules. #11 (@dparker1005)</li>\n<li>BUG FIX: Lifetime memberships (MemberPress \'0000-00-00 00:00:00\') are now migrated as non-expiring instead of expired. #4 (@dparker1005)</li>\n<li>BUG FIX: Already-expired memberships are migrated with an \'expired\' status directly, preventing a mass \"Membership Expired\" email blast. #3 (@dparker1005)</li>\n<li>BUG FIX: Migrated orders are no longer incorrectly recorded under the Stripe gateway. #5 (@dparker1005)</li>\n<li>BUG FIX: Existing PMPro user field groups are now preserved instead of overwritten when migrating custom fields. #7 (@dparker1005)</li>\n<li>BUG FIX: Migration steps no longer briefly display as completed while their queued actions are still running. #13 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:92:\"http://license.paidmembershipspro.com/downloads/free/pmpro-memberpress-migration-toolkit.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:29:\"MemberPress Migration Toolkit\";}i:73;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Membership Card Add On\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Membership Card Add On\";s:9:\"PluginURI\";s:59:\"http://www.paidmembershipspro.com/wp/pmpro-membership-card/\";s:4:\"Slug\";s:21:\"pmpro-membership-card\";s:6:\"plugin\";s:47:\"pmpro-membership-card/pmpro-membership-card.php\";s:7:\"Version\";s:3:\"2.1\";s:11:\"Description\";s:81:\"Display a printable Membership Card for Paid Memberships Pro members or WP users.\";s:12:\"Installation\";s:736:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-membership-card</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Create a page and add the [pmpro_membership_card] shortcode to it.</li>\n<li>(Optional) The page\'s \"featured image\" will be added to the membership card.</li>\n<li>(Optional) Specify the shortcode attribute \'print_size\'. Options include: small, medium, large or all. Default is: all. (ex: [pmpro_membership_card print_size=\"small,medium\"])</li>\n<li>(Optional) Copy the pmpro-membership-card/templates/membership-card.php file to your active theme\'s directory and edit it to change the card template.</li>\n</ol>\";s:3:\"FAQ\";s:319:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-membership-card/issues\">https://github.com/strangerstudios/pmpro-membership-card/issues</a></p>\";s:9:\"Changelog\";s:1545:\"<h4>Changelog</h4><p>2.1 - 2026-07-22</p><ul>\n<li>FEATURE: Added the <code>next_payment_date</code> and <code>membership_enddate_or_next_payment_date</code> card elements. #76 (@M4rkWilhelm, @dparker1005)</li>\n</ul><p>2.0.1 - 2026-02-03</p><ul>\n<li>BUG FIX: Fixed an issue where the membership card CSS was negatively affecting blog posts and featured images on certain themes. #75 (@andrewlimaza)</li>\n</ul><p>2.0 - 2026-01-27</p><ul>\n<li>FEATURE: Added a new membership card block for the WordPress Block Editor. #74 (@RachelRVasquez)</li>\n<li>FEATURE: Introduced a new elements attribute for the [pmpro_membership_card] shortcode, with automatic fallback to the legacy card layout when omitted. #72 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added support for displaying the site logo via site_logo (and retained featured_image support). #72 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added new customization filters: pmpro_membership_card_left, pmpro_membership_card_right, and pmpro_membership_card_get_display_value. #72 (@kimcoleman)</li>\n<li>ENHANCEMENT: Refactored plugin structure by moving template/admin helpers into an /includes folder. #72 (@kimcoleman)</li>\n<li>BUG FIX: Fixed redirection from the membership card in certain cases to make it more reliable and consistent. #71 (@kimcoleman)</li>\n<li>BUG FIX: Fixed an issue where the QR code shown would not be resized. #65 (@dwanjuki)</li>\n<li>DEPRECATION: Removed support for legacy filters pmpro_membership_card-extra_classes and pmpro_membership_card_after_card. #72 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:82:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-membership-card.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:15:\"Membership Card\";}i:74;a:16:{s:4:\"Name\";s:53:\"Paid Memberships Pro - Membership Manager Role Add On\";s:5:\"Title\";s:53:\"Paid Memberships Pro - Membership Manager Role Add On\";s:9:\"PluginURI\";s:73:\"https://www.paidmembershipspro.com/add-ons/pmpro-membership-manager-role/\";s:4:\"Slug\";s:29:\"pmpro-membership-manager-role\";s:6:\"plugin\";s:63:\"pmpro-membership-manager-role/pmpro-membership-manager-role.php\";s:7:\"Version\";s:5:\"0.3.3\";s:11:\"Description\";s:86:\"Adds a Membership Manager role to WordPress with access to PMPro settings and reports.\";s:12:\"Installation\";s:237:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-membership-manager-role</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:311:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-gift-levels/issues\">https://github.com/strangerstudios/pmpro-gift-levels/issues</a></p>\";s:9:\"Changelog\";s:218:\"<h4>Changelog</h4><p>0.3.3 - 2024-02-29</p><ul>\n<li>ENHANCEMENT: Improved capability support for Paid Memberships Pro 3.0+</li>\n<li>ENHANCEMENT: Added localization to the plugin to make strings translatable.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:91:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-membership-manager-role.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:23:\"Membership Manager Role\";}i:75;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Membership Maps Add On\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Membership Maps Add On\";s:9:\"PluginURI\";s:59:\"https://www.paidmembershipspro.com/add-ons/membership-maps/\";s:4:\"Slug\";s:21:\"pmpro-membership-maps\";s:6:\"plugin\";s:47:\"pmpro-membership-maps/pmpro-membership-maps.php\";s:7:\"Version\";s:3:\"0.9\";s:11:\"Description\";s:58:\"Display a map of members or for a single member\'s profile.\";s:12:\"Installation\";s:899:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-membership-maps</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>Settings</p><ol>\n<li>This plugin requires Paid Memberships Pro to be installed and activated.</li>\n<li>By default, the map will geocode the memberâ€™s \"Billing Address\". Navigate to Memberships &gt; Settings &gt; Payment Gateway &amp; SSL in the WordPress admin. Confirm the \"Show Billing Address Fields\" setting is set to \"Yes\".</li>\n<li>Next, enter your Google Maps API Key on the Memberships &gt; Settings &gt; Advanced Settings page in the WordPress admin. <a href=\"https://www.paidmembershipspro.com/add-ons/membership-maps/#google-maps-api-key\">Click here for help obtaining up your Google Maps API Key</a>.</li>\n</ol>\";s:3:\"FAQ\";s:567:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-membership-maps/issues\">https://github.com/strangerstudios/pmpro-membership-maps/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:518:\"<h4>Changelog</h4><p>0.9 - 2025-05-22</p><ul>\n<li>ENHANCEMENT: General improvements to loading the JavaScript files and load the files asynchronously. (@andrewlimaza, @JarrydLong)</li>\n<li>ENHANCEMENT: Improved search support for the Membership Directory and Profiles Add On. The map will now show the marker results from the search results. (@JarrydLong)</li>\n<li>BUG FIX: Fixed an issue where the Membership Map Address fields would not show for logged-out users during the checkout process. (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:82:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-membership-maps.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:15:\"Membership Maps\";}i:76;a:16:{s:4:\"Name\";s:54:\"Paid Memberships Pro - Mobile Reports Dashboard Add On\";s:5:\"Title\";s:54:\"Paid Memberships Pro - Mobile Reports Dashboard Add On\";s:9:\"PluginURI\";s:72:\"https://www.paidmembershipspro.com/add-ons/responsive-reports-dashboard/\";s:4:\"Slug\";s:23:\"pmpro-reports-dashboard\";s:6:\"plugin\";s:51:\"pmpro-reports-dashboard/pmpro-reports-dashboard.php\";s:7:\"Version\";s:5:\"1.0.1\";s:11:\"Description\";s:89:\"Streamlined membership site reports dashboard designed for mobile and responsive screens.\";s:12:\"Installation\";s:443:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-reports-dashboard</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to www.YOURDOMAIN.com/pmpro-reports-dashboard/ to load the dashboard.</li>\n<li>Optionally use your mobile device\'s \"Add to Home Screen\" feature to add the app to your device for instant access.</li>\n</ol>\";s:3:\"FAQ\";s:323:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-reports-dashboard/issues\">https://github.com/strangerstudios/pmpro-reports-dashboard/issues</a></p>\";s:9:\"Changelog\";s:259:\"<h4>Changelog</h4><p>1.0.1 - 2026-05-04</p><ul>\n<li>BUG FIX: Fixed duplicate \"View Mobile Reports\" button appearing on the PMPro Reports admin page in PMPro v3.0+ where two <code>h1</code> tags caused the button to be added twice. #14 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:84:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-reports-dashboard.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:24:\"Mobile Reports Dashboard\";}i:77;a:16:{s:4:\"Name\";s:52:\"Paid Memberships Pro - Multiple Memberships per User\";s:5:\"Title\";s:52:\"Paid Memberships Pro - Multiple Memberships per User\";s:9:\"PluginURI\";s:70:\"http://www.paidmembershipspro.com/pmpro-multiple-memberships-per-user/\";s:4:\"Slug\";s:35:\"pmpro-multiple-memberships-per-user\";s:6:\"plugin\";s:75:\"pmpro-multiple-memberships-per-user/pmpro-multiple-memberships-per-user.php\";s:7:\"Version\";s:5:\"0.8.4\";s:11:\"Description\";s:91:\"Update PMPro to allow users to checkout for and hold multiple memberships at the same time.\";s:12:\"Installation\";s:227:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-multiple-memberships-per-user</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:279:\"<h4>Changelog</h4><p>0.8.4 - 2023-06-14</p><ul>\n<li>BUG FIX: Added additional check to prevent JavaScript from loading on pages other than the checkout page.</li>\n<li>REFACTOR: Added version to Checkout page template to avoid outdated template warnings in PMPro v2.11+</li>\n</ul>\";s:6:\"Author\";s:37:\"Square Lines LLC and Stranger Studios\";s:9:\"AuthorURI\";s:27:\"http://www.square-lines.com\";s:8:\"Download\";s:97:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-multiple-memberships-per-user.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:29:\"Multiple Memberships per User\";}i:78;a:16:{s:4:\"Name\";s:68:\"Paid Memberships Pro - Multiple Memberships per User (Legacy Plugin)\";s:5:\"Title\";s:68:\"Paid Memberships Pro - Multiple Memberships per User (Legacy Plugin)\";s:9:\"PluginURI\";s:60:\"http://www.paidmembershipspro.com/add-ons/pmpro-mmpu-legacy/\";s:4:\"Slug\";s:17:\"pmpro-mmpu-legacy\";s:6:\"plugin\";s:39:\"pmpro-mmpu-legacy/pmpro-mmpu-legacy.php\";s:7:\"Version\";s:3:\"0.1\";s:11:\"Description\";s:60:\"Preserve some aspects of the old MMPU add on for PMPro 3.0+.\";s:12:\"Installation\";s:305:\"<p>Installation</p><ol>\n<li>Make sure you have Paid Memberships Pro v3.0+ installed and activated.</li>\n<li>Upload the <code>pmpro-mmpu-legacy</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:505:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-mmpu-legacy/issues\">https://github.com/strangerstudios/pmpro-mmpu-legacy/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:77:\"<h4>Changelog</h4><p>0.1 - 2024-03-21</p><ul>\n<li>Initial version.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-mmpu-legacy.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:45:\"Multiple Memberships per User (Legacy Plugin)\";}i:79;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Multisite Membership Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Multisite Membership Add On\";s:9:\"PluginURI\";s:68:\"https://www.paidmembershipspro.com/add-ons/pmpro-network-membership/\";s:4:\"Slug\";s:21:\"pmpro-network-subsite\";s:6:\"plugin\";s:47:\"pmpro-network-subsite/pmpro-network-subsite.php\";s:7:\"Version\";s:5:\"0.6.1\";s:11:\"Description\";s:133:\"Centralize membership checkout, login, and admin on the main network site and restrict access to content across all of your subsites.\";s:12:\"Installation\";s:1368:\"<p>Installation</p><ol>\n<li>Install Paid Memberships Pro via Network Admin &gt; Plugins &gt; Add New. Do not \"Network Activate\" the plugin.</li>\n<li>On your main network site, activate and configure Paid Memberships Pro by following the Initial Plugin Setup guide.</li>\n<li>Upload the \'pmpro-network-subsite\' directory to the \'wp-content/plugins/\' directory of your WordPress Multisite environment.</li>\n<li>For each site in your network that has member content, navigate to the site\'s Dashboard &gt; Plugins. Activate Paid Memberships Pro AND the Multisite Membership Add On.</li>\n<li>On the child sites in the network, navigate to the Memberships settings page and assign the appropriate site as the Main Network Site.</li>\n<li>DO NOT activate the \'pmpro-network-subsite\' plugin on the â€œMainâ€ site (i.e. where people checkout) of your network.</li>\n<li>We also recommend defining the PMPRO_MULTISITE_REWRITE_URLS in your wp-config.php file. For example: define(\'PMPRO_MULTISITE_REWRITE_URLS\', true );</li>\n</ol>\n<p>You will now be able to create members-only content on subsites in the network. The membership levels of your main site are mirrored in each subsite.</p>\n<p>Read full documentation at <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-network-membership/\">https://www.paidmembershipspro.com/add-ons/pmpro-network-membership/</a></p>\";s:3:\"FAQ\";s:511:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-network-subsite/issues\">https://github.com/strangerstudios/pmpro-network-subsite/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:1053:\"<h4>Changelog</h4><p>0.6.1 - 2026-06-30</p><ul>\n<li>BUG FIX: Fixed the footer message appearing inside the content area on the plugin\'s settings page due to an unclosed form tag. #44 (@kimwhite)</li>\n</ul><p>0.6 - 2026-05-07</p><ul>\n<li>FEATURE: Added an option on the subsite Settings screen to inherit advanced settings from the main network site (default), or to use custom settings per subsite. #42 (@kimcoleman)</li>\n<li>ENHANCEMENT: Member avatars now load from the main network site\'s uploads directory via the new <code>pmpro_avatar_basedir</code> and <code>pmpro_avatar_baseurl</code> filters in PMPro core. #42 (@kimcoleman)</li>\n<li>BUG FIX: Removed a stray <code>var_dump()</code> and fixed a malformed <code>&lt;div id==\"message\"&gt;</code> in the subsite settings page. #42 (@kimcoleman)</li>\n</ul><p>0.5.3 - 2024-10-07</p><ul>\n<li>ENHANCEMENT: Improved settings UI for compatibility with PMPro admin screens. #38 (@MaximilianoRicoTabo, @kimcoleman)</li>\n<li>BUG FIX: Fixed errors when PMPro core not active. #35 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:82:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-network-subsite.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Multisite Membership\";}i:80;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Nav Menus Add On\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Nav Menus Add On\";s:9:\"PluginURI\";s:59:\"https://www.paidmembershipspro.com/add-ons/pmpro-nav-menus/\";s:4:\"Slug\";s:15:\"pmpro-nav-menus\";s:6:\"plugin\";s:35:\"pmpro-nav-menus/pmpro-nav-menus.php\";s:7:\"Version\";s:5:\"0.4.1\";s:11:\"Description\";s:100:\"Creates member navigation menus and swaps your theme\'s navigation based on a user\'s Membership Level\";s:12:\"Installation\";s:422:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-nav-menus</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Optionally create level-specific navigation menus on the <code>Edit Membership Level</code> admin.</li>\n<li>Create new navigation menu(s) for your members and assign them to the appropriate Theme Location.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:214:\"<h4>Changelog</h4><p>0.4.1 - 2026-04-23</p><ul>\n<li>ENHANCEMENT: Added a link to documentation and updated formatting of the Navigation Menu section on the Edit Membership Level screen. #29 (@kimcoleman)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:76:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-nav-menus.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Nav Menus\";}i:81;a:16:{s:4:\"Name\";s:20:\"Paid Memberships Pro\";s:5:\"Title\";s:20:\"Paid Memberships Pro\";s:9:\"PluginURI\";s:34:\"https://www.paidmembershipspro.com\";s:4:\"Slug\";s:20:\"paid-memberships-pro\";s:6:\"plugin\";s:45:\"paid-memberships-pro/paid-memberships-pro.php\";s:7:\"Version\";s:5:\"3.8.5\";s:11:\"Description\";s:51:\"The Trusted Membership Platform That Grows with You\";s:12:\"Installation\";s:1196:\"<p>Installation</p><p>Download, Install and Activate!</p><p>Visit <a href=\"https://www.paidmembershipspro.com/documentation/download/\">https://www.paidmembershipspro.com/documentation/download/</a> for the full plugin download and instructions on how to install Paid Memberships Pro in your WordPress site.</p><p>Use the Setup Wizard to Complete Initial Setup</p><p>After activation, you will be taken through a brief setup wizard to configure the plugin.</p>\n<p>Refer to our <a href=\"https://www.paidmembershipspro.com/documentation/initial-plugin-setup/\">Initial Setup Tutorial</a> guide for additional help getting started.</p><p>More Installation and Setup Documentation</p><ul>\n<li><a href=\"https://www.paidmembershipspro.com/documentation/initial-plugin-setup/tutorial-video/\">Installation Video</a></li>\n<li><a href=\"https://www.paidmembershipspro.com/documentation/initial-plugin-setup/\">Installation Docs</a></li>\n<li><a href=\"https://www.paidmembershipspro.com/documentation/membership-levels/\">Membership Levels</a></li>\n<li><a href=\"https://www.paidmembershipspro.com/gateway/\">Payment Gateways</a></li>\n<li><a href=\"https://www.paidmembershipspro.com/add-ons/\">Add Ons</a></li>\n</ul>\";s:3:\"FAQ\";s:4058:\"<p>Frequently Asked Questions</p><p>Should I use WordPress or a hosted SaaS platform for memberships?</p><p>Both WordPress and SaaS (Software as a Service) platforms, like Kajabi or Podia, have their strengths, but they represent two very different approaches. Read our guide to determine which is best for you: <a href=\"https://www.paidmembershipspro.com/wordpress-vs-saas/\">WordPress vs SaaS For Membership Sites: Real Costs, Pros &amp; Cons, and Who Actually Wins</a>.</p><p>What is the best WordPress membership plugin? = \nWe published a guide on the <a href=\"https://www.paidmembershipspro.com/best-wordpress-membership-plugins-compared/\">4 best WordPress membership plugins</a>. You can read this guide to help you decide if Paid Memberships Pro is the right solution for you.</p>\n<p>= Do I need to know any coding to use this plugin?</p><p>No, Paid Memberships Pro does not require any coding knowledge. The plugin is designed to meet all levels of WordPress experience. At the same time, our plugin is very developer-friendly and extendible.</p><p>Does the Paid Memberships Pro work with any WordPress theme?</p><p>Yes. PMPro will work with any properly coded theme. However, some themes may cause conflicts with the plugin. If you find a styling issue with your theme please create a post in the community forum.</p><p>Does the plugin work with caching plugins?</p><p>Absolutely. We have a <a href=\"https://www.paidmembershipspro.com/documentation/advanced/caching/\">complete guide on using a caching plugin</a> or your host\'s caching methods with Paid Memberships Pro on our website if you want to explore this topic more.</p><p>Does PMPro restrict access to wp-login.php when the plugin is active?</p><p>PMPro does not restrict access to the wp-login.php page when active. This allows your administrator users to leverage advanced security plugins, like Two-Factor and more, so that you can keep your membership site secure. We do include a frontend login page for your members to use for logging in and resetting their password.</p><p>Is Paid Memberships Pro Multisite or Network Compatible?</p><p>\"Supporting multisite\" means different things to different people. <a href=\"https://www.paidmembershipspro.com/membership-website-wordpress-multisite/\">This guide covers the three primary ways</a> you can use Paid Memberships Pro in a network.</p>\n<p>Out of the box PMPro will basically act as a stand alone plugin for each site. Each site has its own list of membership levels, members, payment settings, etc.</p>\n<p>Our <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-network-multisite-membership/\">Member Network Sites Add On</a> allows members to choose a site name and title at checkout and will set up a network site at checkout.</p>\n<p>Our <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-network-membership/\">Multisite Membership Add On</a> allows you to manage memberships at the \'Main\' Network site and provide or restrict access on other Network Subsites.</p>\n<p>If you would like more help using PMPro on a network install, <a href=\"https://www.paidmembershipspro.com/contact/\">reach our via our contact page</a>.</p><p>I need help installing, configuring, or customizing Paid Memberships Pro.</p><p>Please visit <a href=\"https://www.paidmembershipspro.com/support/\">our support site</a> for more documentation and ways to get support.</p><p>I found a bug in Paid Memberships Pro.</p><p>Please reach out using our <a href=\"https://www.paidmembershipspro.com/contact/\">contact form</a> and we\'ll fix it right away. Thanks for helping.</p><p>Does PMPro Support X?</p><p>Not sure? You can find out by doing a bit a research.</p>\n<ol>\n<li><a href=\"https://www.paidmembershipspro.com/documentation/compatibility/\">Check our compatibility page</a>.</li>\n<li><a href=\"https://www.paidmembershipspro.com/add-ons/\">Check our Add Ons</a>.</li>\n<li><a href=\"https://www.paidmembershipspro.com/\">Do a search on our site</a>.</li>\n<li><a href=\"https://www.paidmembershipspro.com/contact/\">Ask using our contact form</a></li>\n</ol>\";s:9:\"Changelog\";s:3906:\"<h4>Changelog</h4><p>3.8.5 - 2026-08-24</p><ul>\n<li>SECURITY: Fixed an issue where the payment amount was not re-verified after Strong Customer Authentication (3D Secure) in the Stripe on-site checkout. #3767 (@dparker1005)</li>\n<li>SECURITY: Fixed an access check bypass in the <code>getfile</code> service that could allow protected files to be served through <code>admin-ajax.php</code> without a membership access check. #3762 (@dparker1005)</li>\n<li>SECURITY: Added missing capability and nonce checks to several admin AJAX and service handlers. #3758 (@flintfromthebasement)</li>\n<li>ENHANCEMENT: Removed the notices on the Stripe payment settings recommending the deprecated Add PayPal Express Add On. #3751 (@flintfromthebasement)</li>\n<li>BUG FIX: Guarded the <code>pmpro_setMessage()</code> calls in <code>PMPro_AddOns</code> so that activating Paid Memberships Pro while the Update Manager Add On is active no longer causes a fatal error. #3763 (@dparker1005)</li>\n</ul><p>3.8.4 - 2026-08-06</p><ul>\n<li>ENHANCEMENT: Added new <code>--pmpro--btn--border-radius</code>, <code>--pmpro--btn--top-bottom-padding</code>, and <code>--pmpro--btn--left-right-padding</code> CSS variables so that button styles can be customized separately from other elements that share the base variables. #3747 (@RachelRVasquez)</li>\n<li>BUG FIX: Fixed an issue where Stripe Checkout orders paid with delayed notification payment methods such as SEPA Direct Debit could be completed without their subscription and payment transaction IDs, which prevented membership cancellations from being sent to Stripe. An upgrade script now recovers the missing IDs for previously affected orders. #3745 (@dparker1005)</li>\n<li>BUG FIX: Fixed an issue where a user field could be shown at checkout even though its field group was hidden from checkout if the field overrode the group\'s profile visibility setting. #3744 (@dparker1005)</li>\n<li>BUG FIX: Fixed an issue where duplicate recurring scheduled tasks, such as those inherited from a cloned or migrated database, would run simultaneously indefinitely. Duplicate chains are now cancelled automatically, keeping the earliest scheduled task. #3746 (@dalemugford)</li>\n</ul><p>3.8.3 - 2026-07-30</p><ul>\n<li>ENHANCEMENT: Site Health now detects the PMPro SMTP Add On as the site\'s email sending service when a connector is configured. #3729 (@dparker1005)</li>\n<li>ENHANCEMENT: Added translator comments to localized strings containing placeholders so translators have context for each variable. #3730 (@jahidhasan018)</li>\n<li>ENHANCEMENT: The discount code lookup in <code>PMPro_Discount_Code::save()</code> now uses <code>$wpdb-&gt;prepare()</code>. #3734 (@andrewlimaza)</li>\n<li>BUG FIX: Multi-value user fields (multiselect, select2, and grouped checkboxes) now display correctly when their values were imported from a CSV file as a comma-separated string. #3742 (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed a fatal error that could occur when returning from an offsite gateway if the checkout data was missing from the order meta. #3741 (@dparker1005)</li>\n<li>BUG FIX: Fixed PMPro core and Add Ons never auto-updating in the background because the update hooks were only registered on <code>admin_init</code>, which does not fire during WP-Cron where automatic updates run. #3738 (@dalemugford)</li>\n<li>BUG FIX: Set <code>new_version</code> on <code>no_update</code> entries so up-to-date Add Ons no longer trigger an undefined property warning in WP-CLI and other consumers of the plugin update transient. #3738 (@dalemugford)</li>\n<li>BUG FIX: The bulk user delete confirmation screen now counts membership history for every selected user instead of only the first. #3733 (@jahidhasan018)</li>\n<li>BUG FIX: The level group selection message is no longer shown on the Membership Levels page for groups that contain only one level. #3731 (@jahidhasan018)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:77:\"http://license.paidmembershipspro.com/downloads/free/paid-memberships-pro.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:20:\"Paid Memberships Pro\";}i:82;a:16:{s:4:\"Name\";s:42:\"Paid Memberships Pro - Pay by Check Add On\";s:5:\"Title\";s:42:\"Paid Memberships Pro - Pay by Check Add On\";s:9:\"PluginURI\";s:69:\"https://www.paidmembershipspro.com/add-ons/pmpro-pay-by-check-add-on/\";s:4:\"Slug\";s:18:\"pmpro-pay-by-check\";s:6:\"plugin\";s:41:\"pmpro-pay-by-check/pmpro-pay-by-check.php\";s:7:\"Version\";s:5:\"1.1.8\";s:11:\"Description\";s:106:\"A collection of customizations useful when allowing users to pay by check for Paid Memberships Pro levels.\";s:12:\"Installation\";s:843:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-pay-by-check</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Change your Payment Settings to the \"Pay by Check\" gateway and make sure to set the \"Instructions\" with instructions for how to pay by check. Save.</li>\n<li>Change the Payment Settings back to use your gateway of choice. Behind the scenes the Pay by Check settings are still stored.</li>\n<li>Edit your membership levels and set the \"Pay by Check Settings\" for each level.</li>\n</ol>\n<p>If you would like to change the wording from \"Pay by Check\" to something else, you can use this custom code:\n<a href=\"https://gist.github.com/strangerstudios/68bb75bf3b83530390d4\">https://gist.github.com/strangerstudios/68bb75bf3b83530390d4</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1326:\"<h4>Changelog</h4><p>1.1.8 - 2026-06-30</p><ul>\n<li>BUG FIX: The membership level\'s confirmation message is no longer shown on the checkout confirmation page for pending Pay by Check orders; it now displays only once the order status is <code>success</code>. This aligns with the same change in PMPro core (strangerstudios/paid-memberships-pro#3682). #153 (@kimcoleman)</li>\n</ul><p>1.1.7 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Updated default email templates to use the new liquid syntax (<code>{{ var }}</code>) for Paid Memberships Pro 3.7+ while preserving the legacy <code>!!var!!</code> syntax on older versions. #152 (@dparker1005)</li>\n<li>ENHANCEMENT: Updated the admin \"check pending\" email body to use <code>{{ order_id }}</code> / <code>{{ order_date }}</code> / <code>{{ order_total }}</code> so it matches the documented variable list and the member-facing templates. #152 (@dparker1005)</li>\n</ul><p>1.1.6 - 2026-03-27</p><ul>\n<li>ENHANCEMENT: Cleaned up settings formatting in the admin. #150 (@strangerstudios)</li>\n<li>BUG FIX: Fixed checkout page when toggling between the new PayPal (REST API) gateway and Pay by Check. #151 (@dparker1005)</li>\n<li>BUG FIX: Updated references to the PayPal Website Payments Pro gateway slug from <code>paypal</code> to <code>paypalwpp</code>. #151 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-pay-by-check.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:12:\"Pay by Check\";}i:83;a:16:{s:4:\"Name\";s:38:\"Paid Memberships Pro - PayFast Gateway\";s:5:\"Title\";s:38:\"Paid Memberships Pro - PayFast Gateway\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/payfast-payment-gateway/\";s:4:\"Slug\";s:13:\"pmpro-payfast\";s:6:\"plugin\";s:31:\"pmpro-payfast/pmpro-payfast.php\";s:7:\"Version\";s:5:\"1.7.2\";s:11:\"Description\";s:58:\"Adds PayFast as a gateway option for Paid Memberships Pro.\";s:12:\"Installation\";s:1007:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-payfast</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Go to Memberships -&gt; Payment Settings in your WordPress dashboard to complete the Payfast settings.</li>\n</ol><p>Setup</p><ol>\n<li>Register and validate your account with Payfast: <a href=\"https://registration.payfast.io/\">https://registration.payfast.io/</a>.</li>\n<li>Log in to your Payfast account and select \'Settings\' to retrieve your merchant details.</li>\n<li>Log in to your WordPress dashboard and navigate to Memberships &gt; Payment Settings.</li>\n<li>Set your \"Payment Gateway\" to \"Payfast\". Fill out your merchant details and Security Passphrase (required in order to accept recurring payments).</li>\n<li>Set your currency to \"South African Rand\".</li>\n<li>Save your settings.</li>\n</ol>\";s:3:\"FAQ\";s:1038:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-payfast/issues\">https://github.com/strangerstudios/pmpro-payfast/issues</a></p>\n<p>For immediate help, also post to our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>I need to test Payfast in sandbox mode.</p><p>To test Payfast payments without being billed in sandbox mode requires a sandbox account from PayFast. For more information in creating a sandbox account - <a href=\"https://developers.payfast.co.za/documentation/#the-sandbox\">https://developers.payfast.co.za/documentation/#the-sandbox</a></p>\";s:9:\"Changelog\";s:143:\"<h4>Changelog</h4><p>1.7.2 - 2025-07-10</p><ul>\n<li>ENHANCEMENT: Added improved support for Paid Memberships Pro V3.5+ (@JarrydLong)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:70:\"http://license.paidmembershipspro.com/downloads/free/pmpro-payfast.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:15:\"PayFast Gateway\";}i:84;a:16:{s:4:\"Name\";s:54:\"Paid Memberships Pro - Payflow Recurring Orders Add On\";s:5:\"Title\";s:54:\"Paid Memberships Pro - Payflow Recurring Orders Add On\";s:9:\"PluginURI\";s:74:\"https://www.paidmembershipspro.com/add-ons/payflow-recurring-orders-addon/\";s:4:\"Slug\";s:30:\"pmpro-payflow-recurring-orders\";s:6:\"plugin\";s:65:\"pmpro-payflow-recurring-orders/pmpro-payflow-recurring-orders.php\";s:7:\"Version\";s:5:\"0.3.2\";s:11:\"Description\";s:72:\"Check daily for new recurring orders in Payflow and add as PMPro orders.\";s:12:\"Installation\";s:708:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-payflow-recurring-orders/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Thatâ€™s it. No settings.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/payflow-recurring-orders-addon/\">https://www.paidmembershipspro.com/add-ons/payflow-recurring-orders-addon/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:308:\"<h4>Changelog</h4><p>0.3.2 - 2024-10-24</p><ul>\n<li>BUG FIX: Fixed an issue where subscriptions table data would not be updated when using PMPro v3.0+. #7 (@dparker1005)</li>\n<li>BUG FIX: Fixed an issue where the order amount for recurring orders would show as $0 in PMPro v3.2+. #7 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:33:\"htts://www.paidmembershipspro.com\";s:8:\"Download\";s:88:\"https://license.paidmembershipspro.com/downloads/free/pmpro-payflow-recurring-orders.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:24:\"Payflow Recurring Orders\";}i:85;a:16:{s:4:\"Name\";s:43:\"Paid Memberships Pro - Payment Plans Add On\";s:5:\"Title\";s:43:\"Paid Memberships Pro - Payment Plans Add On\";s:9:\"PluginURI\";s:63:\"https://www.paidmembershipspro.com/add-ons/pmpro-payment-plans/\";s:4:\"Slug\";s:19:\"pmpro-payment-plans\";s:6:\"plugin\";s:43:\"pmpro-payment-plans/pmpro-payment-plans.php\";s:7:\"Version\";s:3:\"0.6\";s:11:\"Description\";s:84:\"Integrates with Paid Memberships Pro to provide payment plans for membership levels.\";s:12:\"Installation\";s:1402:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-approvals/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol><p>How to Use</p><ol>\n<li>Create a membership level and set the pricing on the level to the default or most popular payment you offer. For example, set the main level up as a fixed price per month.</li>\n<li>Then, locate the â€œPayment Plansâ€ section and click the â€œAdd Payment Planâ€ button.</li>\n<li>Expand the individual payment plan to adjust the name, pricing details, and any additional settings related to expiration or trials.</li>\n<li>Add additional payment plans if youâ€™d like to offer more than one. The default level pricing will be shown first in the list with any additional active payment plans shown below.</li>\n<li>Save the membership level and browse to the checkout page for that level to see your plans in action.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-payment-plans/\">https://www.paidmembershipspro.com/add-ons/pmpro-payment-plans/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:782:\"<h4>Changelog</h4><p>0.6 - 2026-05-04</p><ul>\n<li>ENHANCEMENT: Added a Payment Plan column to the Orders and Subscriptions list tables and the Edit Member panels, plus a Payment Plan section on the single subscription view. The plan is now stored on the subscription record (with self-healing for legacy orders) so reports can group recurring orders by plan. #89 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added a \"Learn more\" link to the Payment Plans Add On documentation in the level edit settings. #86 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added \"Docs\" and \"Support\" links to the plugin row meta on the Plugins screen. #83 (@ipokkel)</li>\n<li>BUG FIX: Fixed a layout jump and stale expiration text when switching payment plans on the checkout page. #88 (@flintfromthebasement)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:80:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-payment-plans.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:13:\"Payment Plans\";}i:86;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - PayPal Gateway\";s:5:\"Title\";s:37:\"Paid Memberships Pro - PayPal Gateway\";s:9:\"PluginURI\";s:56:\"https://www.paidmembershipspro.com/add-ons/pmpro-paypal/\";s:4:\"Slug\";s:12:\"pmpro-paypal\";s:6:\"plugin\";s:29:\"pmpro-paypal/pmpro-paypal.php\";s:7:\"Version\";s:5:\"1.1.2\";s:11:\"Description\";s:98:\"Modern PayPal integration using Orders V2 and Subscriptions API v1 with offsite redirect checkout.\";s:12:\"Installation\";s:2917:\"<p>Installation</p><ol>\n<li>Get Your PayPal API Credentials</li>\n</ol><p>You need a <strong>Client ID</strong> and <strong>Client Secret</strong> from the PayPal Developer Dashboard.</p>\n<p><strong>For Sandbox (testing):</strong></p>\n<ol>\n<li>Go to <a href=\"https://developer.paypal.com/\">developer.paypal.com</a> and log in with your PayPal account.</li>\n<li>Navigate to <strong>Apps &amp; Credentials</strong> (under the Dashboard menu).</li>\n<li>Make sure the toggle at the top is set to <strong>Sandbox</strong>.</li>\n<li>Click <strong>Create App</strong> (or use the \"Default Application\" if one exists).</li>\n<li>Give it a name like \"PMPro\" and click <strong>Create App</strong>.</li>\n<li>On the app detail page, copy the <strong>Client ID</strong> (shown in full) and the <strong>Secret</strong> (click \"Show\" to reveal it).</li>\n</ol>\n<p><strong>For Live (production):</strong></p>\n<ol>\n<li>Same steps as above, but toggle to <strong>Live</strong> at the top of the Apps &amp; Credentials page.</li>\n<li>You may need to complete PayPal\'s account verification before live credentials are available.</li>\n</ol><ol start=\"2\">\n<li>Configure the Plugin</li>\n</ol><ol>\n<li>Install and activate this plugin.</li>\n<li>Go to <strong>PMPro &gt; Settings &gt; Payment Gateway</strong>.</li>\n<li>Select <strong>PayPal</strong> from the gateway dropdown.</li>\n<li>Set the <strong>Payment Gateway Environment</strong> to Sandbox or Live.</li>\n<li>Enter your <strong>Client ID</strong> and <strong>Client Secret</strong> for both the Live and Sandbox environments.</li>\n<li>Click <strong>Save Settings</strong>.</li>\n</ol><ol start=\"3\">\n<li>Webhook (Automatic)</li>\n</ol><p>The webhook is registered automatically via the PayPal API when you save valid credentials. You do not need to manually configure a webhook URL in the PayPal dashboard.</p>\n<p>After saving, the settings page will display the Webhook ID confirming it was registered. The webhook URL is your site\'s REST API endpoint at:</p>\n<p><code>https://yoursite.com/wp-json/pmpro-paypal/v1/webhook</code></p>\n<p>PayPal will send notifications to this URL for subscription payments, cancellations, refunds, and other events.</p>\n<p><strong>Troubleshooting webhooks:</strong></p>\n<ul>\n<li>Your site must be served over <strong>HTTPS</strong> — PayPal will not deliver webhooks to HTTP URLs.</li>\n<li>If you\'re testing on localhost, PayPal cannot reach your webhook URL. Use a tunnel service like ngrok to expose your local site, or test webhook handling separately.</li>\n<li>If the Webhook ID is not showing after saving, check that your Client ID and Secret are correct and that your site is accessible over HTTPS.</li>\n<li>You can verify the webhook exists by going to your app in the <a href=\"https://developer.paypal.com/\">PayPal Developer Dashboard</a> &gt; <strong>Apps &amp; Credentials</strong> &gt; your app &gt; <strong>Webhooks</strong> tab.</li>\n</ul>\";s:3:\"FAQ\";s:1531:\"<p>Frequently Asked Questions</p><p>What happens to existing PayPal Express subscribers?</p><p>They continue working. The old PayPal Express gateway (slug: <code>paypalexpress</code>) runs side-by-side with this new gateway. Existing subscribers keep their current gateway and IPN handler. Only new sign-ups use the new <code>paypal</code> gateway.</p><p>Can I test in sandbox before going live?</p><p>Yes. Set the Payment Gateway Environment to \"Sandbox\" in PMPro settings and use your sandbox Client ID and Secret. PayPal provides sandbox buyer accounts at developer.paypal.com &gt; Sandbox &gt; Accounts that you can use to complete test checkouts.</p><p>Do I need to set up IPN?</p><p>No. This plugin uses PayPal Webhooks (the modern replacement for IPN), and they are registered automatically. The old IPN handler in PMPro core continues to work for legacy PayPal Express and PayPal Standard subscriptions.</p><p>What PayPal APIs does this plugin use?</p><ul>\n<li><strong>Orders V2</strong> (<code>/v2/checkout/orders</code>) for one-time payments</li>\n<li><strong>Subscriptions API v1</strong> (<code>/v1/billing/subscriptions</code>) for recurring</li>\n<li><strong>Catalog Products</strong> (<code>/v1/catalogs/products</code>) and <strong>Billing Plans</strong> (<code>/v1/billing/plans</code>) for subscription plan management</li>\n<li><strong>Webhooks</strong> (<code>/v1/notifications/webhooks</code>) for event notifications</li>\n<li><strong>OAuth2</strong> (<code>/v1/oauth2/token</code>) for authentication</li>\n</ul>\";s:9:\"Changelog\";s:1796:\"<h4>Changelog</h4><p>1.1.2 - 2026-08-11</p><ul>\n<li>ENHANCEMENT: PayPal API error messages now include the offending field path and PayPal\'s debug ID, so errors like \"The value of a field is invalid.\" identify the invalid field and can be traced with PayPal support. #17 (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed the subscription <code>start_time</code> sent to PayPal being labeled with the site\'s timezone instead of UTC, which could shift the first renewal to the wrong day depending on the checkout time and the site timezone. #16 (@flintfromthebasement)</li>\n<li>BUG FIX: Fixed membership levels set to \"check only\" in the Pay by Check Add On still displaying the payment method picker when PayPal was configured as a secondary gateway. #13 (@davidmutero)</li>\n</ul><p>1.1.1 - 2026-05-07</p><ul>\n<li>BUG FIX: Fixed a <code>DECIMAL_PRECISION</code> error from the PayPal billing API when checking out a recurring level whose initial payment is 0 on a zero-decimal currency (JPY, KRW, VND, UAH, ALL). The setup fee is now formatted via <code>pmpro_round_price_as_string()</code> so it matches the site currency. #12 (@dparker1005)</li>\n</ul><p>1.1 - 2026-04-27</p><ul>\n<li>FEATURE: Added support for offering PayPal as a secondary payment gateway alongside another primary gateway at checkout. #10 (@dparker1005)</li>\n<li>ENHANCEMENT: Added a setting to manually edit the PayPal Webhook ID for both the Sandbox and Live environments. #9 (@andrewlimaza)</li>\n<li>ENHANCEMENT: The PayPal webhook REST endpoint now accepts GET requests so site owners can confirm the URL is reachable from a browser. #11 (@dparker1005)</li>\n<li>BUG FIX: Fixed PayPal webhook signature verification by sending the original raw webhook body to PayPal instead of a re-encoded version. #8 (@ideadude)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:69:\"http://license.paidmembershipspro.com/downloads/free/pmpro-paypal.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"PayPal Gateway\";}i:87;a:16:{s:4:\"Name\";s:41:\"Paystack Gateway for Paid Memberships Pro\";s:5:\"Title\";s:41:\"Paystack Gateway for Paid Memberships Pro\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/paystack-gateway/\";s:4:\"Slug\";s:37:\"paystack-gateway-paid-memberships-pro\";s:6:\"plugin\";s:79:\"paystack-gateway-paid-memberships-pro/paystack-gateway-paid-memberships-pro.php\";s:7:\"Version\";s:5:\"1.9.1\";s:11:\"Description\";s:64:\"Plugin to add Paystack payment gateway into Paid Memberships Pro\";s:12:\"Installation\";s:774:\"<p>Installation</p><p>Minimum Requirements</p><ul>\n<li>Confirm that your server can conclude a TLSv1.2 connection to Paystack\'s servers. More information about this requirement can be gleaned here: <a href=\"https://developers.paystack.co/blog/tls-v12-requirement\">TLS v1.2 requirement</a>.</li>\n<li>Installed and activated [Paid Membership Pro Plugin] (<a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a>)</li>\n</ul><p>Manual installation</p><p>The manual installation method involves downloading our payment plugin and uploading it to your webserver via your favourite FTP application. The WordPress codex contains <a href=\"https://codex.wordpress.org/Managing_Plugins#Manual_Plugin_Installation\">instructions on how to do this here</a>.</p>\";s:3:\"FAQ\";s:621:\"<p>Frequently Asked Questions</p><p>Where can I find help and documentation to understand Paystack?</p><p>You can find help and information on Paystack on our <a href=\"https://paystack.com/help\">Help Desk</a></p><p>Where can I get support or talk to other users?</p><p>If you get stuck, you can ask for help in the <a href=\"https://www.paidmembershipspro.com/support\">Paid Memberships Pro Support</a>.</p><p>Paystack Gateway for Paid Membership Pro is awesome! Can I contribute?</p><p>Yes you can! Join in on our <a href=\"https://github.com/strangerstudios/paystack-gateway-paid-memberships-pro\">GitHub repository</a></p>\";s:9:\"Changelog\";s:355:\"<h4>Changelog</h4><p>1.9.1 - 2025-11-07</p><ul>\n<li>BUG FIX: Fixed an issue where PMPro would show a warning that the gateway is not configured correctly when Paystack is set as the primary gateway. #14 (@andrewlimaza)</li>\n<li>BUG FIX: Fixed an issue with error output when syncing a subscription failed in the WordPress admin. #15 (@DAnn2012)</li>\n</ul>\";s:6:\"Author\";s:30:\"Paid Memberships Pro, Paystack\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:94:\"http://license.paidmembershipspro.com/downloads/free/paystack-gateway-paid-memberships-pro.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:41:\"Paystack Gateway for Paid Memberships Pro\";}i:88;a:16:{s:4:\"Name\";s:25:\"PMPro Levels as UL Layout\";s:5:\"Title\";s:25:\"PMPro Levels as UL Layout\";s:9:\"PluginURI\";s:53:\"http://www.paidmembershipspro.com/wp/pmpro-ul-levels/\";s:4:\"Slug\";s:15:\"pmpro-ul-levels\";s:6:\"plugin\";s:35:\"pmpro-ul-levels/pmpro-ul-levels.php\";s:7:\"Version\";s:2:\".1\";s:11:\"Description\";s:107:\"Display your Membership Levels page in a UL Layout (includes classes for Foundation by ZURB Pricing table).\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:42:\"Stranger Studios / Tweaked by Lasse Larsen\";s:9:\"AuthorURI\";s:28:\"http://www.seventysixnyc.com\";s:8:\"Download\";s:77:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-ul-levels.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:25:\"PMPro Levels as UL Layout\";}i:89;a:16:{s:4:\"Name\";s:34:\"Paid Memberships Pro - Pods Add On\";s:5:\"Title\";s:34:\"Paid Memberships Pro - Pods Add On\";s:9:\"PluginURI\";s:60:\"https://www.paidmembershipspro.com/add-ons/pods-integration/\";s:4:\"Slug\";s:10:\"pmpro-pods\";s:6:\"plugin\";s:25:\"pmpro-pods/pmpro-pods.php\";s:7:\"Version\";s:3:\"1.1\";s:11:\"Description\";s:232:\"Integrates Paid Memberships Pro with the Pods Framework to add groups of fields to many areas of your membership site including Member Profiles, the Membership Checkout page, and admin screens including Membership Levels and Orders.\";s:12:\"Installation\";s:323:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro and Pods Framework plugins installed and activated.</li>\n<li>Upload the <code>pmpro-pods</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:706:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-pods/issues\">https://github.com/strangerstudios/pmpro-pods/issues</a></p>\n<p>For immediate help, also post to our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com/support\">https://www.paidmembershipspro.com/support</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:124:\"<h4>Changelog</h4><p>1.0.4 - 2024-10-18</p><ul>\n<li>FEATURE: Now updating the plugin from paidmembershipspro.com.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:68:\"https://license.paidmembershipspro.com/downloads/free/pmpro-pods.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:4:\"Pods\";}i:90;a:16:{s:4:\"Name\";s:60:\"Paid Memberships Pro - Post Affiliate Pro Integration Add On\";s:5:\"Title\";s:60:\"Paid Memberships Pro - Post Affiliate Pro Integration Add On\";s:9:\"PluginURI\";s:80:\"https://www.paidmembershipspro.com/add-ons/pmpro-post-affiliate-pro-integration/\";s:4:\"Slug\";s:24:\"pmpro-post-affiliate-pro\";s:6:\"plugin\";s:53:\"pmpro-post-affiliate-pro/pmpro-post-affiliate-pro.php\";s:7:\"Version\";s:3:\"0.3\";s:11:\"Description\";s:67:\"Process an affiliate via Post Affiliate Pro after a PMPro checkout.\";s:12:\"Installation\";s:455:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-post-affiliate-pro</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit pmpro-post-affiliate-pro.php to enter your affiliate login link, username, and password.\n. Create links in Post Affiliate Pro as you would normally. The plugin will track clicks and sales through the PAP API.</li>\n</ol>\";s:3:\"FAQ\";s:571:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-post-affiliate-pro/issues\">https://github.com/strangerstudios/pmpro-post-affiliate-pro/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:168:\"<h4>Changelog</h4><p>0.3 - 2025-05-27</p><ul>\n<li>BUG FIX: Fixed a fatal error where curly braces are no longer supported in PHP 8 and above. (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:31:\"https://www.strangerstudios.com\";s:8:\"Download\";s:81:\"http://license.paidmembershipspro.com/downloads/free/pmpro-post-affiliate-pro.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:30:\"Post Affiliate Pro Integration\";}i:91;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Proration Add On\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Proration Add On\";s:9:\"PluginURI\";s:53:\"http://www.paidmembershipspro.com/wp/pmpro-proration/\";s:4:\"Slug\";s:15:\"pmpro-proration\";s:6:\"plugin\";s:35:\"pmpro-proration/pmpro-proration.php\";s:7:\"Version\";s:5:\"1.0.4\";s:11:\"Description\";s:62:\"Simple proration for membership level upgrades and downgrades.\";s:12:\"Installation\";s:207:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-proration</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:756:\"<h4>Changelog</h4><p>1.0.4 - 2026-05-28</p><ul>\n<li>BUG FIX: Fixed an issue where proration could credit a user for a recurring payment they had not actually paid when their subscription was past due on PMPro v3.6 or later. The Add On now skips proration entirely for past-due subscriptions and lets the checkout proceed at full price. #40 (@dparker1005)</li>\n<li>BUG FIX: Fixed an issue where a delayed downgrade could be processed prematurely when a recurring payment failed on PMPro v3.6 or later. Delayed downgrades now process when the subscription\'s next recurring payment is successfully collected (<code>pmpro_subscription_payment_completed</code>) instead of when an order is created (<code>pmpro_added_order</code>). #40 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:76:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-proration.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:9:\"Proration\";}i:92;a:16:{s:4:\"Name\";s:51:\"Paid Memberships Pro - Reason For Cancelling Add On\";s:5:\"Title\";s:51:\"Paid Memberships Pro - Reason For Cancelling Add On\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/pmpro-reason-cancelling/\";s:4:\"Slug\";s:27:\"pmpro-reason-for-cancelling\";s:6:\"plugin\";s:59:\"pmpro-reason-for-cancelling/pmpro-reason-for-cancelling.php\";s:7:\"Version\";s:5:\"1.2.1\";s:11:\"Description\";s:67:\"Adds a field to specify a reason for cancelling to the cancel page.\";s:12:\"Installation\";s:235:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-reason-for-cancelling</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:331:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-reason-for-cancelling/issues\">https://github.com/strangerstudios/pmpro-reason-for-cancelling/issues</a></p>\";s:9:\"Changelog\";s:512:\"<h4>Changelog</h4><p>1.2.1 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: The Edit Member \"Cancellation Reasons\" panel now shows an em-dash for missing dates or levels and a <code>[deleted level #N]</code> placeholder when a referenced level no longer exists. #40 (@andrewlimaza)</li>\n<li>BUG FIX: Fixed PHP errors and incorrect translation handling on the Edit Member \"Cancellation Reasons\" panel when a user\'s stored cancellation reason was in the older string format instead of an array. #40 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:88:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-reason-for-cancelling.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:21:\"Reason For Cancelling\";}i:93;a:16:{s:4:\"Name\";s:39:\"Paid Memberships Pro - Recurring Emails\";s:5:\"Title\";s:39:\"Paid Memberships Pro - Recurring Emails\";s:9:\"PluginURI\";s:77:\"https://www.paidmembershipspro.com/add-ons/recurring-payment-email-reminders/\";s:4:\"Slug\";s:22:\"pmpro-recurring-emails\";s:6:\"plugin\";s:49:\"pmpro-recurring-emails/pmpro-recurring-emails.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:138:\"Send members a reminder email prior to when their next recurring subscription payment is made to let them know payment is processing soon.\";s:12:\"Installation\";s:230:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-recurring-emails</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:567:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-recurring-emails/issues\">https://github.com/strangerstudios/pmpro-recurring-emails/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:962:\"<h4>Changelog</h4><p>1.0 - 2023-12-22</p><ul>\n<li>ENHANCEMENT: For sites running PMPro 3.0+, this plugin now uses the Subscriptions table to more accurately determine when to send emails and to add compatibility with Multiple Memberships Per User. #28 (@dparker1005)</li>\n<li>ENHANCEMENT: Added a new constant <code>PMPROR_DEBUG</code> to allow setting an email address to send log data to or to have the log data printed to a file. #34 (@dparker1005)</li>\n<li>ENHANCEMENT: Added localization support. #35 (@dparker1005)</li>\n<li>BUG FIX: Fixed issue where customized email template data may not be sent. #36 (@andrewlimaza, @dparker1005)</li>\n<li>BUG FIX: Fixed issue where the <code>!!billing_amount!!</code> email template variable would sometimes incorrectly return $0 instead of the actual billing amount. #29 (@MaximilianoRicoTabo)</li>\n<li>REFACTOR: Now using <code>get_option()</code> instead of <code>pmpro_getOption()</code>. #31 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:84:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-recurring-emails.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:16:\"Recurring Emails\";}i:94;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Register Helper Add On\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Register Helper Add On\";s:9:\"PluginURI\";s:97:\"https://www.paidmembershipspro.com/add-ons/pmpro-register-helper-add-checkout-and-profile-fields/\";s:4:\"Slug\";s:21:\"pmpro-register-helper\";s:6:\"plugin\";s:47:\"pmpro-register-helper/pmpro-register-helper.php\";s:7:\"Version\";s:5:\"1.8.3\";s:11:\"Description\";s:90:\"Add custom form fields to membership checkout and user profiles with Paid Memberships Pro.\";s:12:\"Installation\";s:2976:\"<p>Installation</p><p>Note: This plugin doesn\'t require <a href=\"https://wordpress.org/plugins/paid-memberships-pro/\">Paid Memberships Pro</a>, but it is strongly recommended for sites that want to build a membership site and capture user profile information as part of free or paid member registration.</p>\n<h3>Install PMPro Register Helper from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro Register Helper\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - Register Helper Add On\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro Register Helper Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-register-helper</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - Register Helper\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Set Up Your Custom Fields</h3><p>Adding Fields to Membership Checkout</p><p>Register Helper allows you to add fields to a variety of places within the Membership Checkout page using Paid Memberships Pro. Fields can be added to existing locations including:</p>\n<ul>\n<li>after_username</li>\n<li>after_password</li>\n<li>after_email</li>\n<li>after_captcha</li>\n<li>after_billing_fields</li>\n<li>before_submit_button</li>\n</ul>\n<p>If you would like to add fields to the profile only, specify the \'just_profile\' location.</p>\n<p>Fields must be configured using custom code. We offer support for creating up to 5 fields as part of your <a href=\"https://www.paidmembershipspro.com/pricing/?utm_source=wordpress-org&amp;utm_medium=readme&amp;utm_campaign=pmpro-register-helper\">premium membership</a>.</p>\n<p><a href=\"https://www.paidmembershipspro.com/documentation/register-helper-documentation/adding-fields/?utm_source=wordpress-org&amp;utm_medium=readme&amp;utm_campaign=pmpro-register-helper\">View the full documentation on adding fields</a> and <a href=\"https://www.youtube.com/watch?v=VVTHYPQpfZ4\">check out this video demo on Register Helper set up</a>.</p><p>Adding New Sections to Membership Checkout</p><p>You can add a new box or \'section\' to the Membership Checkout form using the \'checkout_boxes\' feature. Your newly created box includes a title, description, and loads in the specified location.</p>\n<p><a href=\"https://www.paidmembershipspro.com/documentation/register-helper-documentation/adding-fields/#checkout-boxes?utm_source=wordpress-org&amp;utm_medium=readme&amp;utm_campaign=pmpro-register-helper\">Read the documentation on Custom Checkout Boxes</a></p><p>Restrict Membership Checkout by Email Address or Username</p><p>Add your list of custom \"approved\" email addresses or usernames to the \"Restrict by Email\" or \"Restrict by Username\" field on the Memberships &gt; Settings &gt; Membership Levels &gt; Edit Level admin page.</p>\";s:3:\"FAQ\";s:319:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-register-helper/issues\">https://github.com/strangerstudios/pmpro-register-helper/issues</a></p>\";s:9:\"Changelog\";s:147:\"<h4>Changelog</h4><p>1.8.3 - 2023-03-17</p><ul>\n<li>BUG FIX: Reverting v1.8.2 changes which were not needed and potentially problematic.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:64:\"https://downloads.wordpress.org/plugin/pmpro-register-helper.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:15:\"Register Helper\";}i:95;a:16:{s:4:\"Name\";s:47:\"Paid Memberships Pro - Require Strong Passwords\";s:5:\"Title\";s:47:\"Paid Memberships Pro - Require Strong Passwords\";s:9:\"PluginURI\";s:68:\"https://www.paidmembershipspro.com/add-ons/require-strong-passwords/\";s:4:\"Slug\";s:22:\"pmpro-strong-passwords\";s:6:\"plugin\";s:49:\"pmpro-strong-passwords/pmpro-strong-passwords.php\";s:7:\"Version\";s:5:\"0.5.2\";s:11:\"Description\";s:51:\"Force users to submit strong passwords on checkout.\";s:12:\"Installation\";s:247:\"<p>Installation</p><ol>\n<li>Upload the â€˜pmpro-strong-passwordsâ€™ directory to the â€˜/wp-content/plugins/â€™ directory of your site.</li>\n<li>Activate the plugin through the â€˜Pluginsâ€™ menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:188:\"<p>Frequently Asked Questions</p><p>I need help with this plugin</p><p>Please post support topics to <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a></p>\";s:9:\"Changelog\";s:437:\"<h4>Changelog</h4><p>0.5.2 - 2025-10-09</p><ul>\n<li>ENHANCEMENT: Update the Zxcvbn library to latest release v1.4.2. #62 (@andrewlimaza)</li>\n<li>ENHANCEMENT: Show a default error message if no message is returned from the Zxcvbn library. #60 (@andrewlimaza)</li>\n<li>BUG FIX: Fixed an issue where the password hint and meter would show up on the Signup Shortcode Add On when the password field was hidden. #61 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/free/pmpro-strong-passwords.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:24:\"Require Strong Passwords\";}i:96;a:16:{s:4:\"Name\";s:35:\"Paid Memberships Pro - Roles Add On\";s:5:\"Title\";s:35:\"Paid Memberships Pro - Roles Add On\";s:9:\"PluginURI\";s:55:\"https://www.paidmembershipspro.com/add-ons/pmpro-roles/\";s:4:\"Slug\";s:11:\"pmpro-roles\";s:6:\"plugin\";s:27:\"pmpro-roles/pmpro-roles.php\";s:7:\"Version\";s:5:\"1.5.2\";s:11:\"Description\";s:48:\"Adds a WordPress Role for each Membership Level.\";s:12:\"Installation\";s:252:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-roles</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>That\'s it. No settings.</li>\n</ol>\";s:3:\"FAQ\";s:547:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-roles/issues\">https://github.com/strangerstudios/pmpro-roles/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:663:\"<h4>Changelog</h4><p>1.5.2 - 2026-06-12</p><ul>\n<li>SECURITY: Users now need the manage_options capability to view or modify the roles assigned to a membership level. Users who can edit levels without that capability now see a read-only list of the level\'s assigned roles. #54 (@dparker1005)</li>\n<li>SECURITY: Submitted role mappings are now validated against the roles offered in the level settings UI so that a tampered request cannot assign hidden roles such as administrator or another level\'s role. #54 (@dparker1005)</li>\n<li>BUG FIX: Deleting a membership level now removes that level\'s role from any users who still have it. #54 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:68:\"http://license.paidmembershipspro.com/downloads/free/pmpro-roles.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:5:\"Roles\";}i:97;a:16:{s:4:\"Name\";s:29:\"Paid Memberships Pro - Series\";s:5:\"Title\";s:29:\"Paid Memberships Pro - Series\";s:9:\"PluginURI\";s:78:\"https://www.paidmembershipspro.com/add-ons/pmpro-series-for-drip-feed-content/\";s:4:\"Slug\";s:12:\"pmpro-series\";s:6:\"plugin\";s:29:\"pmpro-series/pmpro-series.php\";s:7:\"Version\";s:5:\"1.0.1\";s:11:\"Description\";s:121:\"Drip feed content to your members over the course of their membership. Serializes content by # of days post-registration.\";s:12:\"Installation\";s:403:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-series</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Navigate to the Series menu in the WordPress dashboard to create a new series.</li>\n<li>Add posts to series using the \"Posts in this Series\" meta box under the post content.</li>\n</ol>\";s:3:\"FAQ\";s:301:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-series/issues\">https://github.com/strangerstudios/pmpro-series/issues</a></p>\";s:9:\"Changelog\";s:294:\"<h4>Changelog</h4><p>1.0.1 - 2026-05-05</p><ul>\n<li>ENHANCEMENT: Updated the New Content email template to use liquid syntax (<code>{{ }}</code>) when running PMPro v3.7 or higher. The legacy <code>!!</code> syntax continues to be used on older versions of PMPro. #122 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:73:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-series.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:6:\"Series\";}i:98;a:16:{s:4:\"Name\";s:27:\"Seriously Simple Podcasting\";s:5:\"Title\";s:27:\"Seriously Simple Podcasting\";s:9:\"PluginURI\";s:122:\"https://castos.com/seriously-simple-podcasting/?utm_medium=sspodcasting&utm_source=wordpress&utm_campaign=wpplugin_08_2019\";s:4:\"Slug\";s:27:\"seriously-simple-podcasting\";s:6:\"plugin\";s:59:\"seriously-simple-podcasting/seriously-simple-podcasting.php\";s:7:\"Version\";s:6:\"2.13.0\";s:11:\"Description\";s:104:\"Podcasting the way it\'s meant to be. No mess, no fuss - just you and your content taking over the world.\";s:12:\"Installation\";s:845:\"<p>Installation</p><p>Installing \"Seriously Simple Podcasting\" can be done either by searching for \"Seriously Simple Podcasting\" via the \"Plugins &gt; Add New\" screen in your WordPress dashboard, or by using the following steps:</p>\n<ol>\n<li>Download the plugin via WordPress.org</li>\n<li>Upload the ZIP file through the \'Plugins &gt; Add New &gt; Upload\' screen in your WordPress dashboard</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress</li>\n<li>Customise the plugin from the \'Podcast &gt; Settings\' page</li>\n</ol><p>Where are the FAQs?</p><p>You can find complete user and developer documentation (along with the FAQs) on <a href=\"https://castos.com/podcast-hosting-wordpress/?utm_medium=sspodcasting&amp;utm_source=wordpress&amp;utm_campaign=wpplugin_08_2019\">the Seriously Simple Podcasting documentation site</a>.</p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:703:\"<h4>Changelog</h4><p>2.13.0</p><ul>\n<li>2022-04-18</li>\n<li>UPDATE SUMMARY: Podping notification when feed is updated, code refactoring, minor improvements</li>\n<li>[UPDATE] Podping notification when feed is updated</li>\n<li>[UPDATE] Code refactoring: moved podcast CPT functions to a separate controller</li>\n<li>[UPDATE] PMPro integration: possibility to enable/disable integration with settings</li>\n<li>[UPDATE] Changed the contributing guide from GitHub to GitLab</li>\n<li>[FIX] Fixed Elementor episode list widget in compact mode</li>\n<li>[FIX] Bug fixed: Yoast integration critical error</li>\n<li>[FIX] Fixed the Twitter share URL</li>\n<li>[FIX] Fixed intermittent update episode error</li>\n</ul>\";s:6:\"Author\";s:6:\"Castos\";s:9:\"AuthorURI\";s:94:\"https://castos.com/?utm_medium=sspodcasting&utm_source=wordpress&utm_campaign=wpplugin_08_2019\";s:8:\"Download\";s:70:\"https://downloads.wordpress.org/plugin/seriously-simple-podcasting.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:27:\"Seriously Simple Podcasting\";}i:99;a:16:{s:4:\"Name\";s:50:\"Paid Memberships Pro - Set Expiration Dates Add On\";s:5:\"Title\";s:50:\"Paid Memberships Pro - Set Expiration Dates Add On\";s:9:\"PluginURI\";s:64:\"http://www.paidmembershipspro.com/wp/pmpro-set-expiration-dates/\";s:4:\"Slug\";s:26:\"pmpro-set-expiration-dates\";s:6:\"plugin\";s:57:\"pmpro-set-expiration-dates/pmpro-set-expiration-dates.php\";s:7:\"Version\";s:3:\"0.8\";s:11:\"Description\";s:95:\"Set a specific expiration date (e.g. 2026-12-31) for a PMPro membership level or discount code.\";s:12:\"Installation\";s:318:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-set-expiration-date</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Change the expiration date on the edit levels and edit discount code pages.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:484:\"<h4>Changelog</h4><p>0.8 - 2026-03-30</p><ul>\n<li>BUG FIX: Fixed an issue where the expiration date was not being correctly set when using a discount code with a set expiration date. (@dwanjuki)</li>\n<li>BUG FIX: Corrected expiration date calculation for future-based rules. For example, \"Y2-M1-01\" now correctly resolves to \"next year â€“ current month â€“ 01\". Previously, it incorrectly advanced both the month and year (next month, next year). (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:87:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-set-expiration-dates.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:20:\"Set Expiration Dates\";}i:100;a:16:{s:4:\"Name\";s:47:\"Paid Memberships Pro - Signup Shortcode & Block\";s:5:\"Title\";s:47:\"Paid Memberships Pro - Signup Shortcode & Block\";s:9:\"PluginURI\";s:66:\"https://www.paidmembershipspro.com/add-ons/pmpro-signup-shortcode/\";s:4:\"Slug\";s:22:\"pmpro-signup-shortcode\";s:6:\"plugin\";s:49:\"pmpro-signup-shortcode/pmpro-signup-shortcode.php\";s:7:\"Version\";s:3:\"1.2\";s:11:\"Description\";s:125:\"Embed signup forms anywhere on your WordPress site. Designed to simplify membership registration, especially for free levels.\";s:12:\"Installation\";s:438:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-signup-shortcode</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>Add a sign up form to a post/widget/page using a shortcode:</p>\n<p>[pmpro_signup level=\"3\" intro=\"0\" redirect=\"referrer\" short=\"emailonly\" submit_button=\"Join Now\" title=\"Sign Up for Gold Membership\"]</p>\";s:3:\"FAQ\";s:321:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-signup-shortcode/issues\">https://github.com/strangerstudios/pmpro-signup-shortcode/issues</a></p>\";s:9:\"Changelog\";s:763:\"<h4>Changelog</h4><p>1.2 - 2026-05-14</p><ul>\n<li>FEATURE: Added a <code>levels</code> shortcode attribute that lets you offer a dropdown of multiple membership levels on the signup form. Use <code>levels=\"all\"</code> to show all levels or <code>levels=\"1,2,3\"</code> to limit the selection. Levels the user already holds are shown as disabled. #37 (@louiswol94)</li>\n<li>ENHANCEMENT: Replaced the inline reCAPTCHA and Terms of Service rendering with the <code>pmpro_checkout_preheader</code> and <code>pmpro_checkout_before_submit_button</code> action hooks, so the signup form picks up these features (and any other plugin that integrates with the default checkout) through PMPro core. Requires Paid Memberships Pro 3.2 or higher. #73 (@andrewlimaza)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-signup-shortcode.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:24:\"Signup Shortcode & Block\";}i:101;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Sitewide Sales Add On\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Sitewide Sales Add On\";s:9:\"PluginURI\";s:58:\"https://www.paidmembershipspro.com/add-ons/sitewide-sales/\";s:4:\"Slug\";s:20:\"pmpro-sitewide-sales\";s:6:\"plugin\";s:45:\"pmpro-sitewide-sales/pmpro-sitewide-sales.php\";s:7:\"Version\";s:5:\"1.2.5\";s:11:\"Description\";s:143:\"Create, manage, and view advanced reports for a sitewide or flash sale on membership (Black Friday or Cyber Monday) using Paid Memberships Pro.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:82:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-sitewide-sales.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:14:\"Sitewide Sales\";}i:102;a:16:{s:4:\"Name\";s:40:\"Paid Memberships Pro - Slack Integration\";s:5:\"Title\";s:40:\"Paid Memberships Pro - Slack Integration\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/pmpro-slack-integration/\";s:4:\"Slug\";s:11:\"pmpro-slack\";s:6:\"plugin\";s:27:\"pmpro-slack/pmpro-slack.php\";s:7:\"Version\";s:5:\"1.1.2\";s:11:\"Description\";s:66:\"Configure Slack notifications for the Paid Memberships Pro plugin.\";s:12:\"Installation\";s:339:\"<p>Installation</p><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-slack</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>The settings page is at Settings --&gt; PMPro Slack in the WP dashboard.</li>\n</ol>\";s:3:\"FAQ\";s:545:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-slack/issues\">https://github.com/strangerstudios/pmpro-slack/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:981:\"<h4>Changelog</h4><p>1.1.2 - 2026-05-04</p><ul>\n<li>ENHANCEMENT: Improved translation support across the settings page and plugin row links by wrapping strings in proper i18n functions and correcting the text domain. #13 (@dparker1005)</li>\n<li>BUG FIX: Slack notifications now send for offsite gateways (Stripe Checkout, PayPal Standard, 2Checkout) where the user is not logged in when <code>pmpro_after_checkout</code> fires asynchronously from a webhook or IPN. #12 (@dparker1005)</li>\n<li>BUG FIX: Fixed the \"Something went wrong\" error echo so it now outputs the actual error message returned by the Slack webhook request instead of the literal string <code>$error_message</code>. #12 (@dparker1005)</li>\n<li>BUG FIX: Fixed a stray double quote in the levels-to-notify <code>&lt;select&gt;</code> <code>name</code> attribute on the settings page and added missing <code>esc_attr()</code> / <code>esc_html()</code> on rendered level IDs and names. #13 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:68:\"http://license.paidmembershipspro.com/downloads/free/pmpro-slack.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:17:\"Slack Integration\";}i:103;a:16:{s:4:\"Name\";s:27:\"Paid Memberships Pro - SMTP\";s:5:\"Title\";s:27:\"Paid Memberships Pro - SMTP\";s:9:\"PluginURI\";s:53:\"https://www.paidmembershipspro.com/add-ons/pmpro-smtp\";s:4:\"Slug\";s:10:\"pmpro-smtp\";s:6:\"plugin\";s:25:\"pmpro-smtp/pmpro-smtp.php\";s:7:\"Version\";s:5:\"0.1.1\";s:11:\"Description\";s:145:\"Improve email deliverability for your membership site. Connect to SMTP providers and transactional email APIs with email logging and diagnostics.\";s:12:\"Installation\";s:300:\"<p>Installation</p><ol>\n<li>Upload the plugin to <code>/wp-content/plugins/</code> or install it as usual.</li>\n<li>Activate the plugin.</li>\n<li>Go to <code>Memberships &gt; SMTP</code>.</li>\n<li>Choose a provider and save your credentials.</li>\n<li>Send a test email to confirm delivery.</li>\n</ol>\";s:3:\"FAQ\";s:814:\"<p>Frequently Asked Questions</p><p>Can I use this with Google Workspace or Gmail?</p><p>Yes. Use the <code>Custom SMTP</code> connector with:</p>\n<ul>\n<li>Host: <code>smtp.gmail.com</code></li>\n<li>Port: <code>587</code></li>\n<li>Encryption: <code>TLS</code></li>\n<li>Authentication: enabled</li>\n<li>Username: your full Google email address</li>\n<li>Password: your Google app password</li>\n</ul><p>Does this replace PMPro email logging?</p><p>No. PMPro core continues to handle email logging.</p><p>Are emails formatted the same on an API provider as with Custom SMTP?</p><p>Yes. PMPro\'s email formatting — including the optional <code>email_header.html</code> / <code>email_footer.html</code> theme templates — is applied on both the <code>Custom SMTP</code> (PHPMailer) path and the API connector path.</p>\";s:9:\"Changelog\";s:249:\"<h4>Changelog</h4><p>0.1.1 - 2026-07-17</p><ul>\n<li>BUG FIX: Fixed an issue where emails sent through API-based connectors were missing PMPro\'s email formatting. #4 (@dparker1005)</li>\n</ul><p>0.1 - 2026-07-15</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:67:\"http://license.paidmembershipspro.com/downloads/free/pmpro-smtp.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:4:\"SMTP\";}i:104;a:16:{s:4:\"Name\";s:43:\"Paid Memberships Pro - Social Locker Add On\";s:5:\"Title\";s:43:\"Paid Memberships Pro - Social Locker Add On\";s:9:\"PluginURI\";s:63:\"https://www.paidmembershipspro.com/add-ons/pmpro-social-locker/\";s:4:\"Slug\";s:19:\"pmpro-social-locker\";s:6:\"plugin\";s:43:\"pmpro-social-locker/pmpro-social-locker.php\";s:7:\"Version\";s:4:\".1.1\";s:11:\"Description\";s:60:\"Integrate PMPro with the Social Locker plugin from OnePress.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:77:\"https://license.paidmembershipspro.com/downloads/free/pmpro-social-locker.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:13:\"Social Locker\";}i:105;a:16:{s:4:\"Name\";s:42:\"Paid Memberships Pro - Social Login Add On\";s:5:\"Title\";s:42:\"Paid Memberships Pro - Social Login Add On\";s:9:\"PluginURI\";s:63:\"https://www.paidmembershipspro.com/add-ons/social-login-add-on/\";s:4:\"Slug\";s:18:\"pmpro-social-login\";s:6:\"plugin\";s:41:\"pmpro-social-login/pmpro-social-login.php\";s:7:\"Version\";s:5:\"1.1.1\";s:11:\"Description\";s:79:\"Offer social login for your membership siteâ€™s checkout and log in forms.\";s:12:\"Installation\";s:749:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro and either Nextend Social Login (<a href=\"https://wordpress.org/plugins/nextend-facebook-connect/\">https://wordpress.org/plugins/nextend-facebook-connect/</a>) or Super Socializer (<a href=\"https://wordpress.org/plugins/super-socializer/\">https://wordpress.org/plugins/super-socializer/</a>) installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-social-login/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:483:\"<h4>Changelog</h4><p>1.1.1 - 2026-04-30</p><ul>\n<li>ENHANCEMENT: Added a documentation link to the Social Login Settings panel on the Edit Membership Level admin page. #30 (@kimcoleman)</li>\n<li>ENHANCEMENT: Added \"Docs\" and \"Support\" links to the plugin row meta on the Plugins admin screen. #26 (@ipokkel)</li>\n<li>BUG FIX: Fixed PHP notices about translations being loaded too early for the <code>pmpro-social-login</code> text domain on WordPress 6.7+. #29 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-social-login.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:12:\"Social Login\";}i:106;a:16:{s:4:\"Name\";s:47:\"Paid Memberships Pro - Sponsored Members Add On\";s:5:\"Title\";s:47:\"Paid Memberships Pro - Sponsored Members Add On\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/pmpro-sponsored-members/\";s:4:\"Slug\";s:23:\"pmpro-sponsored-members\";s:6:\"plugin\";s:51:\"pmpro-sponsored-members/pmpro-sponsored-members.php\";s:7:\"Version\";s:6:\"0.10.2\";s:11:\"Description\";s:84:\"Generate discount code for a main account holder to distribute to sponsored members.\";s:12:\"Installation\";s:702:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-sponsored-members</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Create one level for paying account holders and one level for sponsored members.</li>\n<li>Edit the PMPROSM_MAIN_ACCOUNT_LEVEL constant in the plugin file to match your main account level id.</li>\n<li>Edit the PMPROSM_SPONSORED_ACCOUNT_LEVEL constant in the plugin file to match your sponsored level id.</li>\n<li>Edit the second half of the pmprosm_pmpro_after_change_membership_level() function to change the values of the discount code given to paying members.</li>\n</ol>\";s:3:\"FAQ\";s:323:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-sponsored-members/issues\">https://github.com/strangerstudios/pmpro-sponsored-members/issues</a></p>\";s:9:\"Changelog\";s:408:\"<h4>Changelog</h4><p>0.10.2 - 2023-07-25</p><ul>\n<li>BUG FIX: Fixed issue where the seat cost would always show $0 at checkout.</li>\n<li>ENHANCEMENT: Updated <code>&lt;h3&gt;</code> tags to <code>&lt;h2&gt;</code> tags for better accessibility.</li>\n<li>REFACTOR: Now getting level information at checkout from <code>pmpro_getLevelAtCheckout()</code> instead of pulling from <code>$_REQUEST</code></li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:85:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-sponsored-members.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:17:\"Sponsored Members\";}i:107;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - Square Add On\";s:5:\"Title\";s:36:\"Paid Memberships Pro - Square Add On\";s:9:\"PluginURI\";s:49:\"https://www.paidmembershipspro.com/add-ons/square\";s:4:\"Slug\";s:12:\"pmpro-square\";s:6:\"plugin\";s:29:\"pmpro-square/pmpro-square.php\";s:7:\"Version\";s:5:\"1.0.1\";s:11:\"Description\";s:36:\"PMPro Gateway integration for Square\";s:12:\"Installation\";s:533:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-square</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>Navigate to Memberships &gt; Settings &gt; Payment Gateways &amp; SSL and select the Square payment gateway. You will then need to fill out the required account credentials to connect your website to the payment gateway.</p>\";s:3:\"FAQ\";s:495:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-square/issues\">https://github.com/strangerstudios/pmpro-square/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:475:\"<h4>Changelog</h4><p>1.0.1 - 2026-06-26</p><ul>\n<li>BUG FIX: Fixed free checkouts (free levels, or discount codes that reduce the total to $0) failing to submit when Square is the active gateway. #23 (@dparker1005)</li>\n<li>BUG FIX: Corrected the Square gateway description shown on the Payment Settings page to accurately reflect supported payment methods (credit and debit card only). #22 (@dparker1005)</li>\n</ul><p>1.0 - 2026-06-24</p><ul>\n<li>Initial release.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:69:\"http://license.paidmembershipspro.com/downloads/free/pmpro-square.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:6:\"Square\";}i:108;a:16:{s:4:\"Name\";s:38:\"Paid Memberships Pro - State Dropdowns\";s:5:\"Title\";s:38:\"Paid Memberships Pro - State Dropdowns\";s:9:\"PluginURI\";s:58:\"https://www.paidmembershipspro.com/add-ons/state-dropdown/\";s:4:\"Slug\";s:21:\"pmpro-state-dropdowns\";s:6:\"plugin\";s:47:\"pmpro-state-dropdowns/pmpro-state-dropdowns.php\";s:7:\"Version\";s:5:\"0.5.3\";s:11:\"Description\";s:85:\"Creates an autopopulated field for countries and states/provinces for billing fields.\";s:12:\"Installation\";s:314:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-state-dropdowns</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:1335:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-state-dropdowns/issues\">https://github.com/strangerstudios/pmpro-state-dropdowns/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>The state fields are not showing correctly for pre-existing users</p><p>Existing users that have entered their State/Province before using this add-on may be required to update their profile while PMPro State Dropdowns is activated. This is usually caused by incorrect spelling of the State/Province. (This only affects the front-end of your site and won\'t affect the previously saved user meta)</p><p>Some States/Provinces are missing or incorrect from the State/Province dropdown</p><p>Not all countries may be fully supported regarding the State/Province list. If you find a fault with your country\'s State/Province list, please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-state-dropdowns/issues\">https://github.com/strangerstudios/pmpro-state-dropdowns/issues</a></p>\";s:9:\"Changelog\";s:294:\"<h4>Changelog</h4><p>0.5.3 - 2026-04-30</p><ul>\n<li>BUG FIX: Added compatibility with the order ID URL parameter introduced in Paid Memberships Pro v3.6. Without this fix, edits made on the admin Edit Order page would fall back to user meta or the default country. #75 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:82:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-state-dropdowns.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:15:\"State Dropdowns\";}i:109;a:16:{s:4:\"Name\";s:44:\"Paid Memberships Pro - Stripe Billing Limits\";s:5:\"Title\";s:44:\"Paid Memberships Pro - Stripe Billing Limits\";s:9:\"PluginURI\";s:71:\"https://www.paidmembershipspro.com/add-ons/pmpro-stripe-billing-limits/\";s:4:\"Slug\";s:27:\"pmpro-stripe-billing-limits\";s:6:\"plugin\";s:59:\"pmpro-stripe-billing-limits/pmpro-stripe-billing-limits.php\";s:7:\"Version\";s:3:\"1.0\";s:11:\"Description\";s:57:\"Allow Billing Limits with Stripe as your primary gateway.\";s:12:\"Installation\";s:360:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated and that Stripe is your primary gateway.</li>\n<li>Upload the <code>pmpro-stripe-billing-limits</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:525:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-stripe-billing-limits/issues\">https://github.com/strangerstudios/pmpro-stripe-billing-limits/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"https://www.paidmembershipspro.com\">https://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:349:\"<h4>Changelog</h4><p>1.0 - 2023-01-09</p><ul>\n<li>BUG FIX/ENHANCEMENT: No longer relying on usermeta to track billing limit data.</li>\n<li>BUG FIX/ENHANCEMENT: Improved compatibility with PMPro Multiple Memberships Per User.</li>\n<li>REFACTOR: Simplified logic throughout the plugin to increase stability. Updating to 1.0 to reflect this.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:85:\"https://license.paidmembershipspro.com/downloads/free/pmpro-stripe-billing-limits.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:21:\"Stripe Billing Limits\";}i:110;a:16:{s:4:\"Name\";s:49:\"Paid Memberships Pro - Subscription Delays Add On\";s:5:\"Title\";s:49:\"Paid Memberships Pro - Subscription Delays Add On\";s:9:\"PluginURI\";s:63:\"https://www.paidmembershipspro.com/add-ons/subscription-delays/\";s:4:\"Slug\";s:25:\"pmpro-subscription-delays\";s:6:\"plugin\";s:55:\"pmpro-subscription-delays/pmpro-subscription-delays.php\";s:7:\"Version\";s:5:\"0.6.2\";s:11:\"Description\";s:118:\"Adds a field to delay the start of a subscription for membership levels and discount codes for variable-length trials.\";s:12:\"Installation\";s:266:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-subscription-delays</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>That\'s it. No settings.</li>\n</ol>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:518:\"<h4>Changelog</h4><p>0.6.2 - 2026-05-04</p><ul>\n<li>BUG FIX: Resolved a PHP 8.1+ \"automatic conversion of false to array is deprecated\" notice when saving discount codes by returning an empty array from <code>pmpro_getDCSDs()</code> instead of <code>false</code> when no delays are stored. #52 (@dparker1005)</li>\n<li>BUG FIX: Avoided a PHP warning in <code>pmprosd_level_cost_text()</code> when the <code>pmpro_level_cost_text</code> filter is fired without a valid level object. #50 (@MaximilianoRicoTabo)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:86:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-subscription-delays.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:19:\"Subscription Delays\";}i:111;a:16:{s:4:\"Name\";s:48:\"Paid Memberships Pro - Table Layout Plugin Pages\";s:5:\"Title\";s:48:\"Paid Memberships Pro - Table Layout Plugin Pages\";s:9:\"PluginURI\";s:69:\"https://www.paidmembershipspro.com/add-ons/table-layout-plugin-pages/\";s:4:\"Slug\";s:17:\"pmpro-table-pages\";s:6:\"plugin\";s:39:\"pmpro-table-pages/pmpro-table-pages.php\";s:7:\"Version\";s:2:\".1\";s:11:\"Description\";s:142:\"An archived version of the table-based layouts for default Paid Memberships Pro pages, including the Checkout, Billing, and Confirmation pages\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:0:\"\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"https://license.paidmembershipspro.com/downloads/standard/pmpro-table-pages.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:25:\"Table Layout Plugin Pages\";}i:112;a:16:{s:4:\"Name\";s:35:\"Paid Memberships Pro - Testimonials\";s:5:\"Title\";s:35:\"Paid Memberships Pro - Testimonials\";s:9:\"PluginURI\";s:56:\"https://www.paidmembershipspro.com/add-ons/testimonials/\";s:4:\"Slug\";s:18:\"pmpro-testimonials\";s:6:\"plugin\";s:41:\"pmpro-testimonials/pmpro-testimonials.php\";s:7:\"Version\";s:5:\"0.1.1\";s:11:\"Description\";s:109:\"Collect, approve, and display member testimonials with review schema on the frontend of your membership site.\";s:12:\"Installation\";s:226:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-testimonials</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\";s:3:\"FAQ\";s:313:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-testimonials/issues\">https://github.com/strangerstudios/pmpro-testimonials/issues</a></p>\";s:9:\"Changelog\";s:495:\"<h4>Changelog</h4><p>0.1.1 - 2025-03-31</p><ul>\n<li>ENHANCEMENT: Improved accessibility for the star rating and other elements.</li>\n<li>BUG FIX: Fixed an issue where categories/tags were not being assigned via the shortcode.</li>\n<li>BUG FIX: Resolved issues where the wrong text-domain value was being used.</li>\n<li>BUG FIX: Fixed a fatal error when Paid Memberships Pro is deactivated.</li>\n<li>BUG FIX: Fixed an issue where required fields may have been skipped in certain cases.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:79:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-testimonials.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:12:\"Testimonials\";}i:113;a:16:{s:4:\"Name\";s:45:\"Paid Memberships Pro - Unlock Protocol Add On\";s:5:\"Title\";s:45:\"Paid Memberships Pro - Unlock Protocol Add On\";s:9:\"PluginURI\";s:70:\"https://www.paidmembershipspro.com/add-ons/unlock-protocol-integration\";s:4:\"Slug\";s:12:\"pmpro-unlock\";s:6:\"plugin\";s:29:\"pmpro-unlock/pmpro-unlock.php\";s:7:\"Version\";s:5:\"1.2.1\";s:11:\"Description\";s:52:\"Integrate Paid Memberships Pro with Unlock Protocol.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:226:\"<h4>Changelog</h4><p>1.2.1 - 2024-10-18</p><ul>\n<li>FEATURE: Now updating the plugin from paidmembershipspro.com.</li>\n<li>ENHANCEMENT: Added Dutch language files.</li>\n<li>ENHANCEMENT: Added \"Sepolia\" test network.</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:70:\"https://license.paidmembershipspro.com/downloads/free/pmpro-unlock.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:15:\"Unlock Protocol\";}i:114;a:16:{s:4:\"Name\";s:37:\"Paid Memberships Pro - Update Manager\";s:5:\"Title\";s:37:\"Paid Memberships Pro - Update Manager\";s:9:\"PluginURI\";s:58:\"https://www.paidmembershipspro.com/add-ons/update-manager/\";s:4:\"Slug\";s:20:\"pmpro-update-manager\";s:6:\"plugin\";s:45:\"pmpro-update-manager/pmpro-update-manager.php\";s:7:\"Version\";s:5:\"1.0.3\";s:11:\"Description\";s:106:\"Manage downloads and updates for all official Paid Memberships Pro Add Ons, themes, and translation files.\";s:12:\"Installation\";s:626:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>You must have Paid Memberships Pro installed and activated on your site.</li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Download the latest version of the plugin.</li>\n<li>Unzip the downloaded file to your computer.</li>\n<li>Upload the /pmpro-update-manager/ directory to the /wp-content/plugins/ directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n</ol>\n<p>View full documentation at: <a href=\"https://www.paidmembershipspro.com/add-ons/update-manager/\">https://www.paidmembershipspro.com/add-ons/update-manager/</a></p>\";s:3:\"FAQ\";s:0:\"\";s:9:\"Changelog\";s:1192:\"<h4>Changelog</h4><p>1.0.3 - 2026-08-20</p><ul>\n<li>BUG FIX: Fixed a fatal \"Cannot redeclare pmpro_setMessage()\" error when activating Paid Memberships Pro while the Update Manager was active. #19 (@dparker1005)</li>\n</ul><p>1.0.2 - 2026-07-30</p><ul>\n<li>BUG FIX: Fixed PMPro core and Add Ons never auto-updating in the background because the update hooks only registered on <code>admin_init</code>, which does not fire during WP-Cron where automatic updates run. #18 (@dalemugford)</li>\n<li>BUG FIX: Fixed a potential fatal error when the Add On update check runs outside of the WordPress admin, such as during WP-Cron. #18 (@dparker1005)</li>\n<li>BUG FIX: Fixed a fatal error when the PMPro License Server could not be reached while Paid Memberships Pro was not active. #18 (@dparker1005)</li>\n<li>BUG FIX: Set <code>new_version</code> on <code>no_update</code> entries so up-to-date Add Ons no longer trigger an undefined-property warning in WP-CLI and other consumers of the update transient. #18 (@dalemugford)</li>\n</ul><p>1.0.1 - 2025-11-12</p><ul>\n<li>BUG FIX: Fixed a deprecation warning when installing Add Ons from the Membership &gt; Add Ons screen. #16 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:77:\"http://license.paidmembershipspro.com/downloads/free/pmpro-update-manager.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"Update Manager\";}i:115;a:16:{s:4:\"Name\";s:40:\"Paid Memberships Pro - User Pages Add On\";s:5:\"Title\";s:40:\"Paid Memberships Pro - User Pages Add On\";s:9:\"PluginURI\";s:51:\"http://www.paidmembershipspro.com/pmpro-user-pages/\";s:4:\"Slug\";s:16:\"pmpro-user-pages\";s:6:\"plugin\";s:37:\"pmpro-user-pages/pmpro-user-pages.php\";s:7:\"Version\";s:5:\"0.7.2\";s:11:\"Description\";s:88:\"When a user signs up, create a page for them that only they (and admins) have access to.\";s:12:\"Installation\";s:443:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-user-pages</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Create an empty members page as the top level page for all user pages.</li>\n<li>Go to Memberships -&gt; User Pages in the dashboard to set the top level page and choose which levels should generate user pages.</li>\n</ol>\";s:3:\"FAQ\";s:309:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-user-pages/issues\">https://github.com/strangerstudios/pmpro-user-pages/issues</a></p>\";s:9:\"Changelog\";s:1526:\"<h4>Changelog</h4><p>0.7.2 - 2026-08-19</p><ul>\n<li>SECURITY: Added nonce verification when saving the User Pages settings. #29 (@flintfromthebasement)</li>\n<li>SECURITY: User pages can no longer be read through the REST API by users who do not have access to them. #29 (@flintfromthebasement)</li>\n</ul><p>0.7.1 - 2026-05-04</p><ul>\n<li>ENHANCEMENT: Localized the order confirmation message that links members to their most recent purchase page so the strings can be translated. #24 (@ipokkel)</li>\n<li>ENHANCEMENT: Wrapped the order page permalink and post title output in <code>esc_url()</code> and <code>esc_html()</code> in the confirmation message. #24 (@ipokkel)</li>\n</ul><p>0.7 - 2023-08-18</p><ul>\n<li>ENHANCEMENT: Added the <code>pmproup_allow_access_to_user_page</code> filter to adjust viewing restrictions for a user page. #14 (@andrewlimaza, @dparker1005)</li>\n<li>ENHANCEMENT: Added <code>&lt;span&gt;</code> tags around dates in the Account Page member links to allow styling that content. #13 (@kimwhite)</li>\n<li>BUG FIX/ENHANCEMENT: Now cleaning up user page data for users whose corresponding user page has been deleted. #12 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Improved compatibility with PMPro Multiple Memberships Per User Add On. #20 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Now creating sub-pages whenever a membership level is changed instead of only after checkouts. #20 (@dparker1005)</li>\n<li>BUG FIX/ENHANCEMENT: Updated localization and escaping of strings. #15 (@femiyb)</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:77:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-user-pages.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:10:\"User Pages\";}i:116;a:16:{s:4:\"Name\";s:46:\"Paid Memberships Pro - Variable Pricing Add On\";s:5:\"Title\";s:46:\"Paid Memberships Pro - Variable Pricing Add On\";s:9:\"PluginURI\";s:67:\"https://www.paidmembershipspro.com/add-ons/variable-pricing-add-on/\";s:4:\"Slug\";s:22:\"pmpro-variable-pricing\";s:6:\"plugin\";s:49:\"pmpro-variable-pricing/pmpro-variable-pricing.php\";s:7:\"Version\";s:5:\"1.0.1\";s:11:\"Description\";s:84:\"Allow customers to set their own price when checking out for your membership levels.\";s:12:\"Installation\";s:332:\"<p>Installation</p><ol>\n<li>Upload the <code>pmpro-variable-pricing</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>Edit the levels you want to add variable pricing to and set the \"Variable Pricing\" settings.</li>\n</ol>\";s:3:\"FAQ\";s:321:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-variable-pricing/issues\">https://github.com/strangerstudios/pmpro-variable-pricing/issues</a></p>\";s:9:\"Changelog\";s:388:\"<h4>Changelog</h4><p>1.0.1 - 2026-04-23</p><ul>\n<li>ENHANCEMENT: Added a \"Learn more\" documentation link to the Variable Pricing section on the Edit Membership Level page. #54 (@kimcoleman)</li>\n<li>BUG FIX: Fixed a PHP deprecation warning that may show on sites running PHP 8.5+ by replacing non-canonical <code>(double)</code> casts with <code>(float)</code>. #53 (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:83:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-variable-pricing.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:16:\"Variable Pricing\";}i:117;a:16:{s:4:\"Name\";s:30:\"Paid Memberships Pro - VAT Tax\";s:5:\"Title\";s:30:\"Paid Memberships Pro - VAT Tax\";s:9:\"PluginURI\";s:51:\"https://www.paidmembershipspro.com/add-ons/vat-tax/\";s:4:\"Slug\";s:13:\"pmpro-vat-tax\";s:6:\"plugin\";s:31:\"pmpro-vat-tax/pmpro-vat-tax.php\";s:7:\"Version\";s:5:\"0.8.5\";s:11:\"Description\";s:114:\"Calculate VAT tax at checkout and allow customers with a VAT Number lookup for VAT tax exemptions in EU countries.\";s:12:\"Installation\";s:572:\"<p>Installation</p><ol>\n<li>Make sure you have the Paid Memberships Pro plugin installed and activated.</li>\n<li>Upload the <code>pmpro-vat-tax</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the <code>Plugins</code> menu in WordPress.</li>\n<li>Update your payment settings to make sure you are collecting billing address at checkout.</li>\n<li>If you are using a gateway like PayPal Express that doesn\'t collect a billing address, install and activate the Add Address for Free Levels addon.</li>\n</ol>\";s:3:\"FAQ\";s:692:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the GitHub issue tracker here: <a href=\"https://github.com/strangerstudios/pmpro-vat-tax/issues\">https://github.com/strangerstudios/pmpro-vat-tax/issues</a></p>\n<p>For immediate help, also post to our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:308:\"<h4>Changelog</h4><p>0.8.5 - 2026-03-12</p><ul>\n<li>ENHANCEMENT: Improved the detection of recurring orders during <code>pmprovat_pmpro_added_order()</code>. #78 (@dparker1005)</li>\n<li>REFACTOR: Removed a deprecated call to the core <code>pmpro_doing_webhook()</code> function. #78 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:74:\"http://license.paidmembershipspro.com/downloads/standard/pmpro-vat-tax.zip\";s:7:\"License\";s:8:\"standard\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:7:\"VAT Tax\";}i:118;a:16:{s:4:\"Name\";s:41:\"Paid Memberships Pro - WooCommerce Add On\";s:5:\"Title\";s:41:\"Paid Memberships Pro - WooCommerce Add On\";s:9:\"PluginURI\";s:61:\"https://www.paidmembershipspro.com/add-ons/pmpro-woocommerce/\";s:4:\"Slug\";s:17:\"pmpro-woocommerce\";s:6:\"plugin\";s:39:\"pmpro-woocommerce/pmpro-woocommerce.php\";s:7:\"Version\";s:6:\"1.10.1\";s:11:\"Description\";s:48:\"Integrate Paid Memberships Pro With WooCommerce.\";s:12:\"Installation\";s:2059:\"<p>Installation</p><p>Note: You must have <a href=\"https://www.paidmembershipspro.com\">Paid Memberships Pro</a> and <a href=\"https://wordpress.org/plugins/woocommerce/\">WooCommerce</a> installed and activated on your site.</p>\n<h3>Install PMPro WooCommerce from within WordPress</h3>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"PMPro WooCommerce\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"Paid Memberships Pro - WooCommerce Add On\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>Install PMPro WooCommerce Manually</h3>\n<ol>\n<li>Upload the <code>pmpro-woocommerce</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"Paid Memberships Pro - WooCommerce\" through the \"Plugins\" menu in WordPress</li>\n<li>Go to \"after activation\" below.</li>\n</ol>\n<h3>After Activation: Configure Plugin Settings</h3><p>Create a Membership Product</p><ol>\n<li>Edit a product or add a new product.</li>\n<li>Select the \"Membership\" tab in the \"Product Data\" metabox.</li>\n<li>Select a level from the \"Membership Product\" dropdown.</li>\n<li>Save changes.</li>\n</ol><p>Set Member Discount Pricing on a Product</p><ol>\n<li>Edit a product or add a new product.</li>\n<li>Select the \"Membership\" tab in the \"Product Data\" metabox.</li>\n<li>Set a price for one or more levels in the \"Member Discount Pricing\" section.</li>\n<li>Save changes.</li>\n</ol><p>Set a Global Shop Discount for Members</p><ol>\n<li>Edit a membership level under Membership &gt; Settings.</li>\n<li>Locate the \"Set Membership Discount\" section.</li>\n<li>Add a percent discount to the field.</li>\n<li>Save changes.</li>\n</ol>\n<p>Visit our documentation site to <a href=\"https://www.paidmembershipspro.com/add-ons/pmpro-woocommerce/?utm_source=plugin&amp;utm_medium=readme&amp;utm_campaign=pmpro-woocommerce\">learn more about the settings, access custom code recipes and tutorials, and view a list of compatibility with other Paid Memberships Pro Add Ons</a>.</p>\";s:3:\"FAQ\";s:311:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-woocommerce/issues\">https://github.com/strangerstudios/pmpro-woocommerce/issues</a></p>\";s:9:\"Changelog\";s:997:\"<h4>Changelog</h4><p>1.10.1 - 2026-05-14</p><ul>\n<li>ENHANCEMENT: Inherit pmpro-woocommerce option values on multisite subsites. Membership product levels, gift codes, member discounts, and \"discounts on subscriptions\" are now read from the main site when pmpro-network-subsite is active and in \"inherit\" mode. #213 (@dparker1005)</li>\n<li>ENHANCEMENT: Added a \"Learn More\" link to the Add On documentation in the WooCommerce product data panel and the Edit Membership Level screen, and cleaned up settings formatting. #211 (@kimcoleman)</li>\n<li>BUG FIX: Added a null guard for the <code>$pmprowoo_product_levels</code> global to prevent a fatal error when <code>pmprowoo_get_membership_price()</code> is called before <code>pmprowoo_init()</code> has run. #212 (@flintfromthebasement)</li>\n<li>BUG FIX: Skip order items whose product no longer exists when granting memberships from an order, preventing a fatal in <code>pmprowoo_add_membership_from_order()</code>. #207 (@dparker1005)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:35:\"https://www.paidmembershipspro.com/\";s:8:\"Download\";s:74:\"http://license.paidmembershipspro.com/downloads/free/pmpro-woocommerce.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:11:\"WooCommerce\";}i:119;a:16:{s:4:\"Name\";s:15:\"WP Activity Log\";s:5:\"Title\";s:15:\"WP Activity Log\";s:9:\"PluginURI\";s:45:\"https://melapress.com/wordpress-activity-log/\";s:4:\"Slug\";s:21:\"wp-security-audit-log\";s:6:\"plugin\";s:47:\"wp-security-audit-log/wp-security-audit-log.php\";s:7:\"Version\";s:5:\"5.5.2\";s:11:\"Description\";s:280:\"Identify WordPress security issues before they become a problem. Keep track of everything happening on your WordPress, including users activity. Similar to Linux Syslog, WP Activity Log generates an activity log with a record of everything that happens on your WordPress websites.\";s:12:\"Installation\";s:0:\"\";s:3:\"FAQ\";s:5577:\"<p>Frequently Asked Questions</p><p>Does the free edition of WP Activity Log limit the data it collects?</p><p>No, the free edition does not limit the data the plugin collects whatsoever. All events logged by the premium edition are available in the free edition. The premium edition adds additional features such as extensive log filtering options, external database/log management service integration, user session management, and much more.</p><p>How long does WP Activity Log keep data for?</p><p>Log data can be kept indefinitely in both free and premium editions. By default, the plugin retains all audit logging data for 3 months however this can be changed from the initial configuration wizards or the plugin\'s settings (<a href=\"https://melapress.com/support/kb/wp-activity-log-retention-policies/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">activity log retention policies</a>).</p><p>Where does the plugin store the log?</p><p>By default, the log is stored in the WordPress database. WP Activity Log Enterprise edition includes an option to save the activity log to an external database and log mirroring to AWS Cloudwatch, Loggly, Papertrail, Syslog, &amp; other SIEMs</p><p>Can the log be exported?</p><p>Yes, the <a href=\"https://melapress.com/support/kb/wp-activity-log-data-export/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">log can easily be exported as either CSV or HTML</a>. The reports module in the Premium plugin is required for this functionality.</p><p>How does WP Activity Log Improve Security?</p><p>WP Activity Log keeps a record of security-related user and system activities, including logins, logouts, failed login attempts, changes to settings and configurations, and post edits among other things. This security log can not only uncover suspicious or untoward behaviour, but also aid in forensics and post-mortems for quicker recoveries.</p><p>Who can view the activity log?</p><p>By default, all users with administrator role can view the activity log. However, you can restrict this to a specific administrator or access can be given to other users through the plugin\'s settings. Refer to the <a href=\"https://melapress.com/support/kb/wp-activity-log-managing-plugin-privileges/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">WordPress activity log privileges</a> for more information on how you can do this.</p><p>Does the plugin send any log data to Melapress?</p><p>No, the plugin does not send any log data to us whatsoever. The only data we receive is license data from the premium edition of the plugin.</p><p>Does the plugin receive updates?</p><p>We update the plugin fairly regularly to ensure the plugin continues to run in tip-top shape while adding new features from time to time.</p><p>Will WP Activity Log slow down my website?</p><p><a href=\"https://melapress.com/support/kb/wp-activity-log-slow-down-website/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">WP Activity Log will not slow down your website</a>. Each version is tested before release to ensure it works in the best way possible. Having said that, you need to make sure your WordPress web server has adequate resources to manage the load of your website.</p><p>How do I get support?</p><p>Support for the Free edition of the plugin is provided only via the WordPress.org support forums. You can also refer to our <a href=\"https://melapress.com/support/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">support pages</a> for all the technical and product documentation.</p>\n<p>If you are using the Premium edition, you get direct access to our support team via one-to-one <a href=\"https://melapress.com/support/submit-ticket/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">email support</a>.</p><p>How can I report security bugs?</p><p>You can report security bugs through the Patchstack Vulnerability Disclosure Program. Please use this <a href=\"https://patchstack.com/database/vdp/wp-security-audit-log\">form</a>. For more details, please refer to our <a href=\"https://melapress.com/plugins-security-program/\">Melapress plugins security program</a>.</p><p>How does WP Activity Log compare to competitors?</p><p>WP Activity Log stands out as one of the most detailed WordPress activity logging solutions on the market. Unlike many competitors, it offers:</p>\n<ul>\n<li><strong>Unlimited log retention</strong> â€“ keep a complete history of all user and system activity without arbitrary limits  </li>\n<li><strong>Detailed event information</strong> â€“ see who made each change, when it happened, and from which IP address  </li>\n<li><strong>Feature-rich monitoring</strong> â€“ including real-time activity tracking, user session management, advanced reporting, alerts, and support for a wide range of third-party plugins  </li>\n<li><strong>Vulnerability Disclosure Program</strong> â€“ through Patchstack, we allow security researchers to report vulnerabilities responsibly, helping us address potential issues quickly and maintain a secure plugin for all users  </li>\n</ul>\n<p>These capabilities make WP Activity Log a <strong>comprehensive solution for site security, troubleshooting, and compliance</strong>, helping administrators and security teams maintain full visibility over their WordPress websites and multisite networks.</p>\";s:9:\"Changelog\";s:2442:\"<h4>Changelog</h4><p>5.5.2 (2025-10-22)</p><ul>\n<li>\n<p><strong>New activity Log event IDs for Paid Membership Pro</strong></p>\n<ul>\n<li>ID 9501 - A membership level was created</li>\n<li>ID 9502 - A membership level was permanently deleted.</li>\n<li>ID 9504 - A membership level was assigned to a user.</li>\n<li>ID 9505 - A membership level was removed from a user.</li>\n<li>We also added a number of event IDs for Paid Membership Pro that are only available in Premium. Refer to the <a href=\"https://melapress.com/support/kb/wp-activity-log-list-event-ids/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">list of WordPress activity log event IDs</a> for the complete list.</li>\n</ul>\n</li>\n<li>\n<p><strong>New New activity Log event IDs for WordPress</strong></p>\n<ul>\n<li>ID 5032 - A plugin update available</li>\n<li>ID 5033 - A theme update available</li>\n<li>ID 6079 - WordPress core update available.</li>\n<li>ID 2134 - User accessed a password protected post.</li>\n<li>ID 2135 - Failed attempt to access a password protected post.</li>\n</ul>\n</li>\n<li>\n<p><strong>New features</strong></p>\n<ul>\n<li>New buttons in the activity log viewer to copy event details to the clipboard.</li>\n<li>Added a Members Activity panel area inside the Members details page in Paid Memberships PRO that allows the admin to view the activity of each user. (PREMIUM)</li>\n</ul>\n</li>\n<li>\n<p><strong>Plugin &amp; functiontionality improvements</strong></p>\n<ul>\n<li>Updated the translations build process so that .po files are now merged with new strings without removing existing translations.</li>\n<li>Organized the Report sections settings in alphabetical order.</li>\n</ul>\n</li>\n<li>\n<p><strong>Bug fixes</strong></p>\n<ul>\n<li>Fixed a conflict with User Switch plugin which was breaking the process of switching back and forth through users.</li>\n<li>Fixed a number of spelling mistakes in the wizard.</li>\n<li>Fixed an issue where certain Yoast SEO plugin event IDs would not remain enabled after a user enables them and saves the settings.</li>\n</ul>\n</li>\n</ul>\n<p>Refer to the complete <a href=\"https://melapress.com/support/kb/wp-activity-log-plugin-changelog/?utm_source=wp+repo&amp;utm_medium=repo+link&amp;utm_campaign=wordpress_org&amp;utm_content=wsal\">plugin changelog</a> for more detailed information about what was new, improved and fixed in previous version updates of WP Activity Log.</p>\";s:6:\"Author\";s:9:\"Melapress\";s:9:\"AuthorURI\";s:22:\"https://melapress.com/\";s:8:\"Download\";s:64:\"https://downloads.wordpress.org/plugin/wp-security-audit-log.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:15:\"WP Activity Log\";}i:120;a:16:{s:4:\"Name\";s:63:\"Paid Memberships Pro - WP Affiliate Platform Integration Add On\";s:5:\"Title\";s:63:\"Paid Memberships Pro - WP Affiliate Platform Integration Add On\";s:9:\"PluginURI\";s:83:\"https://www.paidmembershipspro.com/add-ons/pmpro-wp-affiliate-platform-integration/\";s:4:\"Slug\";s:27:\"pmpro-wp-affiliate-platform\";s:6:\"plugin\";s:59:\"pmpro-wp-affiliate-platform/pmpro-wp-affiliate-platform.php\";s:7:\"Version\";s:5:\"1.7.3\";s:11:\"Description\";s:70:\"Process an affiliate via WP Affiliate Platform after a PMPro checkout.\";s:12:\"Installation\";s:457:\"<p>Installation</p><ol>\n<li>Make sure that WP-Affiliate-Platform is activated and setup correctly.</li>\n<li>Upload the <code>pmpro-wp-affiliate-platform</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>That\'s it! All orders from affiliates will have their affiliate id tracked in the PMPro order and will kick off conversions in WPAP.</li>\n</ol>\";s:3:\"FAQ\";s:331:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-wp-affiliate-platform/issues\">https://github.com/strangerstudios/pmpro-wp-affiliate-platform/issues</a></p>\";s:9:\"Changelog\";s:318:\"<h4>Changelog</h4><p>1.7.3 - 2023-01-05</p><ul>\n<li>ENHANCEMENT: Improved sanitization and escaping.</li>\n<li>BUG FIX: Fixed an issue where emails would not send when Paid Memberships Pro - WP Affiliate Platform Add On installed but WP Affiliate Platform was not/incorrectly configured. (@sc0ttkclark, @jjj)</li>\n</ul>\";s:6:\"Author\";s:36:\"Stranger Studios, Tips and Tricks HQ\";s:9:\"AuthorURI\";s:30:\"http://www.strangerstudios.com\";s:8:\"Download\";s:85:\"https://license.paidmembershipspro.com/downloads/free/pmpro-wp-affiliate-platform.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:33:\"WP Affiliate Platform Integration\";}i:121;a:16:{s:4:\"Name\";s:38:\"WP Bouncer - Limit Simultaneous Logins\";s:5:\"Title\";s:38:\"WP Bouncer - Limit Simultaneous Logins\";s:9:\"PluginURI\";s:54:\"https://www.paidmembershipspro.com/add-ons/wp-bouncer/\";s:4:\"Slug\";s:10:\"wp-bouncer\";s:6:\"plugin\";s:25:\"wp-bouncer/wp-bouncer.php\";s:7:\"Version\";s:5:\"1.5.1\";s:11:\"Description\";s:93:\"Deter members from sharing login credentials: restrict simultaneous logins for the same user.\";s:12:\"Installation\";s:773:\"<p>Installation</p><p>***Install WP Bouncer from within WordPress</p>\n<ol>\n<li>Visit the plugins page within your dashboard and select \"Add New\"</li>\n<li>Search for \"WP Bouncer\"</li>\n<li>Locate this plugin and click \"Install\"</li>\n<li>Activate \"WP Bouncer\" through the \"Plugins\" menu in WordPress</li>\n</ol>\n<p>***Install WP Bouncer Manually</p>\n<ol>\n<li>Upload the <code>wp-bouncer</code> folder to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate \"WP Bouncer\" through the \"Plugins\" menu in WordPress</li>\n</ol>\n<p>***Settings</p>\n<p>There are no settings for this plugin. If you want to modify the default behavior to instead enable JavaScript checks, add the following code to your wp-config.php:</p>\n<p>define( \'WP_BOUNCER_HEARTBEAT_CHECK\', true );</p>\";s:3:\"FAQ\";s:322:\"<p>Frequently Asked Questions</p><p>I need something strong to keep people from sharing accounts.</p><p>We\'ve found that using a 2-Factor-Authentication scheme on your site is a good way to keep people from sharing accounts. When we tried to design an advanced version of WP-Bouncer, it was basically 2FA. So try that.</p>\";s:9:\"Changelog\";s:427:\"<h4>Changelog</h4><p>1.5.1 - 2023-01-30</p><ul>\n<li>ENHANCEMENT: Added filter <code>wp_bouncer_ajax_timeout</code> to adjust timeout (default 5000).</li>\n<li>ENHANCEMENT: Added support for translations.</li>\n<li>BUG FIX: Removed unused login warning file and screenshot from the SVN repository that is not used in this plugin.</li>\n<li>BUG FIX: Fixed misspelled constant for plugin version and usage in JS file load.</li>\n</ul>\";s:6:\"Author\";s:16:\"Stranger Studios\";s:9:\"AuthorURI\";s:31:\"https://www.strangerstudios.com\";s:8:\"Download\";s:53:\"https://downloads.wordpress.org/plugin/wp-bouncer.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:1;s:9:\"ShortName\";s:38:\"WP Bouncer - Limit Simultaneous Logins\";}i:122;a:16:{s:4:\"Name\";s:14:\"WP Fusion Lite\";s:5:\"Title\";s:14:\"WP Fusion Lite\";s:9:\"PluginURI\";s:21:\"https://wpfusion.com/\";s:4:\"Slug\";s:14:\"wp-fusion-lite\";s:6:\"plugin\";s:33:\"wp-fusion-lite/wp-fusion-lite.php\";s:7:\"Version\";s:8:\"3.46.3.1\";s:11:\"Description\";s:94:\"WP Fusion Lite synchronizes your WordPress users with your CRM or marketing automation system.\";s:12:\"Installation\";s:398:\"<p>Installation</p><p>Upload and activate the plugin, then go to Settings &gt;&gt; WP Fusion. Select your desired CRM, enter your API credentials and click \"Connect\" to verify the connection.</p>\n<p>For CRM-specific setup information, see our <a href=\"https://wpfusion.com/documentation/getting-started/installation-guide/?utm_campaign=free-plugin&amp;utm_source=wp-org\">Installation Guide</a>.</p>\";s:3:\"FAQ\";s:3567:\"<p>Frequently Asked Questions</p><p>Who is it for?</p><p>WP Fusion is built for anyone using a <a href=\"https://wpfusion.com/documentation/faq/crm-compatibility-table/?utm_campaign=free-plugin&amp;utm_source=wp-org\">CRM or marketing automation platform</a>, and running their website with WordPress.</p>\n<p>CRMs empower businesses to track leads, send email broadcasts, manage contact data, track sales, delegate client relationships between employees, and more.</p>\n<p>WordPress handles the public facing side of your business: your sales pages, ecommerce platform, support forums, photos and videos, and anything else you want the world to see.</p>\n<p><strong>But your CRM and WordPress donâ€™t talk to each other.</strong></p>\n<p><strong>This is where WP Fusion comes in.</strong></p>\n<p>WP Fusion acts as a bridge between your WordPress data and CRM dataâ€” it allows you to use data from WordPress to power your marketing campaigns, and data from your CRM to personalize the customer experience in WordPress.</p><p>How is it different from Zapier?</p><p>While WP Fusion and Zapier are both integration tools, they work quite differently.</p>\n<p>Zapier is a SaaS (Software as a Service) solution that acts as a middleman between your site and your CRM (as well as many other platforms).</p>\n<p>When something is updated in WordPress, it is synced to Zapierâ€™s website, and then Zapier syncs the data on to your desired platform. Depending on your plan there is a delay before the data is synced, and/or limit on how many â€œtasksâ€ you can run each month.</p>\n<p><strong>WP Fusion connects your site directly to your CRM or marketing automation platform</strong> over the API (nothing goes through our website). Because of this the sync of data is instant, secure, and there are no monthly limits.</p>\n<p>In addition to syncing data with your CRM, WP Fusion also includes many options for <a href=\"https://wpfusion.com/documentation/getting-started/access-control/?utm_campaign=free-plugin&amp;utm_source=wp-org\">protecting your WordPress content based on CRM tags</a>, and triggering changes in membership level or course enrollments based on CRM automations. This generally isnâ€™t possible with Zapier because Zapier is configured via zapier.com, not inside your WordPress dashboard.</p><p>Why are your version numbers so funny?</p><p>WP Fusion Lite is a copy of the Pro WP Fusion plugin, with support for third-party plugins removed. Each time we release a Lite update, it brings it up to date with the latest version of the Pro plugin. For the full details <a href=\"https://wpfusion.com/documentation/faq/changelog/?utm_campaign=free-plugin&amp;utm_source=wp-org\">see the changelog on our site</a>.</p><p>Can I disable the upgrade nags?</p><p>WP Fusion Lite has a few banners on the settings pages with additional info about the features available in the Pro version.</p>\n<p>If you\'d prefer not to see these you can disable them with the filter:</p>\n<p><code>add_filter( \'wp_fusion_hide_upgrade_nags\', \'__return_true\' );</code></p><p>How can I report security bugs?</p><p>You can report security bugs through the Patchstack Vulnerability Disclosure Program. The Patchstack team help validate, triage and handle any security vulnerabilities. <a href=\"https://patchstack.com/database/vdp/wp-fusion-lite\">Report a security vulnerability.</a></p><p>Where can I find the source code?</p><p>The source code and build files for WP Fusion Lite are available on <a href=\"https://github.com/verygoodplugins/wp-fusion-lite\">GitHub</a>.</p>\";s:9:\"Changelog\";s:119:\"<h4>Changelog</h4><p>3.46.3.1 - 7/5/2025</p><ul>\n<li>Fixed Klaviyo deactivate URL not working in Lite plugin</li>\n</ul>\";s:6:\"Author\";s:17:\"Very Good Plugins\";s:9:\"AuthorURI\";s:28:\"https://verygoodplugins.com/\";s:8:\"Download\";s:57:\"https://downloads.wordpress.org/plugin/wp-fusion-lite.zip\";s:7:\"License\";s:13:\"wordpress.org\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:14:\"WP Fusion Lite\";}i:123;a:16:{s:4:\"Name\";s:36:\"Paid Memberships Pro - Zapier Add On\";s:5:\"Title\";s:36:\"Paid Memberships Pro - Zapier Add On\";s:9:\"PluginURI\";s:56:\"https://www.paidmembershipspro.com/add-ons/pmpro-zapier/\";s:4:\"Slug\";s:12:\"pmpro-zapier\";s:6:\"plugin\";s:29:\"pmpro-zapier/pmpro-zapier.php\";s:7:\"Version\";s:5:\"1.2.4\";s:11:\"Description\";s:83:\"Integrate activity on your membership site with thousands of other apps via Zapier.\";s:12:\"Installation\";s:460:\"<p>Installation</p><p>Prerequisites</p><ol>\n<li>Create a Zapier account at <a href=\"http://zapier.com\">http://zapier.com</a></li>\n</ol><p>Download, Install and Activate!</p><ol>\n<li>Upload the <code>pmpro-zapier</code> directory to the <code>/wp-content/plugins/</code> directory of your site.</li>\n<li>Activate the plugin through the \'Plugins\' menu in WordPress.</li>\n<li>The settings page is at Memberships --&gt; PMPro Zapier in the WP dashboard.</li>\n</ol>\";s:3:\"FAQ\";s:547:\"<p>Frequently Asked Questions</p><p>I found a bug in the plugin.</p><p>Please post it in the issues section of GitHub and we\'ll fix it as soon as we can. Thanks for helping. <a href=\"https://github.com/strangerstudios/pmpro-zapier/issues\">https://github.com/strangerstudios/pmpro-zapier/issues</a></p><p>I need help installing, configuring, or customizing the plugin.</p><p>Please visit our premium support site at <a href=\"http://www.paidmembershipspro.com\">http://www.paidmembershipspro.com</a> for more documentation and our support forums.</p>\";s:9:\"Changelog\";s:573:\"<h4>Changelog</h4><p>1.2.4 - 2025-05-26</p><ul>\n<li>ENHANCEMENT: Pass back the user_id value when the add_member action was successful. (@dwanjuki)</li>\n<li>ENHANCEMENT: Added new filters for each action (receive data to PMPro) to allow further customizations. See <code>pmproz_after_add_member</code>, <code>pmproz_after_change_membership_level</code>, <code>pmproz_after_add_order</code> and <code>pmproz_after_update_order</code>(@dwanjuki)</li>\n<li>BUG FIX: Fixed an issue where the discount code was not being included in the order trigger data. (@dwanjuki)</li>\n</ul>\";s:6:\"Author\";s:20:\"Paid Memberships Pro\";s:9:\"AuthorURI\";s:34:\"https://www.paidmembershipspro.com\";s:8:\"Download\";s:69:\"http://license.paidmembershipspro.com/downloads/free/pmpro-zapier.zip\";s:7:\"License\";s:4:\"free\";s:18:\"HideFromAddOnsList\";i:0;s:9:\"ShortName\";s:6:\"Zapier\";}}','off'),(237,'pmpro_visits','a:9:{s:5:\"today\";i:7;s:8:\"thisdate\";s:10:\"2026-21-08\";s:4:\"week\";i:37;s:8:\"thisweek\";s:2:\"34\";s:5:\"month\";i:159;s:9:\"thismonth\";s:1:\"8\";s:3:\"ytd\";i:295;s:8:\"thisyear\";s:4:\"2026\";s:7:\"alltime\";i:295;}','auto'),(238,'pmpro_views','a:9:{s:5:\"today\";i:17;s:8:\"thisdate\";s:10:\"2026-21-08\";s:4:\"week\";i:207;s:8:\"thisweek\";s:2:\"34\";s:5:\"month\";i:686;s:9:\"thismonth\";s:1:\"8\";s:3:\"ytd\";i:1432;s:8:\"thisyear\";s:4:\"2026\";s:7:\"alltime\";i:1432;}','auto'),(239,'_transient_no_forms_displayed_bellow_content','1','on'),(240,'action_scheduler_migration_status','complete','auto'),(241,'as_has_wp_comment_logs','no','on'),(246,'_site_transient_traduttore-registry-plugins','O:8:\"stdClass\":2:{s:20:\"paid-memberships-pro\";a:1:{s:12:\"translations\";a:42:{i:0;a:7:{s:8:\"language\";s:2:\"af\";s:7:\"version\";s:3:\"1.0\";s:7:\"updated\";s:25:\"2024-11-26T08:35:37+00:00\";s:12:\"e